void GraphEdge::removeWeight() {
    has_weight = false;
    prepareGeometryChange();
    update();
}
QPointF GraphEdge::weightAnchor() const {
    if (!source || !dest) return QPointF();
    QPointF p1 = source->pos() - pos();
    QPointF p2 = dest->pos() - pos();
    QPointF delta = p2 - p1;
    qreal length = std::max<qreal>(1.0, std::hypot(delta.x(), delta.y()));
    QPointF offset(-delta.y() / length * 15, delta.x() / length * 15);
    return (p1 + p2) / 2 + offset;
}
QVariant GraphEdge::itemChange(GraphicsItemChange change, const QVariant& value) {
    if (change == ItemPositionHasChanged) {
        prepareGeometryChange();
    }
    return QGraphicsItem::itemChange(change, value);
}
QRectF GraphEdge::boundingRect() const {
    if (!source || !dest) return QRectF();
    QPointF p1 = source->pos() - pos();
    QPointF p2 = dest->pos() - pos();
    QRectF rect = QRectF(p1, p2).normalized().adjusted(-26, -26, 26, 26);
    if (has_weight) rect = rect.united(QRectF(weightAnchor() - QPointF(14, 10), QPointF(28, 20)));
    return rect;
}
void GraphEdge::adjust() {
    if (!source || !dest) return;
    prepareGeometryChange();
}
void GraphEdge::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    if (!source || !dest) return;
    painter->setRenderHint(QPainter::Antialiasing);
    painter->setPen(QPen(color, 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
    QPointF p1 = source->pos() - pos();
    QPointF p2 = dest->pos() - pos();
    QLineF line(p1, p2);
    if (line.length() <= 40.0) return;
    qreal rad = std::atan2(line.dy(), line.dx());
    QPointF s1 = p1 + QPointF(20 * std::cos(rad), 20 * std::sin(rad));
    QPointF s2 = p2 - QPointF(20 * std::cos(rad), 20 * std::sin(rad));
    painter->drawLine(s1, s2);
    bool drawHead = is_directed || is_bidirectional;
    if (drawHead) {
        qreal arrowSize = 12.0;
        QPointF arrowP1 = s2 - QPointF(arrowSize * std::cos(rad - M_PI / 6.0), arrowSize * std::sin(rad - M_PI / 6.0));
        QPointF arrowP2 = s2 - QPointF(arrowSize * std::cos(rad + M_PI / 6.0), arrowSize * std::sin(rad + M_PI / 6.0));
        QPolygonF arrowHead;
        arrowHead << s2 << arrowP1 << arrowP2;
        painter->setBrush(color);
        painter->setPen(QPen(color, 1));
        painter->drawPolygon(arrowHead);
    }
    if (is_bidirectional) {
        qreal arrowSize = 12.0;
        QPointF backP1 = s1 + QPointF(arrowSize * std::cos(rad - M_PI / 6.0), arrowSize * std::sin(rad - M_PI / 6.0));
        QPointF backP2 = s1 + QPointF(arrowSize * std::cos(rad + M_PI / 6.0), arrowSize * std::sin(rad + M_PI / 6.0));
        QPolygonF backHead;
        backHead << s1 << backP1 << backP2;
        painter->setBrush(color);
        painter->setPen(QPen(color, 1));
        painter->drawPolygon(backHead);
    }
    if (has_weight) {
        QPointF anchor = weightAnchor();
        painter->setPen(QPen(color.lighter(140), 2));
        painter->drawRoundedRect(QRectF(anchor.x() - 13, anchor.y() - 10, 26, 20), 4, 4);
        painter->setBrush(color);
        painter->drawRoundedRect(QRectF(anchor.x() - 13, anchor.y() - 10, 26, 20), 4, 4);
        painter->setPen(QColor(255, 255, 255));
        painter->setFont(QFont("Consolas", 10, QFont::Bold));
        painter->drawText(QRectF(anchor.x() - 13, anchor.y() - 10, 26, 20), Qt::AlignCenter, QString::number(weight));
    }
}

