void IModule::playSwapAnim(ArrayBlock* b1, ArrayBlock* b2, int val1, int val2) {
    if (!b1 || !b2 || !m_scene) return;
    if (m_animated) {
        b1->showValue = false;
        b1->update();
        b2->showValue = false;
        b2->update();
        FloatingText* t1 = new FloatingText(QString::number(val1));
        FloatingText* t2 = new FloatingText(QString::number(val2));
        t1->setPos(b1->pos());
        t2->setPos(b2->pos());
        m_scene->addItem(t1);
        m_scene->addItem(t2);
        QVariantAnimation* anim = new QVariantAnimation();
        anim->setDuration(500);
        anim->setStartValue(0.0);
        anim->setEndValue(1.0);
        anim->setEasingCurve(QEasingCurve::InOutQuad);
        QPointF p1 = b1->pos();
        QPointF p2 = b2->pos();
        QObject::connect(anim, &QVariantAnimation::valueChanged, [t1, t2, p1, p2](const QVariant& value) {
            qreal t = value.toReal();
            qreal arc = std::sin(t * M_PI) * 40.0;
            t1->setPos(p1.x() + (p2.x() - p1.x()) * t, p1.y() - arc);
            t2->setPos(p2.x() + (p1.x() - p2.x()) * t, p2.y() + arc);
        });
        QObject::connect(anim, &QVariantAnimation::finished, [this, b1, b2, t1, t2, val1, val2]() {
            m_scene->removeItem(t1);
            m_scene->removeItem(t2);
            delete t1;
            delete t2;
            b1->value = val2;
            b2->value = val1;
            b1->showValue = true;
            b1->update();
            b2->showValue = true;
            b2->update();
        });
        anim->start(QAbstractAnimation::DeleteWhenStopped);
    } else {
        b1->value = val2;
        b2->value = val1;
        b1->showValue = true;
        b1->update();
        b2->showValue = true;
        b2->update();
    }
}

void IModule::playSwapAnim(ArrayBlock* b1, ArrayBlock* b2, int val1, int val2) {
    if (!b1 || !b2 || !m_scene) return;
    if (m_animated) {
        b1->showValue = false;
        b1->update();
        b2->showValue = false;
        b2->update();
        QPointer<FloatingText> t1 = new FloatingText(QString::number(val1));
        QPointer<FloatingText> t2 = new FloatingText(QString::number(val2));
        t1->setPos(b1->pos());
        t2->setPos(b2->pos());
        m_scene->addItem(t1.data());
        m_scene->addItem(t2.data());
        QVariantAnimation* anim = new QVariantAnimation();
        anim->setDuration(500);
        anim->setStartValue(0.0);
        anim->setEndValue(1.0);
        anim->setEasingCurve(QEasingCurve::InOutQuad);
        QPointF p1 = b1->pos();
        QPointF p2 = b2->pos();
        QObject::connect(anim, &QVariantAnimation::valueChanged, [t1, t2, p1, p2](const QVariant& value) {
            qreal t = value.toReal();
            qreal arc = std::sin(t * M_PI) * 40.0;
            if (t1) t1->setPos(p1.x() + (p2.x() - p1.x()) * t, p1.y() - arc);
            if (t2) t2->setPos(p2.x() + (p1.x() - p2.x()) * t, p2.y() + arc);
        });
        QObject::connect(anim, &QVariantAnimation::finished, [this, b1, b2, t1, t2, val1, val2]() {
            if (t1) {
                if (t1->scene()) t1->scene()->removeItem(t1.data());
                delete t1.data();
            }
            if (t2) {
                if (t2->scene()) t2->scene()->removeItem(t2.data());
                delete t2.data();
            }
            b1->value = val2;
            b2->value = val1;
            b1->showValue = true;
            b1->update();
            b2->showValue = true;
            b2->update();
        });
        anim->start(QAbstractAnimation::DeleteWhenStopped);
    } else {
        b1->value = val2;
        b2->value = val1;
        b1->showValue = true;
        b1->update();
        b2->showValue = true;
        b2->update();
    }
}

void IModule::playShiftAnim(ArrayBlock* src, ArrayBlock* dst, int val, QColor targetColor, bool pulseDst) {
    if (!src || !dst || !m_scene) return;
    if (m_animated) {
        src->showValue = false;
        src->color = QColor(200, 200, 200);
        src->update();
        FloatingText* ft = new FloatingText(QString::number(val));
        ft->setPos(src->pos());
        m_scene->addItem(ft);
        QPropertyAnimation* anim = new QPropertyAnimation(ft, "pos");
        anim->setEndValue(dst->pos());
        anim->setDuration(300);
        anim->setEasingCurve(QEasingCurve::InOutQuad);
        QObject::connect(anim, &QPropertyAnimation::finished, [this, dst, ft, val, targetColor, pulseDst]() {
            m_scene->removeItem(ft);
            delete ft;
            dst->value = val;
            dst->showValue = true;
            dst->color = targetColor;
            dst->update();
            if (pulseDst) playScaleAnim(dst);
        });
        anim->start(QAbstractAnimation::DeleteWhenStopped);
    } else {
        src->showValue = false;
        src->color = QColor(200, 200, 200);
        src->update();
        dst->value = val;
        dst->showValue = true;
        dst->color = targetColor;
        dst->update();
    }
}

