int DSUBasicModule::find(std::vector<int>& parent, int x) {
    int root = x;
    int guard = 0;
    while (parent[root] != root && guard <= (int)parent.size()) {
        root = parent[root];
        guard++;
    }
    if (parent[root] != root) return x;
    while (parent[x] != x) {
        int nxt = parent[x];
        parent[x] = root;
        x = nxt;
    }
    return root;
}

