struct EdgeShot {
    QImage img;
    QPointF pa, pb;
};

static EdgeShot renderCase(bool directed, bool bidirectional) {
    QGraphicsScene scene;
    std::map<int, GraphNode*> nodes;
    std::map<std::pair<int,int>, GraphEdge*> edges;
    GraphModuleUtils::GraphOptions opt;
    opt.directed = directed;
    opt.bidirectional = bidirectional;
    GraphRenderHelper::buildNodes(&scene, nodes, 3, QPointF(300, 300), 140);
    GraphRenderHelper::buildEdges(&scene, nodes, edges, {GraphModuleUtils::EdgeInput{1,2,0}}, opt, false);
    scene.setSceneRect(-100, -100, 900, 600);
    QImage img(900, 600, QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    scene.render(&p, QRectF(-100, -100, 900, 600), QRectF(-100, -100, 900, 600));
    p.end();
    EdgeShot shot;
    shot.img = img;
    shot.pa = nodes[1]->pos();
    shot.pb = nodes[2]->pos();
    return shot;
}

static int countDark(const QImage& img, QRectF region) {
    int n = 0;
    QRect r = region.toRect().intersected(img.rect());
    for (int y = r.top(); y <= r.bottom(); ++y)
        for (int x = r.left(); x <= r.right(); ++x) {
            QColor c = img.pixelColor(x, y);
            if (c.red() < 120 && c.green() < 120 && c.blue() < 120) n++;
        }
    return n;
}

static int ringA(const EdgeShot& s) { return countDark(s.img, QRectF(s.pa.x()-34, s.pa.y()-34, 68, 68)); }
static int ringB(const EdgeShot& s) { return countDark(s.img, QRectF(s.pb.x()-34, s.pb.y()-34, 68, 68)); }

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    EdgeShot plain   = renderCase(false, false);
    EdgeShot direct  = renderCase(true,  false);
    EdgeShot bidir   = renderCase(false, true);

    int plainA = ringA(plain),  plainB = ringB(plain);
    int directA = ringA(direct), directB = ringB(direct);
    int bidirA = ringA(bidir),  bidirB = ringB(bidir);

    printf("plain  A=%d B=%d\ndirect A=%d B=%d\nbidir  A=%d B=%d\n", plainA, plainB, directA, directB, bidirA, bidirB);

    check(directB > plainB + 30, "directed: arrowhead added at TARGET end");
    check(directA <= plainA + 10, "directed: no arrowhead at SOURCE end");
    check(bidirA > plainA + 30, "bidirectional: arrowhead added at SOURCE end");
    check(bidirB > plainB + 30, "bidirectional: arrowhead added at TARGET end");

    printf(failures == 0 ? "ALL ARROW TESTS PASSED\n" : "ARROW TESTS HAD FAILURES\n");
    return failures == 0 ? 0 : 1;
}

