    QTextEdit* input = w.findChild<QTextEdit*>();
    QGroupBox* graphBox = w.findChild<QGroupBox*>();
    QPushButton* btnAuto = findAuto(&w);
    QPushButton* btnBuild = nullptr, *btnRun = nullptr, *btnStep = nullptr;
    for (QPushButton* b : w.findChildren<QPushButton*>()) {
        if (b->text().contains("绘制")) btnBuild = b;
        if (b->text().contains("计算")) btnRun = b;
        if (b->text().contains("下一步")) btnStep = b;
    }
    check(combo && input && graphBox && btnAuto && btnBuild && btnRun && btnStep, "all widgets found");
    if (!combo || !input || !graphBox || !btnAuto || !btnBuild || !btnRun || !btnStep) return 1;

    int idxGraph = -1, idxNonGraph = -1;
    for (int i = 1; i < combo->count(); ++i) {
        QString name = combo->itemText(i);
        if (name.contains("BFS") && idxGraph < 0) idxGraph = i;
        if (name.contains("冒泡") && idxNonGraph < 0) idxNonGraph = i;
    }
    printf("graph module = %s | nonggraph module = %s\n", qPrintable(combo->itemText(idxGraph)), qPrintable(combo->itemText(idxNonGraph)));

    combo->setCurrentIndex(idxGraph);
    pump(150);
    check(graphBox->isVisible(), "graph options VISIBLE for graph module");
    check(input->placeholderText().contains("顶点数"), "graph placeholder mentions 顶点数");
    printf("graph placeholder:\n%s\n", qPrintable(input->placeholderText()));

    combo->setCurrentIndex(idxNonGraph);
    pump(150);
    check(!graphBox->isVisible(), "graph options HIDDEN for non-graph module");
    check(input->placeholderText().contains("数组长度"), "sort placeholder mentions 数组长度");
    printf("sort placeholder:\n%s\n", qPrintable(input->placeholderText()));

    combo->setCurrentIndex(idxGraph);
    pump(150);
    check(graphBox->isVisible(), "graph options VISIBLE again after switching back");

    check(btnAuto->text() == "自动播放", "auto button starts as 自动播放");

    btnBuild->click();
    pump(200);
    btnRun->click();
    pump(200);
    check(w.probeFrameCount() > 0, "frames recorded");
    printf("frame count = %d\n", w.probeFrameCount());

    w.probeStartAuto();
    pump(60);
    check(w.probeIsPlaying(), "auto play entered playing state");
    check(btnAuto->text() == "暂停", "button becomes 暂停 while playing");

    w.probeAdvance();
    pump(60);
    int afterAdvance = w.probeFrameIndex();
    check(afterAdvance >= 1, "auto advance moved frame index");

    w.probeRequestPause();
    pump(60);
    check(w.probePendingPause(), "pause request registered as pending");
    check(btnAuto->text() == "暂停中...", "button shows 暂停中 while settling");
    int beforeSettle = w.probeFrameIndex();
    w.probeAdvance();
    check(w.probeFrameIndex() == beforeSettle, "no further frame advance while pending pause");

    w.probeSettle();
    pump(60);
    check(!w.probeIsPlaying(), "playing stops after frame settles");
    check(btnAuto->text() == "自动播放", "button back to 自动播放 after pause");
    int pausedIndex = w.probeFrameIndex();

    btnStep->click();
    pump(60);
    check(w.probeFrameIndex() == pausedIndex + 1, "manual step advances index");

    w.probeStartAuto();
    pump(60);
    check(w.probeIsPlaying(), "resume enters playing state");
    check(btnAuto->text() == "暂停", "button becomes 暂停 again on resume");
    int resumeIndex = w.probeFrameIndex();
    w.probeAdvance();
    pump(60);
    check(w.probeFrameIndex() == resumeIndex + 1, "resume continues from CURRENT index, not old paused index");

    printf("\n%d failures\n", failures);
    return failures == 0 ? 0 : 1;
}

