// 第 1/7 条回归：反复切换模块 + 切换图选项不得崩溃（悬空指针）
static void crashRegression() {
    MainWindow w;
    w.resize(1200, 800);
    w.show();
    QComboBox* combo = w.findChild<QComboBox*>();
    QGroupBox* gb = w.findChild<QGroupBox*>();
    int bfs = -1, tarjan = -1, bubble = -1, kruskal = -1;
    for (int i = 1; i < combo->count(); ++i) {
        QString n = combo->itemText(i);
        if (n.contains("广度优先")) bfs = i;
        if (n.contains("强连通")) tarjan = i;
        if (n.contains("冒泡")) bubble = i;
        if (n.contains("Kruskal") || n.contains("最小生成")) kruskal = i;
    }
    int cycle[] = {bfs, tarjan, bubble, kruskal, bfs, bubble, bfs};
    for (int rep = 0; rep < 3; ++rep) {
        for (int idx : cycle) {
            if (idx < 0) continue;
            combo->setCurrentIndex(idx);
            pump(60);
            for (QPushButton* b : w.findChildren<QPushButton*>()) {
                if (b->text() == "绘制可视化效果") { b->click(); break; }
            }
            pump(80);
            for (QRadioButton* r : gb->findChildren<QRadioButton*>()) {
                if (r->text() == "有向图" && r->isEnabled()) { r->click(); break; }
            }
            pump(80);
            for (QRadioButton* r : gb->findChildren<QRadioButton*>()) {
                if (r->text() == "无向图") { r->click(); break; }
            }
            pump(80);
            for (QCheckBox* c : gb->findChildren<QCheckBox*>()) {
                if (c->isEnabled()) { c->click(); break; }
            }
            pump(80);
        }
    }
    printf("crash regression: no crash over %d module/option cycles\n", 3 * 7);
}

