    setFocusPolicy(Qt::StrongFocus);
    setCursor(Qt::PointingHandCursor);
    setAttribute(Qt::WA_Hover, true);
    setCheckable(true);
    setFont(UiTheme::uiFont(9, true));
    setSizePolicy(QSizePolicy::Fixed, QSizePolicy::Fixed);

    m_anim = new QPropertyAnimation(this, "checked", this);
    m_anim->setDuration(180);
    m_anim->setEasingCurve(QEasingCurve::OutCubic);
    connect(m_anim, &QPropertyAnimation::valueChanged, this, [this](const QVariant& v) {
        m_checked = v.toBool();
        update();
    });
}

void MyToggleSwitch::setChecked(bool on) {
    if (m_checked == on) {
        m_checked = on;
        update();
        return;
    }
    m_anim->stop();
    m_anim->setStartValue(m_checked ? 1.0 : 0.0);
    m_anim->setEndValue(on ? 1.0 : 0.0);
    m_anim->start();
    setCheckedInternal(on);
}

