}

QSize MyToggleSwitch::minimumSizeHint() const {
    return QSize(74, 32);
}

QRectF MyToggleSwitch::trackRect() const {
    return QRectF(0, (height() - 30) / 2.0, width(), 30);
}

QRectF MyToggleSwitch::knobRect(qreal t) const {
    QRectF track = trackRect();
    qreal knob = 24.0;
    qreal travel = track.width() - knob - 6.0;
    qreal x = track.left() + 3.0 + travel * t;
    return QRectF(x, track.top() + 3.0, knob, knob);
}

void MyToggleSwitch::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    QRectF track = trackRect();
    QRectF knob = knobRect(m_checked ? 1.0 : 0.0);

    QColor trackColor = m_hover ? UiTheme::trackOff().darker(106) : UiTheme::trackOff();
    if (m_checked) {
        QColor on = m_onColor;
        trackColor = m_hover ? on.lighter(108) : on;
    }

    painter.setPen(Qt::NoPen);
    painter.setBrush(trackColor);
    painter.drawRoundedRect(track, 15, 15);

    QColor knobColor = m_checked ? UiTheme::surface() : QColor(252, 252, 253);
    painter.setBrush(knobColor);
    painter.setPen(QPen(QColor(0, 0, 0, 26), 1));
    painter.drawEllipse(knob);

    QString label = m_checked ? m_onText : m_offText;
    if (label.isEmpty()) return;

    painter.setFont(font());
    QFontMetrics fm(font());
    int textWidth = fm.horizontalAdvance(label);
    bool labelInside = textWidth + 18 < knob.width();
    QColor labelColor = m_checked ? UiTheme::textOnAccent() : UiTheme::textSecondary();

    if (labelInside) {
        painter.setPen(labelColor);
        QRectF labelRect = track;
        if (m_checked) labelRect.setLeft(track.left() + 6);
        else labelRect.setRight(track.right() - 6);
        painter.drawText(labelRect, Qt::AlignCenter, label);
    } else {
        painter.setPen(m_checked ? QColor(255, 255, 255, 235) : UiTheme::textSecondary());
        painter.drawText(QRectF(0, 0, width(), height()), m_checked ? (Qt::AlignRight | Qt::AlignVCenter) : (Qt::AlignLeft | Qt::AlignVCenter), label);
    }
}

void MyToggleSwitch::enterEvent(QEnterEvent* event) {
    m_hover = true;
    update();
    QAbstractButton::enterEvent(event);
}

void MyToggleSwitch::leaveEvent(QEvent* event) {
    m_hover = false;
    update();
    QAbstractButton::leaveEvent(event);
}

void MyToggleSwitch::mousePressEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        toggle();
        event->accept();
        return;
    }
    QAbstractButton::mousePressEvent(event);
}

