    m_hover = false;
    update();
    QAbstractButton::leaveEvent(event);
}

void MyCheckBox::mousePressEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        setChecked(!m_checked);
        event->accept();
        return;
    }
    QAbstractButton::mousePressEvent(event);
}

