int MyComboBox::hitTest(const QPoint& globalPos) const {
    QPoint local = mapFromGlobal(globalPos);
    int itemHeight = 30;
    int top = 4;
    int index = (local.y() - top) / itemHeight;
    if (index < 0 || index >= m_items.size()) return -1;
