}

void MyComboBox::paintPopup(QPainter& painter, const QPoint& globalPos) {
    int itemHeight = 30;
    int popupWidth = qMax(width(), 140);
    int popupHeight = m_items.size() * itemHeight + 8;
    QPoint origin = mapToGlobal(QPoint(0, height() + 4));

    QRect screen = QGuiApplication::primaryScreen()->availableGeometry();
    if (origin.y() + popupHeight > screen.bottom()) origin.setY(mapToGlobal(QPoint(0, 0)).y() - popupHeight - 4);
    if (origin.x() + popupWidth > screen.right()) origin.setX(screen.right() - popupWidth);

    QRect popupRect(origin.x(), origin.y(), popupWidth, popupHeight);
    painter.setRenderHint(QPainter::Antialiasing);
    QPainterPath path;
    path.addRoundedRect(QRectF(popupRect).adjusted(0.5, 0.5, -0.5, -0.5), UiTheme::radiusMd(), UiTheme::radiusMd());
    painter.setPen(QPen(UiTheme::border(), 1));
    painter.setBrush(UiTheme::surface());
    painter.drawPath(path);

    painter.setFont(font());
    for (int i = 0; i < m_items.size(); ++i) {
        QRectF row(popupRect.left() + 4, popupRect.top() + 4 + i * itemHeight, popupWidth - 8, itemHeight);
        if (i == m_current) {
            painter.setPen(Qt::NoPen);
            painter.setBrush(UiTheme::accentSoft());
            painter.drawRoundedRect(row, UiTheme::radiusSm(), UiTheme::radiusSm());
        }
        painter.setPen(i == m_current ? UiTheme::accent().darker(115) : UiTheme::textPrimary());
        painter.drawText(row.adjusted(8, 0, -8, 0), Qt::AlignVCenter | Qt::AlignLeft, m_items[i]);
    }
}

void MyComboBox::mousePressEvent(QMouseEvent* event) {
    if (event->button() != Qt::LeftButton) {
        QAbstractButton::mousePressEvent(event);
        return;
    }
    QPoint global = event->globalPosition().toPoint();
    if (m_popupOpen) {
        int index = hitTest(global);
        if (index >= 0) selectIndex(index);
        else {
            m_popupOpen = false;
            update();
        }
        event->accept();
        return;
    }
    popup();
    event->accept();
}

void MyComboBox::keyPressEvent(QKeyEvent* event) {
    if (event->key() == Qt::Key_Down) {
        setCurrentIndex(m_current + 1 < m_items.size() ? m_current + 1 : 0);
        return;
    }
    if (event->key() == Qt::Key_Up) {
        setCurrentIndex(m_current - 1 >= 0 ? m_current - 1 : m_items.size() - 1);
        return;
    }
    QAbstractButton::keyPressEvent(event);
}

bool MyComboBox::event(QEvent* e) {
    if (m_popupOpen) {
        if (e->type() == QEvent::MouseButtonPress) {
            QMouseEvent* me = static_cast<QMouseEvent*>(e);
            QPoint global = me->globalPosition().toPoint();
            QRect popupRect(mapToGlobal(QPoint(0, height() + 4)), QSize(qMax(width(), 140), m_items.size() * 30 + 8));
            if (!popupRect.contains(global)) {
                m_popupOpen = false;
                update();
            }
        } else if (e->type() == QEvent::KeyPress) {
            QKeyEvent* ke = static_cast<QKeyEvent*>(e);
            if (ke->key() == Qt::Key_Escape) {
                m_popupOpen = false;
                update();
                return true;
            }
        }
    }
    return QAbstractButton::event(e);
}

