#include "SceneGrid.h"
#include "GraphElements.h"
#include <QPainter>
#include <QGraphicsSceneMouseEvent>
#include <cmath>

SceneGrid::Config g_gridConfig;

void SceneGrid::attach(QGraphicsScene* scene, const Config& config) {
    if (!scene) return;
    g_gridConfig = config;
    for (QGraphicsItem* item : scene->items()) {
        if (item->type() == QGraphicsItem::UserType + 77) {
            static_cast<GridSnapItem*>(item)->setConfig(config);
            return;
        }
    }
    GridSnapItem* grid = new GridSnapItem(scene);
    grid->setConfig(config);
}

QPointF SceneGrid::snap(const QPointF& pos, const Config& config) {
    if (!config.enabled || config.cell <= 0) return pos;
    qreal step = config.cell;
    return QPointF(std::round(pos.x() / step) * step, std::round(pos.y() / step) * step);
}

QLineF SceneGrid::nearestAxis(const QPointF& a, const QPointF& b, const Config& config) {
    qreal step = config.cell > 0 ? config.cell : 56.0;
    qreal dx = b.x() - a.x();
    qreal dy = b.y() - a.y();
    if (std::abs(dx) >= std::abs(dy)) {
        qreal targetY = std::round(a.y() / step) * step;
        return QLineF(a.x(), targetY, b.x(), targetY);
    }
    qreal targetX = std::round(a.x() / step) * step;
    return QLineF(targetX, a.y(), targetX, b.y());
}

QPolygonF SceneGrid::hexagonAt(const QPointF& center, qreal radius) {
    QPolygonF poly;
    for (int i = 0; i < 6; ++i) {
        qreal angle = M_PI / 6.0 + i * M_PI / 3.0;
        poly << QPointF(center.x() + radius * std::cos(angle), center.y() + radius * std::sin(angle));
    }
    return poly;
}

void SceneGrid::drawGuides(QPainter* painter, const QGraphicsScene* scene, const Config& config) {
    if (!painter || !scene || !config.showGuides) return;
    QRectF bounds = scene->itemsBoundingRect().adjusted(-400, -400, 400, 400);
    painter->setPen(QPen(config.enabled ? UiTheme::canvasGridAxis() : UiTheme::canvasGrid(), 1, Qt::DotLine));
    qreal step = config.cell > 0 ? config.cell : 56.0;
    for (qreal x = std::floor(bounds.left() / step) * step; x <= bounds.right(); x += step) {
        painter->drawLine(QPointF(x, bounds.top()), QPointF(x, bounds.bottom()));
    }
    for (qreal y = std::floor(bounds.top() / step) * step; y <= bounds.bottom(); y += step) {
        painter->drawLine(QPointF(bounds.left(), y), QPointF(bounds.right(), y));
    }
}

