void GridSnapItem::mousePressEvent(QGraphicsSceneMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        m_dragging = true;
        m_lastScenePos = event->scenePos();
        event->accept();
        return;
    }
    QGraphicsItem::mousePressEvent(event);
}

void GridSnapItem::mouseMoveEvent(QGraphicsSceneMouseEvent* event) {
    if (!m_dragging) {
        QGraphicsItem::mouseMoveEvent(event);
        return;
    }
    QPointF delta = event->scenePos() - m_lastScenePos;
    m_lastScenePos = event->scenePos();
    if (scene()) {
        for (QGraphicsItem* item : scene()->items()) {
            GraphNode* node = dynamic_cast<GraphNode*>(item);
            if (!node) continue;
            node->setPos(node->pos() + delta);
        }
    }
    event->accept();
}

void GridSnapItem::mouseReleaseEvent(QGraphicsSceneMouseEvent* event) {
    if (m_dragging) {
        m_dragging = false;
        event->accept();
        return;
    }
    QGraphicsItem::mouseReleaseEvent(event);
}

