static void analyze(const char* path, bool expectPanel) {
    QImage img(path);
    if (img.isNull()) { printf("FAIL: cannot load %s\n", path); failures++; return; }
    int accent = 0;
    int lightBlue = 0;
    int panelBox = 0;
    for (int y = 60; y < 260 && y < img.height(); ++y) {
        for (int x = 10; x < 320 && x < img.width(); ++x) {
            QColor c = img.pixelColor(x, y);
            if (c.blue() > 170 && c.red() < 130 && c.green() < 160) accent++;
            if (c.blue() > 235 && c.red() > 225 && c.green() > 230) lightBlue++;
            if (std::abs(c.red() - 246) < 6 && std::abs(c.green() - 248) < 6 && std::abs(c.blue() - 251) < 6) panelBox++;
        }
    }
    printf("%s: accent=%d lightBlue=%d panelSurface=%d\n", path, accent, lightBlue, panelBox);
    if (!expectPanel) {
        check(panelBox < 300, "no graph panel surface box in left column");
        check(accent < 200, "no accent-tinted block in left column at startup");
    } else {
        check(panelBox > 800, "graph panel surface present in left column");
    }
}

