    innerLayout->setContentsMargins(4, 4, 4, 4);
    innerLayout->setSpacing(0);
    layout->addWidget(inner);

    m_popup = frame;
    m_popupLayout = innerLayout;
    rebuildRows();

    int popupWidth = qMax(width(), 170);
    frame->setFixedWidth(popupWidth);
    frame->adjustSize();
    frame->setFixedWidth(popupWidth);

    QPoint origin = mapToGlobal(QPoint(0, height() + 4));
    int popupHeight = frame->sizeHint().height();
    QRect screen = QGuiApplication::primaryScreen()->availableGeometry();
    if (origin.y() + popupHeight > screen.bottom()) {
        origin.setY(mapToGlobal(QPoint(0, 0)).y() - popupHeight - 4);
    }
    if (origin.x() + popupWidth > screen.right()) {
        origin.setX(screen.right() - popupWidth);
    }
    frame->move(origin);

    connect(frame, &QWidget::destroyed, this, [this]() {
        m_popup = nullptr;
        m_popupLayout = nullptr;
        m_rows.clear();
        qApp->removeEventFilter(this);
    });
    frame->show();
    frame->raise();
    frame->activateWindow();

    qApp->installEventFilter(this);
}

