    painter->setRenderHint(QPainter::Antialiasing);
    painter->setBrush(color);
    painter->setPen(QPen(Qt::black, 2));
    painter->drawRect(0, 0, 60, 40);

    painter->setFont(QFont("Consolas", 14, QFont::Bold));
    if (showValue) {
        painter->drawText(QRectF(0, 0, 60, 40), Qt::AlignCenter, QString::number(value));
    }

    painter->setFont(QFont("Consolas", 12));
    QString topText = customLabel.isEmpty() ? QString::number(id) : customLabel;
    painter->drawText(QRectF(0, -25, 60, 20), Qt::AlignHCenter | Qt::AlignBottom, topText);
}

