void MyToggleSwitch::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setOpacity(0.25 + 0.75 * m_ratio);
    QRectF track = trackRect();
    QRectF knob = knobRect(m_position);

    QColor trackColor;
    if (m_position > 0.5) {
        QColor on = m_onColor;
        trackColor = on.lighter(100 + 8 * (1.0 - m_position));
    } else {
        trackColor = UiTheme::trackOff().lighter(100 + 8 * m_position);
    }
    if (m_hover) trackColor = trackColor.lighter(106);

    painter.setPen(Qt::NoPen);
    painter.setBrush(trackColor);
    painter.drawRoundedRect(track, 15, 15);

    QColor knobColor = m_position > 0.5 ? UiTheme::surface() : QColor(252, 252, 253);
    painter.setBrush(knobColor);
    painter.setPen(QPen(QColor(0, 0, 0, 24), 1));
    painter.drawEllipse(knob);

    QString label = m_position > 0.5 ? m_onText : m_offText;
    if (label.isEmpty()) return;

    painter.setFont(font());
    QFontMetrics fm(font());
    int textWidth = fm.horizontalAdvance(label);
    bool labelInside = textWidth + 16 < knob.width();
    QColor labelColor = m_position > 0.5 ? UiTheme::textOnAccent() : UiTheme::textSecondary();

    if (labelInside) {
        painter.setPen(labelColor);
        QRectF labelRect = track;
        if (m_position > 0.5) labelRect.setLeft(track.left() + 5);
        else labelRect.setRight(track.right() - 5);
        painter.drawText(labelRect, Qt::AlignCenter, label);
    } else {
        painter.setPen(m_position > 0.5 ? QColor(255, 255, 255, 240) : UiTheme::textSecondary());
        painter.drawText(QRectF(0, 0, width(), height()),
                         m_position > 0.5 ? (Qt::AlignRight | Qt::AlignVCenter) : (Qt::AlignLeft | Qt::AlignVCenter),
                         label);
    }
}

