void MyTextEdit::renderFrame() {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    QRectF box = QRectF(this->rect()).adjusted(0.5, 0.5, -0.5, -0.5);
    QPainterPath path;
    path.addRoundedRect(box, UiTheme::radiusMd(), UiTheme::radiusMd());
    painter.setPen(QPen(m_focused ? UiTheme::borderFocus() : UiTheme::border(), m_focused ? 1.6 : 1.0));
    painter.setBrush(UiTheme::surface());
    painter.drawPath(path);
}

void MyTextEdit::renderFrame() {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    QRectF box = QRectF(this->rect()).adjusted(0.5, 0.5, -0.5, -0.5);
    QPainterPath path;
    path.addRoundedRect(box, UiTheme::radiusMd(), UiTheme::radiusMd());
    QColor borderColor = m_focused ? UiTheme::borderFocus() : UiTheme::borderSoft();
    painter.setPen(QPen(borderColor, m_focused ? 1.8 : 1.2));
    painter.setBrush(UiTheme::surface());
    painter.drawPath(path);
    if (!m_focused) {
        painter.setPen(QPen(UiTheme::accentSoftDeep(), 1.0));
        QRectF inner = box.adjusted(1.0, 1.0, -1.0, -1.0);
        painter.setBrush(Qt::NoBrush);
        painter.drawPath(path);
        Q_UNUSED(inner);
    }
}

