    if (m_pendingPause) {
        finishAutoPlay();
        m_playTimer->stop();
        labelStatus->setText("已暂停。");
    }
}

void MainWindow::onFrameSettled() {
    if (m_pendingPause) {
        finishAutoPlay();
        m_playTimer->stop();
        labelStatus->setText("已暂停。");
        return;
    }
    if (m_playing && m_frameIndex >= m_frames.size()) {
        m_playTimer->stop();
        finishAutoPlay();
        labelStatus->setText("播放完毕。");
    }
}

