void MyTextEdit::renderPlaceholder(QPainter& painter) {
    if (!document()->isEmpty()) return;
    QString hint = placeholderText();
    if (hint.isEmpty()) return;
    painter.save();
    painter.setPen(UiTheme::textMuted());
    painter.setFont(font());
    painter.setRenderHint(QPainter::Antialiasing);
    QRectF area = QRectF(viewport()->rect()).adjusted(4, 3, -4, -3);
    QStringList lines = hint.split('\n');
    qreal lineHeight = painter.fontMetrics().lineSpacing();
    for (int i = 0; i < lines.size(); ++i) {
        qreal y = area.top() + lineHeight * i;
        if (y > area.bottom()) break;
        painter.drawText(QRectF(area.left(), y, area.width(), lineHeight),
                         Qt::AlignLeft | Qt::AlignVCenter, lines[i]);
    }
    painter.restore();
}

