static void colors(const QImage& img, const char* label) {
    printf("=== %s ===\n", label);
    printf("  center(150,25)=%s\n", img.pixelColor(150, 25).name().toUtf8().constData());
    printf("  left(10,25)  =%s\n", img.pixelColor(10, 25).name().toUtf8().constData());
    printf("  top(150,3)   =%s\n", img.pixelColor(150, 3).name().toUtf8().constData());
    QSet<QString> uniq;
    for (int y = 0; y < img.height(); ++y)
        for (int x = 0; x < img.width(); ++x) uniq.insert(img.pixelColor(x, y).name());
    printf("  unique colors=%d\n", uniq.size());
    int i = 0;
    for (const QString& c : uniq) { printf("    %s\n", c.toUtf8().constData()); if (++i > 8) break; }
}

