class Base : public QTextEdit {
public:
    explicit Base(int flags) : m_flags(flags) {
        if (m_flags & 1) setObjectName("myTextEdit");
        setFrameShape(QFrame::NoFrame);
        setFrameShadow(QFrame::Plain);
        setViewportMargins(0, 0, 0, 0);
        if (m_flags & 2) setAttribute(Qt::WA_TranslucentBackground, false);
        if (m_flags & 4) setFont(UiTheme::monoFont(10));
        if (m_flags & 8) setLineWrapMode(QTextEdit::NoWrap);
        if (m_flags & 16) setTabChangesFocus(true);
        viewport()->setAutoFillBackground((m_flags & 32) != 0);
        document()->setDocumentMargin(6);

        QPalette pal = viewport()->palette();
        pal.setColor(QPalette::Base, UiTheme::surface());
        pal.setColor(QPalette::Text, UiTheme::textPrimary());
        pal.setColor(QPalette::Highlight, UiTheme::accentSoft());
        pal.setColor(QPalette::HighlightedText, UiTheme::textPrimary());
        pal.setColor(QPalette::PlaceholderText, UiTheme::textMuted());
        viewport()->setPalette(pal);

        if (m_flags & 64) {
            setStyleSheet(QString(
                "QTextEdit#myTextEdit { background:%1; color:%2; selection-background-color:%3; selection-color:%2;"
                " border:1px solid %4; border-radius:%5px; }"
                "QTextEdit#myTextEdit:focus { border:1px solid %6; }"
            ).arg(UiTheme::surface().name(), UiTheme::textPrimary().name(),
                  UiTheme::accentSoft().name(), UiTheme::borderSoft().name(),
                  QString::number(UiTheme::radiusMd()), UiTheme::borderFocus().name()));
        }
        setPlaceholderText("请输入数据");
        if (m_flags & 128) {
            connect(this, &QTextEdit::textChanged, this, [this]() { viewport()->update(); });
        }
    }
    void setPlaceholderText(const QString& t) {
        if (m_flags & 256) { m_hint = t; QTextEdit::setPlaceholderText(t); return; }
        QTextEdit::setPlaceholderText(t);
    }
    QString placeholderText() const { return m_hint; }
private:
    int m_flags;
    QString m_hint;
};

static void run(int flags, const char* label) {
    Base t(flags);
    t.setFixedSize(300, 60);
    t.show();
    QApplication::processEvents();
    shot(&t, label);
    t.setText("临时内容");
    QApplication::processEvents();
    t.clear();
    QApplication::processEvents();
    shot(&t, label);
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    run(0, "F0 none");
    run(1, "F1 objectName");
    run(4, "F4 monoFont");
    run(8, "F8 nowrap");
    run(16, "F16 tabFocus");
    run(32, "F32 autofill");
    run(64, "F64 qss");
    run(128, "F128 connect");
    run(256, "F256 phOverride");
    run(1 | 4 | 8 | 16 | 32 | 64 | 128 | 256, "FALL");
    return 0;
}

