            p.setRenderHint(QPainter::Antialiasing);
            QPainterPath path;
            path.addRoundedRect(viewport()->rect(), 9, 9);
            p.setPen(Qt::NoPen);
            p.setBrush(UiTheme::surface());
            p.drawPath(path);
        }
        QTextEdit::paintEvent(e);
        if (toPlainText().isEmpty() && !m_hint.isEmpty()) {
            QPainter p(viewport());
            p.setRenderHint(QPainter::Antialiasing);
            p.setPen(UiTheme::textMuted());
            p.setFont(font());
            QRectF area = QRectF(viewport()->geometry());
            area.translate(viewport()->pos());
            area = area.adjusted(7, 5, -7, -5);
            const QStringList lines = m_hint.split('\n');
            const qreal lh = p.fontMetrics().lineSpacing();
            for (int i = 0; i < lines.size(); ++i) {
                const qreal y = area.top() + lh * i;
                if (y > area.bottom()) break;
                p.drawText(QRectF(area.left(), y, area.width(), lh), Qt::AlignLeft | Qt::AlignVCenter, lines[i]);
            }
        }
        {
            QPainter p(viewport());
            p.setRenderHint(QPainter::Antialiasing);
            QPainterPath path;
            path.addRoundedRect(viewport()->rect(), 9, 9);
            p.setBrush(Qt::NoBrush);
            p.setPen(QPen(QColor("#C4D8F3"), 1.4));
            p.drawPath(path);
        }
    }
private:
    QString m_hint;
};

