void SegmentTreeBuildModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;
    QString error;
    m_valid = SegmentTreeCommon::parseInput(inputData, m_arr, m_mod, error);
    m_mathText = scene->addText(m_valid ? "build(1, 1, n, a)：自顶向下递归建树，自底向上 push_up 合并"
                                        : ("输入错误：" + error));
    m_mathText->setFont(QFont("Consolas", 14, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(50, 22);
    if (!m_valid) return;

    m_n = static_cast<int>(m_arr.size()) - 1;
    m_slotCount = 4 * m_n + 5;
    m_tr.assign(m_slotCount, 0);
    m_mul.assign(m_slotCount, 0);

    const double cellW = 56.0;
    const double arrStartX = 150.0;
    for (int i = 1; i <= m_n; ++i) {
        QGraphicsRectItem* cell = scene->addRect(QRectF(0, 0, 52, 38), QPen(QColor(70, 80, 95), 1.5), QBrush(Qt::white));
        cell->setPos(arrStartX + (i - 1) * cellW, m_arrY);
        m_aCells[i] = cell;
        ArrayBlock* block = new ArrayBlock(i, m_arr[i], QString::number(i));
        block->setPos(arrStartX + (i - 1) * cellW, m_arrY);
        block->color = QColor(255, 250, 230);
        scene->addItem(block);
        m_aBlocks.push_back(block);
    }
    QGraphicsTextItem* aTitle = scene->addText("a");
    aTitle->setFont(QFont("Consolas", 13, QFont::Bold));
    aTitle->setDefaultTextColor(QColor(40, 70, 110));
    aTitle->setPos(arrStartX - 40, m_arrY - 2);

    m_nodes = SegmentTreeCommon::buildTopology(1, 1, m_n, QPointF(420, m_nodeY), 190.0, 105.0);
    for (const auto& info : m_nodes) {
        GraphNode* item = new GraphNode(info.node);
        item->setPos(info.pos);
        item->setCustomValueText(QString::number(info.node));
        item->setSubLabel(QString("[%1,%2]").arg(info.l).arg(info.r));
        item->color = QColor(250, 250, 252);
        scene->addItem(item);
        m_treeNodes[info.node] = item;
    }
    for (const auto& info : m_nodes) {
        if (info.l == info.r) continue;
        int mid = (info.l + info.r) >> 1;
        GraphNode* left = m_treeNodes[SegmentTreeCommon::ls(info.node)];
        GraphNode* right = m_treeNodes[SegmentTreeCommon::rs(info.node)];
        if (!left || !right) continue;
        GraphEdge* e1 = new GraphEdge(info.item, left, false, false);
        scene->addItem(e1);
        info.item->addEdge(e1);
        left->addEdge(e1);
        GraphEdge* e2 = new GraphEdge(info.item, right, false, false);
        scene->addItem(e2);
        info.item->addEdge(e2);
        right->addEdge(e2);
    }

    const double slotW = 52.0;
    const double slotStartX = 120.0;
    for (int i = 1; i <= m_slotCount; ++i) {
        ArrayBlock* tr = new ArrayBlock(i, 0, QString::number(i));
        tr->showValue = false;
        tr->setPos(slotStartX + (i - 1) * slotW, m_trY);
        tr->color = kSegGray;
        scene->addItem(tr);
        m_trBlocks[i] = tr;
        ArrayBlock* mul = new ArrayBlock(i, 0, QString::number(i));
        mul->showValue = false;
        mul->setPos(slotStartX + (i - 1) * slotW, m_mulY);
        mul->color = kSegGray;
        scene->addItem(mul);
        m_mulBlocks[i] = mul;
    }
    QGraphicsTextItem* trTitle = scene->addText("tr");
    trTitle->setFont(QFont("Consolas", 13, QFont::Bold));
    trTitle->setDefaultTextColor(QColor(40, 70, 110));
    trTitle->setPos(slotStartX - 42, m_trY);
    QGraphicsTextItem* mulTitle = scene->addText("mul");
    mulTitle->setFont(QFont("Consolas", 13, QFont::Bold));
    mulTitle->setDefaultTextColor(QColor(40, 70, 110));
    mulTitle->setPos(slotStartX - 42, m_mulY);

    m_ptrNode = new PointerBlock("node", kSegRed);
    m_ptrNode->setOpacity(0);
    scene->addItem(m_ptrNode);
}

std::vector<AnimFrame> SegmentTreeBuildModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;
    m_tr.assign(m_slotCount, 0);
    m_mul.assign(m_slotCount, 0);
    m_frames.push_back({ActionType::SEG_RESET, 0, 0, 0, 0, {}, "准备建树，所有节点尚未赋值", "build(1, 1, n, a)"});

    struct Task { int node, l, r; };
    std::vector<Task> stack;
    stack.push_back({1, 1, m_n});
    std::vector<std::pair<int, int>> pending;
    while (!stack.empty()) {
        Task t = stack.back();
        stack.pop_back();
        m_mul[t.node] = 1;
        m_frames.push_back({ActionType::SEG_INIT_MUL, t.node, 0, 0, 0, {},
                            QString("进入 build(node=%1, l=%2, r=%3)：先令 mul 为 1").arg(t.node).arg(t.l).arg(t.r),
                            QString("mul[%1] = 1").arg(t.node)});
        if (t.l == t.r) {
            m_tr[t.node] = m_arr[t.l] % m_mod;
            m_frames.push_back({ActionType::SEG_LEAF, t.node, t.l, static_cast<int>(m_tr[t.node]), 0, {},
                                QString("到达叶子 node=%1，取 a[%2]").arg(t.node).arg(t.l),
                                QString("tr[%1] = a[%2] %% p = %3").arg(t.node).arg(t.l).arg(m_tr[t.node])});
            pending.push_back({t.node, t.node});
            continue;
        }
        int mid = (t.l + t.r) >> 1;
        m_frames.push_back({ActionType::SEG_DESCEND, t.node, mid, SegmentTreeCommon::ls(t.node), SegmentTreeCommon::rs(t.node), {},
                            QString("node=%1 的区间 [%2,%3] 被中点 %4 一分为二").arg(t.node).arg(t.l).arg(t.r).arg(mid),
                            QString("mid = (%1+%2)>>1 = %3　ls = %1<<1 = %4　rs = %1<<1|1 = %5")
                                .arg(t.node).arg(t.r).arg(mid).arg(SegmentTreeCommon::ls(t.node)).arg(SegmentTreeCommon::rs(t.node))});
        stack.push_back({SegmentTreeCommon::rs(t.node), mid + 1, t.r});
        stack.push_back({SegmentTreeCommon::ls(t.node), t.l, mid});
    }

    std::vector<std::pair<int, int>> merges;
    for (auto& p : pending) merges.push_back(p);
    while (!merges.empty()) {
        std::pair<int, int> p = merges.back();
        merges.pop_back();
        int node = p.first;
        int l = p.second;
        int r = p.second;
        (void)l;
        (void)r;
        int lc = SegmentTreeCommon::ls(node);
        int rc = SegmentTreeCommon::rs(node);
        if (lc > m_slotCount || rc > m_slotCount) continue;
        if (m_tr[lc] == 0 && m_tr[rc] == 0 && !m_leaves[lc]) continue;
        m_tr[node] = (m_tr[lc] + m_tr[rc]) % m_mod;
        m_frames.push_back({ActionType::SEG_PUSHUP, node, lc, static_cast<int>(m_tr[lc]), static_cast<int>(m_tr[rc]), {},
                            QString("node=%1 汇总两个孩子的区间和").arg(node),
                            QString("tr[%1] = (tr[%2] + tr[%3]) %% mod = %4").arg(node).arg(lc).arg(rc).arg(m_tr[node])});
    }

    m_frames.push_back({ActionType::SEG_DONE, 1, 0, 0, 0, {}, "建树完成，根节点保存整个数组的和", "build 完成"});
    return m_frames;
}

void SegmentTreeBuildModule::renderFrame(const AnimFrame& frame) {
    if (!m_mathText) return;
    m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    if (frame.type == ActionType::SEG_RESET) {
        for (auto& kv : m_treeNodes) {
            kv.second->setHighlightColor(Qt::transparent);
            kv.second->color = QColor(250, 250, 252);
            kv.second->setCustomValueText(QString::number(kv.first));
            kv.second->setSubLabel(QString("[%1,%2]").arg(kv.second->l).arg(kv.second->l));
            kv.second->update();
        }
        for (auto& kv : m_trBlocks) {
            kv.second->showValue = false;
            kv.second->value = 0;
            kv.second->color = kSegGray;
            kv.second->update();
        }
        for (auto& kv : m_mulBlocks) {
            kv.second->showValue = false;
            kv.second->value = 0;
            kv.second->color = kSegGray;
            kv.second->update();
        }
        if (m_ptrNode) m_ptrNode->setOpacity(0);
        refreshNodeLabels();
    } else if (frame.type == ActionType::SEG_INIT_MUL) {
        ArrayBlock* blk = m_mulBlocks[frame.u];
        if (blk) {
            blk->value = 1;
            blk->showValue = true;
            blk->color = kSegBlue;
            blk->update();
        }
        GraphNode* node = m_treeNodes[frame.u];
        if (node) {
            node->setHighlightColor(kSegRed);
            node->color = QColor(255, 240, 238);
        }
        if (m_ptrNode) {
            m_ptrNode->setOpacity(1);
            m_ptrNode->setPos(node->pos() + QPointF(0, 46));
        }
    } else if (frame.type == ActionType::SEG_DESCEND) {
        GraphNode* node = m_treeNodes[frame.u];
        GraphNode* left = m_treeNodes[frame.v];
        GraphNode* right = m_treeNodes[frame.val2];
        if (node) {
            node->setHighlightColor(kSegOrange);
            node->color = QColor(255, 248, 232);
        }
        if (left) {
            left->setHighlightColor(kSegOrange);
            left->color = QColor(255, 248, 232);
        }
        if (right) right->color = QColor(250, 250, 252);
        if (m_ptrNode && node) m_ptrNode->setPos(node->pos() + QPointF(0, 46));
    } else if (frame.type == ActionType::SEG_LEAF) {
        ArrayBlock* blk = m_trBlocks[frame.u];
        GraphNode* node = m_treeNodes[frame.u];
        if (blk && node) {
            blk->value = frame.val1;
            blk->showValue = true;
            blk->color = kSegGreen;
            blk->update();
            node->setCustomValueText(QString::number(frame.val1));
            node->color = QColor(240, 252, 242);
            node->setHighlightColor(kSegGreen);
        }
        if (m_ptrNode && node) m_ptrNode->setPos(node->pos() + QPointF(0, 46));
    } else if (frame.type == ActionType::SEG_PUSHUP) {
        ArrayBlock* blk = m_trBlocks[frame.u];
        GraphNode* node = m_treeNodes[frame.u];
        ArrayBlock* lb = m_trBlocks[frame.v];
        ArrayBlock* rb = m_trBlocks[frame.val2];
        if (blk && node) {
            QPointF sa = lb ? lb->pos() + QPointF(30, 0) : blk->pos();
            QPointF sb = rb ? rb->pos() + QPointF(30, 0) : blk->pos();
            playDualValueFlight(sa, sb, blk, frame.val1, frame.val2, kSegGreen);
            node->setCustomValueText(QString::number((frame.val1 + frame.val2) % m_mod));
            node->color = QColor(240, 252, 242);
            node->setHighlightColor(kSegGreen);
        }
        if (m_ptrNode && node) m_ptrNode->setPos(node->pos() + QPointF(0, 46));
    } else if (frame.type == ActionType::SEG_DONE) {
        for (auto& kv : m_treeNodes) {
            kv.second->setHighlightColor(Qt::transparent);
            kv.second->color = QColor(240, 252, 242);
        }
        for (auto& kv : m_trBlocks) {
            if (kv.second->showValue) {
                kv.second->color = kSegGreen;
                kv.second->update();
            }
        }
        if (m_ptrNode) m_ptrNode->setOpacity(0);
    }
}

