QPropertyAnimation* IModule::acquireAnim(QObject* target, const char* property, int duration, const QEasingCurve& curve) {
    if (!target) return nullptr;
    auto key = std::make_pair(target, QString(property));
    auto it = m_animRegistry.find(key);
    QPropertyAnimation* anim = nullptr;
    if (it != m_animRegistry.end() && it->second) {
        anim = it->second;
    } else {
        anim = new QPropertyAnimation(target, property, this);
        m_animRegistry[key] = anim;
    }
    anim->stop();
    anim->setDuration(duration);
    anim->setEasingCurve(curve);
    return anim;
}

void IModule::releaseAnim(QObject* target, const char* property) {
    auto key = std::make_pair(target, QString(property));
    auto it = m_animRegistry.find(key);
    if (it == m_animRegistry.end()) return;
    if (it->second) {
        it->second->stop();
        delete it->second;
    }
    m_animRegistry.erase(it);
}

void IModule::stopAllAnims() {
    for (auto& kv : m_animRegistry) {
        if (kv.second) {
            kv.second->stop();
        }
    }
}

void IModule::playPointerMove(PointerBlock* ptr, QPointF targetPos) {
    if (!ptr) return;
    if (m_animated) {
        QPropertyAnimation* anim = new QPropertyAnimation(ptr, "pos");
        anim->setEndValue(targetPos);
        anim->setDuration(400);
        anim->setEasingCurve(QEasingCurve::InOutQuad);
        anim->start(QAbstractAnimation::DeleteWhenStopped);
    } else {
        ptr->setPos(targetPos);
    }
}

void IModule::playScaleAnim(ArrayBlock* block) {
    if (!block) return;
    if (m_animated) {
        QPropertyAnimation* sa = new QPropertyAnimation(block, "scale");
        sa->setDuration(300);
        sa->setKeyValueAt(0, 1.0);
        sa->setKeyValueAt(0.5, 1.2);
        sa->setKeyValueAt(1.0, 1.0);
        sa->start(QAbstractAnimation::DeleteWhenStopped);
    }
}

void IModule::playPointerMove(PointerBlock* ptr, QPointF targetPos) {
    if (!ptr) return;
    if (!m_animated) {
        stopAnimFor(ptr);
        ptr->setPos(targetPos);
        return;
    }
    QPropertyAnimation* anim = acquireAnim(ptr, "pos", 400, QEasingCurve::InOutQuad);
    if (!anim) return;
    anim->setStartValue(ptr->pos());
    anim->setEndValue(targetPos);
    anim->start();
}

void IModule::playScaleAnim(ArrayBlock* block) {
    if (!block) return;
    if (!m_animated) {
        stopAnimFor(block);
        block->setScale(1.0);
        return;
    }
    QPropertyAnimation* anim = acquireAnim(block, "scale", 300, QEasingCurve::InOutQuad);
    if (!anim) return;
    anim->setStartValue(block->scale());
    anim->setKeyValueAt(0.0, 1.0);
    anim->setKeyValueAt(0.5, 1.2);
    anim->setKeyValueAt(1.0, 1.0);
    anim->start();
}

