    Layout layout;
    if (n <= 0) return layout;
    layout.depth = treeDepth(n);
    layout.nodeY = 230.0;
    layout.treeBottom = layout.nodeY + (layout.depth - 1) * layout.rowGap;
    layout.firstRowY = layout.treeBottom + 130.0;
    layout.slotIds = collectNodeIds(1, 1, n);
    return layout;
}

