void ArrayBlock::beginEdit() {
    if (!m_editable || m_editor) return;
    QGraphicsScene* sc = scene();
    if (!sc) return;
    QString current = customValue.isEmpty() ? QString::number(value) : customValue;
    m_editor = sc->addText(current);
    m_editor->setFont(QFont("Consolas", 14, QFont::Bold));
    m_editor->setDefaultTextColor(QColor(20, 30, 45));
    m_editor->setTextInteractionFlags(Qt::TextEditorInteraction);
    m_editor->setZValue(20);
    QFontMetrics fm(m_editor->font());
    m_editor->setPos(pos().x() + 30.0 - fm.horizontalAdvance(current) / 2.0, pos().y() + 20.0 - fm.height() / 2.0);
    m_editor->setFocus();
    QTextCursor cursor = m_editor->textCursor();
    cursor.select(QTextCursor::Document);
    m_editor->setTextCursor(cursor);
}
void ArrayBlock::commitEdit() {
    if (!m_editor) return;
    QString text = m_editor->toPlainText().trimmed();
    QGraphicsScene* sc = m_editor->scene();
    QGraphicsTextItem* editor = m_editor;
    m_editor = nullptr;
    if (sc) sc->removeItem(editor);
    delete editor;
    if (text.isEmpty()) return;
    emit valueEdited(id, text);
}
void ArrayBlock::cancelEdit() {
    if (!m_editor) return;
    QGraphicsScene* sc = m_editor->scene();
    QGraphicsTextItem* editor = m_editor;
    m_editor = nullptr;
    if (sc) sc->removeItem(editor);
    delete editor;
}
