class IModule {
public:
    bool m_animated = true;
    virtual ~IModule() = default;

    QPropertyAnimation* makeAnim(QObject* target, const char* property);
    static void stopGlobalAnims();

private:
    struct AnimKey {
        QPointer<QObject> target;
        QString property;
        bool operator<(const AnimKey& other) const {
            if (target.data() != other.target.data()) return target.data() < other.target.data();
            return property < other.property;
        }
    };
    std::map<AnimKey, QPointer<QPropertyAnimation>> m_animRegistry;
};

private:
    struct AnimKey {
        QPointer<QObject> target;
        QString property;
        bool operator<(const AnimKey& other) const {
            if (target.data() != other.target.data()) return target.data() < other.target.data();
            return property < other.property;
        }
    };
    std::map<AnimKey, QPointer<QPropertyAnimation>> m_animRegistry;
    std::vector<QPointer<QPropertyAnimation>> m_ownedAnims;
};

QPropertyAnimation* IModule::makeAnim(QObject* target, const char* property) {
    if (!target) return nullptr;
    auto key = std::make_pair(QPointer<QObject>(target), QString(property));
    static std::map<std::pair<QPointer<QObject>, QString>, QPropertyAnimation*> s_global;
    auto it = s_global.find(key);
    if (it != s_global.end() && it->second) {
        it->second->stop();
        return it->second;
    }
    QPropertyAnimation* anim = new QPropertyAnimation(target, QByteArray(property));
    s_global[key] = anim;
    m_ownedAnims.push_back(QPointer<QPropertyAnimation>(anim));
    return anim;
}

void IModule::stopGlobalAnims() {
    stopAllAnims();
}

