#include <QString>
#include <QMap>

class ValueOverrides {
public:
    static ValueOverrides& instance() {
        static ValueOverrides s_instance;
        return s_instance;
    }

    void set(const QString& key, int value) {
        if (key.isEmpty()) return;
        m_map[key] = value;
    }

    void remove(const QString& key) { m_map.remove(key); }

    bool get(const QString& key, int& out) const {
        if (key.isEmpty()) return false;
        auto it = m_map.constFind(key);
        if (it == m_map.constEnd()) return false;
        out = it.value();
        return true;
    }

    bool contains(const QString& key) const {
        if (key.isEmpty()) return false;
        return m_map.contains(key);
    }

    void clear() { m_map.clear(); }

    QStringList keys() const { return m_map.keys(); }

private:
    QMap<QString, int> m_map;
};

#endif

