struct EditableSlot {
    QString key;
    int value = 0;
    bool numeric = true;
};

class EditableModel {
public:
    static EditableModel& instance() {
        static EditableModel s_instance;
        return s_instance;
    }

    void clear() {
        m_values.clear();
        m_numeric.clear();
    }

    void declare(const QString& key, int initial) {
        if (key.isEmpty()) return;
        if (m_values.contains(key)) return;
        m_values[key] = initial;
        m_numeric[key] = true;
    }

    void declareText(const QString& key, const QString& initial) {
        if (key.isEmpty()) return;
        if (m_values.contains(key)) return;
        m_values[key] = 0;
        m_numeric[key] = false;
        m_texts[key] = initial;
    }

    void setText(const QString& key, const QString& text) {
        if (key.isEmpty()) return;
        if (!m_numeric.value(key, true)) {
            m_texts[key] = text;
            return;
        }
        bool ok = false;
        int parsed = text.toInt(&ok);
        if (ok) m_values[key] = parsed;
    }

    int value(const QString& key, int fallback) const {
        auto it = m_values.constFind(key);
        if (it == m_values.constEnd()) return fallback;
        return it.value();
    }

    bool has(const QString& key) const {
        return m_values.contains(key);
    }

    void setValue(const QString& key, int value) {
        if (key.isEmpty()) return;
        m_values[key] = value;
    }

private:
    QHash<QString, int> m_values;
    QHash<QString, bool> m_numeric;
    QHash<QString, QString> m_texts;
};

#endif

