    QString slotKeyFor(ArrayBlock* block) const override;
    QString slotKeyFor(GraphNode* node) const override;
    QString slotKeyFor(GraphEdge* edge) const override;
    bool onSlotEdited(const QString& key, const QString& text) override;

protected:
    struct SlotBinding {
        QString key;
        ArrayBlock* block = nullptr;
        GraphNode* node = nullptr;
        GraphEdge* edge = nullptr;
        int fallback = 0;
    };

    QString makeKey(const QString& row, int index) const;
    void bindBlock(ArrayBlock* block, const QString& row, int index, int fallback);
    void bindNode(GraphNode* node, const QString& row, int index, int fallback);
    void bindEdge(GraphEdge* edge, const QString& row, int index, int fallback);
    void refreshSlot(const QString& key);
    void refreshAllSlots();
    int slotValue(const QString& row, int index, int fallback) const;
