        GraphNode* node = new GraphNode(i);
        node->setPos(GraphModuleUtils::circlePoint(i - 1, n, center, radius));
        scene->addItem(node);
        nodes[i] = node;
        if (module) module->registerNodeSlot(i, "v", i);
