int main(int argc, char** argv) {
    QApplication app(argc, argv);

    Knapsack01Module knap;
    QGraphicsScene scene;
    knap.buildLayout(&scene, "4 8\n2 3\n3 4\n4 5\n5 8");
    QApplication::processEvents();
    QVector<QGraphicsItem*> blocks;
    for (QGraphicsItem* item : scene.items()) {
        if (item->type() >= QGraphicsItem::UserType + 1 && item->type() < QGraphicsItem::UserType + 100) blocks.push_back(item);
    }
    printf("knapsack blocks: %d\n", blocks.size());
    int shown = 0;
    for (int a = 0; a < blocks.size(); ++a) {
        for (int b = a + 1; b < blocks.size(); ++b) {
            QRectF ra = blocks[a]->mapRectToScene(blocks[a]->boundingRect());
            QRectF rb = blocks[b]->mapRectToScene(blocks[b]->boundingRect());
            if (ra.intersects(rb) && shown < 8) {
                printf("OVERLAP type %d rect(%.0f,%.0f,%.0f,%.0f)  type %d rect(%.0f,%.0f,%.0f,%.0f)\n",
                       blocks[a]->type(), ra.x(), ra.y(), ra.width(), ra.height(),
                       blocks[b]->type(), rb.x(), rb.y(), rb.width(), rb.height());
                ++shown;
            }
        }
    }

    BinarySearchClosedModule bs;
    QGraphicsScene bsScene;
    bs.m_animated = false;
    bs.buildLayout(&bsScene, "5 8\n1 3 5 7 9");
    auto frames = bs.runAlgorithm();
    for (const auto& f : frames) bs.renderFrame(f);
    QApplication::processEvents();
    for (QGraphicsItem* item : bsScene.items()) {
        PointerBlock* p = dynamic_cast<PointerBlock*>(item);
        if (!p) continue;
