                if (!anim) continue;
                anim->setStartValue(s.ptr->pos());
                anim->setEndValue(targetPos);
                anim->start();
            } else {
                stopAnimFor(s.ptr);
                s.ptr->setPos(targetPos);
            }
        }
    }
