#include <QApplication>
#include <QImage>
#include <QPainter>
#include <QGraphicsScene>
#include <cstdio>
#include "modules/KMPMatchModule.h"

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    QGraphicsScene scene;
    KMPMatchModule m;
    m.buildLayout(&scene, "ABABCABAA\nABAB");
    auto frames = m.runAlgorithm();
    for (auto& f : frames) m.renderFrame(f);
    QRectF sr = scene.sceneRect();
    QImage img(sr.size().toSize(), QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    scene.render(&p);

    for (int y = 112; y <= 170; y += 2) {
        std::vector<int> cols;
        for (int x = 100; x < 700; ++x) {
            if (img.pixelColor(x, y).lightness() < 200) cols.push_back(x);
        }
        std::vector<int> runs;
        for (size_t i = 0; i < cols.size(); ++i) {
            if (i + 1 < cols.size() && cols[i + 1] - cols[i] <= 1) runs.push_back(cols[i]);
        }
        bool contiguous = runs.size() >= 10;
        double mind = 1e9, maxd = -1e9;
        for (size_t i = 1; i < runs.size(); ++i) {
            double d = runs[i] - runs[i - 1];
            if (d < mind) mind = d;
            if (d > maxd) maxd = d;
        }
        for (size_t i = 1; i < runs.size() && contiguous; ++i) {
            double d = runs[i] - runs[i - 1];
            if (d < 52 || d > 54) contiguous = false;
        }
        printf("row %d: runs=%zu contiguous=%d deltaRange=[%.0f,%.0f]", y, runs.size(), (int)contiguous, mind, maxd);
        if (runs.size() <= 16) {
            printf("  cols=");
            for (int c : runs) printf("%d ", c);
        }
        printf("\n");
    }
    return 0;
}

