static void scanRow(const char* tag, const QImage& img, int y) {
    printf("%s row %d dark runs: ", tag, y);
    int x = 0;
    while (x < img.width()) {
        if (img.pixelColor(x, y).lightness() < 160) {
            int start = x;
            while (x < img.width() && img.pixelColor(x, y).lightness() < 160) ++x;
            printf("[%d..%d w=%d] ", start, x - 1, x - start);
        } else ++x;
    }
    printf("\n");
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    QGraphicsScene scene;
    PrefixSumModule mod;
    mod.buildLayout(&scene, "4 1\n1 2 3 4\n1 4");
    QApplication::processEvents();
    QRectF sr = scene.sceneRect();
    QImage img(sr.size().toSize(), QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    scene.render(&p);
    img.save("border_diag.png");
    for (int y = 200; y <= 210; ++y) scanRow("a", img, y);
    return 0;
}

