void destroyEditor(QPointer<QGraphicsTextItem>& slot) {
    if (slot.isNull()) return;
    QGraphicsTextItem* editor = slot.data();
    slot = nullptr;
    editor->setParentItem(nullptr);
    if (editor->scene()) editor->scene()->removeItem(editor);
    editor->deleteLater();
}
