static int failures = 0;
static void check(bool cond, const char* msg) {
    if (!cond) { printf("FAIL: %s\n", msg); failures++; }
    else printf("PASS: %s\n", msg);
}

static void pump(int ms) {
    QEventLoop loop;
    QTimer::singleShot(ms, &loop, &QEventLoop::quit);
    loop.exec();
}

static QGraphicsTextItem* editorOf(QGraphicsItem* parent) {
    for (QGraphicsItem* child : parent->childItems()) {
        QGraphicsTextItem* t = dynamic_cast<QGraphicsTextItem*>(child);
        if (t) return t;
    }
    return nullptr;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    QGraphicsScene scene;
    QGraphicsView view(&scene);
    view.setAttribute(Qt::WA_DontShowOnScreen, true);
    view.show();
    QApplication::processEvents();

    PrefixSumModule mod;
    mod.buildLayout(&scene, "4 1\n1 2 3 4\n1 4");
    mod.enableLiveEditing();

    ArrayBlock* a1 = nullptr;
    for (QGraphicsItem* item : scene.items()) {
        ArrayBlock* blk = qgraphicsitem_cast<ArrayBlock*>(item);
        if (blk && blk->id == 1 && blk->pos().y() < 300) a1 = blk;
    }
    check(a1 != nullptr, "a[1] block exists");
    if (!a1) { printf("\n%d failures\n", failures); return 1; }
    check(a1->isEditable(), "a[1] is editable");

    a1->beginEdit();
    pump(30);
    check(a1->isEditing(), "double click starts editing");

    QGraphicsTextItem* ed = editorOf(a1);
    check(ed != nullptr, "editor item created");
    if (ed) {
        ed->clearFocus();
        pump(30);
        printf("survived focus-out commit\n");
        check(!a1->isEditing(), "focus out ends editing");
    }

    a1->beginEdit();
    pump(30);
    ed = editorOf(a1);
    check(ed != nullptr, "second editor created");
    if (ed) {
        ed->setPlainText("7");
        QTextCursor c = ed->textCursor();
        c.select(QTextCursor::Document);
        ed->setTextCursor(c);
        QKeyEvent ke(QEvent::KeyPress, Qt::Key_Return, Qt::NoModifier);
        QApplication::sendEvent(ed, &ke);
    }
    pump(30);
    printf("survived enter commit\n");
    check(!a1->isEditing(), "enter commit ends editing");
    check(a1->value == 7, "committed value applied");

    a1->beginEdit();
    pump(30);
    ed = editorOf(a1);
    if (ed) {
        ed->setPlainText("9");
        QKeyEvent ke(QEvent::KeyPress, Qt::Key_Escape, Qt::NoModifier);
        QApplication::sendEvent(ed, &ke);
    }
    pump(30);
    printf("survived escape cancel\n");
    check(!a1->isEditing(), "escape ends editing");
    check(a1->value == 7, "escape keeps old value");

    a1->beginEdit();
    pump(30);
    scene.clear();
    pump(30);
    printf("survived scene teardown while editing\n");
    check(true, "scene teardown during edit does not crash");

    printf("\n%d failures\n", failures);
    return failures == 0 ? 0 : 1;
}

#include <QApplication>
#include <QGraphicsScene>
#include <QImage>
#include <QPainter>
#include <cstdio>
#include "modules/PrefixSumModule.h"
#include "modules/BubbleSortModule.h"
#include "modules/SegmentTreeBuildModule.h"
#include "render/GraphElements.h"

static int failures = 0;
static void check(bool cond, const char* msg) {
    if (!cond) { printf("FAIL: %s\n", msg); failures++; }
    else printf("PASS: %s\n", msg);
}

static QImage shot(QGraphicsScene* scene) {
    QRectF sr = scene->itemsBoundingRect();
    QImage img(sr.size().toSize(), QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    scene->render(&p, QRectF(QPointF(0, 0), sr.size()), sr);
    return img;
}

static std::vector<int> darkRuns(const QImage& img, int y, int x0, int x1) {
    std::vector<int> runs;
    int start = -1;
    for (int x = x0; x <= x1; ++x) {
        bool dark = x < img.width() && img.pixelColor(x, y).lightness() < 160;
        if (dark && start < 0) start = x;
        if (!dark && start >= 0) { runs.push_back(x - start); start = -1; }
    }
    return runs;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    {
        QGraphicsScene scene;
        PrefixSumModule mod;
        mod.buildLayout(&scene, "4 1\n1 2 3 4\n1 4");
        QApplication::processEvents();
        QImage img = shot(&scene);
        img.save("border_diag.png");
        QRectF sr = scene.itemsBoundingRect();

        int y = int(220 - sr.y());
        int x0 = int(250 - sr.x());
        int x1 = int(430 - sr.x());
        std::vector<int> runs = darkRuns(img, y, x0, x1);
        printf("dark run widths at row y=220: ");
        for (int w : runs) printf("%d ", w);
        printf("\n");

        int maxWidth = 0;
        int wideCount = 0;
        for (int w : runs) {
            if (w > maxWidth) maxWidth = w;
            if (w > 3) wideCount++;
        }
        check(maxWidth <= 3, "no thick double border band between cells");
        check(wideCount == 0, "no double-line seam between adjacent cells");
    }

    {
        QGraphicsScene scene;
        BubbleSortModule mod;
        mod.buildLayout(&scene, "5 3 8 1 9");
        QApplication::processEvents();
        QImage img = shot(&scene);
        QRectF sr = scene.itemsBoundingRect();
        int y = int(320 - sr.y());
        std::vector<int> runs = darkRuns(img, y, int(140 - sr.x()), int(460 - sr.x()));
        printf("bubble dark run widths: ");
        for (int w : runs) printf("%d ", w);
        printf("\n");
        int wideCount = 0;
        for (int w : runs) if (w > 3) wideCount++;
        check(wideCount == 0, "bubble sort cells share single divider");
    }

    {
        QGraphicsScene scene;
        SegmentTreeBuildModule mod;
        mod.buildLayout(&scene, "6 100\n1 2 3 4 5 6");
        QApplication::processEvents();
        QImage img = shot(&scene);
        QRectF sr = scene.itemsBoundingRect();
        int y = int(140 - sr.y());
        std::vector<int> runs = darkRuns(img, y, int(140 - sr.x()), int(500 - sr.x()));
        printf("seg dark run widths: ");
        for (int w : runs) printf("%d ", w);
        printf("\n");
        int wideCount = 0;
        for (int w : runs) if (w > 3) wideCount++;
        check(wideCount == 0, "segment tree array cells share single divider");
    }

    {
        QGraphicsScene scene;
        BubbleSortModule mod;
        mod.buildLayout(&scene, "5 3 8 1 9");
        QApplication::processEvents();
        int tightPairs = 0;
        double gap = 0.0;
        QVector<ArrayBlock*> cells;
        for (QGraphicsItem* item : scene.items()) {
            ArrayBlock* blk = qgraphicsitem_cast<ArrayBlock*>(item);
            if (blk) cells.push_back(blk);
        }
        for (int i = 0; i + 1 < cells.size(); ++i) {
            ArrayBlock* a = cells[i];
            ArrayBlock* b = cells[i + 1];
            if (qAbs(a->pos().y() - b->pos().y()) > 1.0) continue;
            double d = b->pos().x() - a->pos().x();
            if (d <= 0.0) continue;
            gap = d;
            if (d < a->cellWidth() - 0.5) tightPairs++;
        }
        printf("cell pitch: %.2f, cell width: %.2f\n", gap, cells.isEmpty() ? 0.0 : cells[0]->cellWidth());
        check(tightPairs == 0, "adjacent cells are exactly pitch-wide (no gap, no overlap)");
    }

    printf("\n%d failures\n", failures);
    return failures == 0 ? 0 : 1;
}

