        if (ArrayBlock* b = aBlock(i)) { b->color = kFtPale; b->update(); }
        if (ArrayBlock* b = tBlock(i)) { b->color = kFtPale; b->update(); }
    }
    if (m_accText) m_accText->setPlainText("");
    if (m_ptrIndex) m_ptrIndex->setOpacity(0);
