bool MyComboBox::eventFilter(QObject* obj, QEvent* event) {
    if (m_popup && event->type() == QEvent::MouseButtonPress) {
        QMouseEvent* me = static_cast<QMouseEvent*>(event);
        QWidget* w = qobject_cast<QWidget*>(obj);
        if (w != m_popup && !isAncestorOf(w)) {
            bool insidePopup = false;
            for (ComboRow* row : m_rows) {
                if (w == row || (w && row->isAncestorOf(w))) { insidePopup = true; break; }
            }
            if (!insidePopup) {
                closePopup();
                qApp->removeEventFilter(this);
                Q_UNUSED(me);
            }
        }
    }

bool MyComboBox::isPopupChild(QObject* obj) const {
    QWidget* w = qobject_cast<QWidget*>(obj);
    if (!w) return false;
    if (w == m_popup) return true;
    if (m_popup && m_popup->isAncestorOf(w)) return true;
    for (ComboRow* row : m_rows) {
        if (w == row || (w && row->isAncestorOf(w))) return true;
    }
    for (QWidget* child : m_popupWidgets) {
        if (w == child || (w && child->isAncestorOf(w))) return true;
    }
    return false;
}

bool MyComboBox::eventFilter(QObject* obj, QEvent* event) {
    if (m_popup && event->type() == QEvent::MouseButtonPress) {
        QMouseEvent* me = static_cast<QMouseEvent*>(event);
        QWidget* w = qobject_cast<QWidget*>(obj);
        if (w != m_popup && !isAncestorOf(w) && !isPopupChild(w)) {
            closePopup();
            qApp->removeEventFilter(this);
            Q_UNUSED(me);
        }
    }

void MyComboBox::closePopup() {
    if (!m_popup) return;
    QPointer<QWidget> popup = m_popup;
    m_popup = nullptr;
    m_popupLayout = nullptr;
    m_rows.clear();
    if (!popup) return;
    popup->close();
    popup->deleteLater();
}

void MyComboBox::closePopup() {
    if (!m_popup) return;
    QPointer<QWidget> popup = m_popup;
    m_popup = nullptr;
    m_popupLayout = nullptr;
    m_rows.clear();
    m_popupWidgets.clear();
    if (!popup) return;
    popup->close();
    popup->deleteLater();
}

#ifndef HEAPTREEBASE_H
#define HEAPTREEBASE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <map>
#include <vector>
#include <algorithm>
#include <cmath>
#include <QFont>
#include <QGraphicsTextItem>

class HeapTreeBase : public IModule {
public:
    int heapDepth(int n) const {
        int d = 0;
        while ((1 << (d + 1)) <= n) ++d;
        return d;
    }

    void layoutHeap(int n, const std::vector<int>& heap) {
        m_heap.clear();
        m_heap = heap;
        m_arrayBlocks.clear();
        m_treeNodes.clear();
        m_treeEdges.clear();
        m_relationLabels.clear();
        m_n = n;

        const double cellW = 62.0;
        const double arrY = 560.0;
        const double treeTop = 200.0;
        const double levelGap = 108.0;
        const double halfSpan = 210.0;
        const double centerX = 400.0;

        for (int i = 1; i <= n; ++i) {
            ArrayBlock* block = new ArrayBlock(i, heap[i], QString::number(i));
            block->setCellSize(cellW, 40.0);
            block->setPos(centerX - (n * cellW) / 2.0 + (i - 1) * cellW, arrY);
            block->color = QColor(250, 250, 252);
            m_scene->addItem(block);
            m_arrayBlocks[i] = block;
            registerArraySlot(block, "heap", i);
        }
        QGraphicsTextItem* arrTitle = m_scene->addText("heap[]（数组存储）");
        arrTitle->setFont(QFont("Consolas", 12, QFont::Bold));
        arrTitle->setDefaultTextColor(QColor(40, 70, 110));
        arrTitle->setPos(centerX - (n * cellW) / 2.0 - 10, arrY - 30);

        int depth = heapDepth(n);
        for (int i = 1; i <= n; ++i) {
            int d = 0;
            while ((1 << (d + 1)) <= i) ++d;
            int levelStart = 1 << d;
            int levelCount = std::min(1 << d, n - levelStart + 1);
            int posInLevel = i - levelStart;
            double span = halfSpan * std::pow(2.0, d) / std::pow(2.0, depth);
            double x = centerX + (posInLevel - (levelCount - 1) / 2.0) * (span * 2.0 / std::max(1, levelCount));
            double y = treeTop + d * levelGap;

            GraphNode* node = new GraphNode(i);
            node->setPos(x, y);
            node->color = QColor(250, 250, 252);
            node->setCustomValueText(QString::number(heap[i]));
            node->setSubLabel(QString::number(i));
            m_scene->addItem(node);
            m_treeNodes[i] = node;

            int parent = i / 2;
            if (parent >= 1) {
                GraphEdge* edge = new GraphEdge(m_treeNodes[parent], node, false, false);
                edge->color = QColor(170, 180, 195);
                m_scene->addItem(edge);
                m_treeNodes[parent]->addEdge(edge);
                node->addEdge(edge);
