    const QRectF box = QRectF(rect());

    const double barW = 3.5;
    const double barH = 15.0;
    QRectF bar(box.left() + 12.0, box.center().y() - barH / 2.0, barW, barH);
    QPainterPath barPath;
    barPath.addRoundedRect(bar, 1.6, 1.6);
    painter.setPen(Qt::NoPen);
    painter.setBrush(m_accent);
    painter.drawPath(barPath);

    painter.setFont(font());
    painter.setPen(m_accent.darker(118));
    painter.drawText(QRectF(bar.right() + 8.0, box.top(), box.width() - 34.0, box.height()),
                     Qt::AlignVCenter | Qt::AlignLeft, m_text);

    const QFontMetrics fm(font());
    const double textW = fm.horizontalAdvance(m_text);
    const double count = std::max(1, static_cast<int>(m_text.size()) / 4);
    Q_UNUSED(count);
    Q_UNUSED(textW);
}

