#include "TwoRowArrayModule.h"
#include <QRegularExpression>
#include <QPropertyAnimation>
#include <QParallelAnimationGroup>
#include <QPointer>
#include <QFont>

void TwoRowArrayModule::parseTwoRowInput(const QString& inputData, int& n, int& m,
                                         std::vector<int>& first, QString& error) {
    error.clear();
    QStringList lines = inputData.split('\n', Qt::SkipEmptyParts);
    if (lines.size() < 2) { error = "输入至少需要两行"; return; }
    QStringList head = lines[0].split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    if (head.size() < 2) { error = "第一行需要数组长度与操作次数"; return; }
    bool ok = false;
    n = head[0].toInt(&ok);
    if (!ok || n < 0 || n > 200) { error = "n 需为 0-200 的整数"; n = 0; return; }
    m = head[1].toInt(&ok);
    if (!ok || m < 0 || m > 200) { error = "m 需为 0-200 的整数"; m = 0; return; }
    QStringList arrStrs = lines[1].split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    first.assign(n + 2, 0);
    for (int i = 1; i <= n && i - 1 < arrStrs.size(); ++i) first[i] = arrStrs[i - 1].toInt();
}

void TwoRowArrayModule::buildTwoRowLayout(QGraphicsScene* scene, const std::vector<int>& first,
                                          const std::vector<RowSpec>& rows) {
    const double cellW = 60.0;
    const int startX = 400 - ((m_n + 2) * static_cast<int>(cellW)) / 2;
    for (const RowSpec& row : rows) {
        QGraphicsTextItem* label = scene->addText(row.title);
        label->setFont(QFont("Microsoft YaHei UI", 12, QFont::Bold));
        label->setPos(startX - 100, row.y - 2);
        for (int i = 0; i < row.count; ++i) {
            const int dataIndex = row.startIndex + i;
            const int value = (row.offset == 0) ? first[dataIndex] : 0;
            ArrayBlock* block = new ArrayBlock(row.offset + dataIndex, value, QString::number(dataIndex));
            block->setPos(startX + dataIndex * cellW, row.y);
            if (row.hideExtra && value == 0 && row.offset != 0) block->showValue = false;
            scene->addItem(block);
            m_blocks[row.offset + dataIndex] = block;
            registerArraySlot(block, row.row, dataIndex);
        }
    }
}

ArrayBlock* TwoRowArrayModule::getBlock(int id) const {
    auto it = m_blocks.find(id);
    return it == m_blocks.end() ? nullptr : it->second;
}

void TwoRowArrayModule::renderTwoRowFrame(const AnimFrame& frame) {
    if (m_mathText && !frame.mathText.isEmpty()) m_mathText->setPlainText(frame.mathText);
    if (frame.type == ActionType::PD_HIGHLIGHT) {
        for (int id : frame.group) {
            ArrayBlock* block = getBlock(id);
            if (block) { block->color = QColor(255, 200, 100); block->update(); }
        }
    } else if (frame.type == ActionType::PD_UPDATE_VAL) {
        ArrayBlock* target = getBlock(frame.u);
        if (!target) return;
        const int finalVal = frame.val1;
        QPointer<ArrayBlock> safeTarget = target;
        if (m_animated && !frame.group.empty()) {
            target->showValue = false;
            target->update();
            QParallelAnimationGroup* group = new QParallelAnimationGroup(this);
            std::vector<QPointer<FloatingText>> texts;
            for (int srcId : frame.group) {
                ArrayBlock* src = getBlock(srcId);
                if (!src) continue;
                QPointer<FloatingText> ft = new FloatingText(QString::number(src->value));
                ft->setPos(src->pos());
                m_scene->addItem(ft.data());
                texts.push_back(ft);
                QPropertyAnimation* anim = new QPropertyAnimation(ft.data(), "pos");
                anim->setEndValue(target->pos());
                anim->setDuration(400);
                anim->setEasingCurve(QEasingCurve::InOutQuad);
                group->addAnimation(anim);
            }
            connect(group, &QParallelAnimationGroup::finished, [this, safeTarget, texts, finalVal]() {
                for (auto& t : texts) {
                    if (!t) continue;
                    if (t->scene()) t->scene()->removeItem(t.data());
                    delete t.data();
                }
                if (!safeTarget) return;
                safeTarget->value = finalVal;
                safeTarget->color = QColor(150, 255, 150);
                safeTarget->showValue = true;
                safeTarget->update();
                playScalePulse(safeTarget, 1.3, 300);
            });
            group->start(QAbstractAnimation::DeleteWhenStopped);
        } else {
            target->value = finalVal;
            target->color = QColor(150, 255, 150);
            target->showValue = true;
            target->update();
            if (m_animated) playScalePulse(target, 1.3, 300);
        }
    } else if (frame.type == ActionType::PD_RESET) {
        for (int id : frame.group) {
            ArrayBlock* block = getBlock(id);
            if (block) { block->color = Qt::white; block->update(); }
        }
    }
}

void TwoRowArrayModule::reset() {
    m_blocks.clear();
    m_frames.clear();
    m_mathText = nullptr;
    m_n = 0;
    m_m = 0;
}

void TwoRowArrayModule::releaseSceneItems() {
    m_blocks.clear();
    m_mathText = nullptr;
}

#include "PrefixSumModule.h"
#include <QRegularExpression>
#include <QFont>

PrefixSumModule::PrefixSumModule() {}

QString PrefixSumModule::getModuleName() const { return "前缀和"; }
QString PrefixSumModule::getDefaultInput() const { return "5 2\n3 1 2 5 4\n2 4\n1 5"; }

QString PrefixSumModule::getInputHint() const {
    return "第一行输入两个正整数：数组长度 n、查询次数 m\n"
           "第二行输入 n 个整数，即原数组 a[1..n]\n"
           "接下来 m 行，每行两个整数 l, r，表示一次区间 [l, r] 求和查询";
}

void PrefixSumModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    m_blocks.clear();
    m_frames.clear();
    m_queries.clear();
    m_dataA.clear();
    m_dataS.clear();

    QString error;
    parseTwoRowInput(inputData, m_n, m_m, m_dataA, error);
    if (!error.isEmpty()) {
        m_mathText = scene->addText("输入错误：" + error);
        m_mathText->setFont(QFont("Microsoft YaHei UI", 13, QFont::Bold));
        m_mathText->setDefaultTextColor(QColor(180, 50, 50));
        m_mathText->setPos(50, 30);
        return;
    }

    QStringList lines = inputData.split('\n', Qt::SkipEmptyParts);
    for (int i = 2; i < 2 + m_m && i < lines.size(); ++i) {
        QStringList q = lines[i].split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
        if (q.size() < 2) continue;
        int l = q[0].toInt();
        int r = q[1].toInt();
        if (l < 1) l = 1;
        if (r > m_n) r = m_n;
        if (l > r) std::swap(l, r);
        m_queries.push_back({l, r});
    }

    m_mathText = scene->addText("");
    m_mathText->setFont(QFont("Consolas", 18, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(180, 50, 50));
    m_mathText->setPos(300, 50);

    std::vector<RowSpec> rows;
    RowSpec rowA;
    rowA.row = "a";
    rowA.title = "原数组 a";
    rowA.startIndex = 1;
    rowA.count = m_n;
    rowA.offset = 0;
    rowA.y = 200.0;
    rows.push_back(rowA);

    RowSpec rowS;
    rowS.row = "s";
    rowS.title = "前缀和 s";
    rowS.startIndex = 0;
    rowS.count = m_n + 1;
    rowS.offset = 100;
    rowS.y = 350.0;
    rows.push_back(rowS);

    buildTwoRowLayout(scene, m_dataA, rows);
}

void PrefixSumModule::onLiveDataChanged(const QString& row, int index, int value) {
    if (row == "a" && index >= 1 && index <= m_n) {
        m_dataA[index] = value;
        return;
    }
    if (row == "s" && index >= 0 && index <= m_n) {
        m_dataS[index] = value;
    }
}

std::vector<AnimFrame> PrefixSumModule::runAlgorithm() {
    m_frames.clear();
    for (int i = 1; i <= m_n; ++i) m_dataA[i] = liveValue("a", i, m_dataA[i]);
    m_dataS.assign(m_n + 1, 0);
    m_frames.push_back({ActionType::PD_MATH_TEXT, 0, 0, 0, 0, {}, "1. 预处理构建前缀和数组 S", "S[i] = S[i-1] + a[i]"});
    for (int i = 1; i <= m_n; ++i) {
        m_dataS[i] = m_dataS[i - 1] + m_dataA[i];
        const int computed = m_dataS[i];
        m_dataS[i] = liveValue("s", i, computed);
        m_frames.push_back({ActionType::PD_HIGHLIGHT, 0, 0, 0, 0, {i, 100 + i - 1, 100 + i},
                            QString("S[%1] = S[%2] + a[%1]").arg(i).arg(i - 1),
                            QString("S[%1] = %2 + %3 = %4").arg(i).arg(m_dataS[i - 1]).arg(m_dataA[i]).arg(m_dataS[i])});
        m_frames.push_back({ActionType::PD_UPDATE_VAL, 100 + i, 0, m_dataS[i], 0, {i, 100 + i - 1}, "", ""});
        m_frames.push_back({ActionType::PD_RESET, 0, 0, 0, 0, {i, 100 + i - 1, 100 + i}, "", ""});
    }
    for (int q = 0; q < static_cast<int>(m_queries.size()); ++q) {
        const int l = m_queries[q].l;
        const int r = m_queries[q].r;
        m_frames.push_back({ActionType::PD_MATH_TEXT, 0, 0, 0, 0, {},
                            QString("查询 %1: 区间 [%2, %3]").arg(q + 1).arg(l).arg(r), ""});
        int sum = 0;
        QString bfStr = "暴力: ";
        std::vector<int> hl;
        for (int i = l; i <= r; ++i) {
            sum += m_dataA[i];
            hl.push_back(i);
            const QString currentMath = bfStr + (i == l ? QString::number(m_dataA[i]) : QString(" + %1").arg(m_dataA[i]));
            m_frames.push_back({ActionType::PD_HIGHLIGHT, 0, 0, 0, 0, {i},
                                QString("暴力扫描 a[%1]").arg(i), currentMath + QString(" = %1").arg(sum)});
            bfStr = currentMath;
        }
        m_frames.push_back({ActionType::PD_RESET, 0, 0, 0, 0, hl, "", ""});
        const int fast = m_dataS[r] - m_dataS[l - 1];
        m_frames.push_back({ActionType::PD_HIGHLIGHT, 0, 0, 0, 0, {100 + r, 100 + l - 1},
                            QString("优化: O(1) 查询 S[%1] - S[%2]").arg(r).arg(l - 1),
                            QString("O(1): S[%1] - S[%2] = %3 - %4 = %5").arg(r).arg(l - 1).arg(m_dataS[r]).arg(m_dataS[l - 1]).arg(fast)});
        m_frames.push_back({ActionType::PD_RESET, 0, 0, 0, 0, {100 + r, 100 + l - 1}, "", ""});
    }
    return m_frames;
}

void PrefixSumModule::renderFrame(const AnimFrame& frame) {
    renderTwoRowFrame(frame);
}

