static int countColor(const QImage& img, int r, int g, int b) {
    int n = 0;
    for (int y = 0; y < img.height(); ++y) {
        for (int x = 0; x < img.width(); ++x) {
            QColor c = img.pixelColor(x, y);
            if (c.red() > r && c.green() < g && c.blue() < b) ++n;
        }
    }
    return n;
}

