void SceneGrid::install(QGraphicsScene* scene) {
    if (!scene) return;
    if (dynamic_cast<GridGuideScene*>(scene)) return;
    GridGuideScene* guided = new GridGuideScene(scene);
    guided->setBackgroundBrush(scene->backgroundBrush());
    scene->setBackgroundBrush(guided->backgroundBrush());
    Q_UNUSED(guided);
}

void SceneGrid::uninstall(QGraphicsScene* scene) {
