static int countColor(const QImage& img, const QColor& want, int tol) {
    int n = 0;
    for (int y = 0; y < img.height(); ++y) {
        for (int x = 0; x < img.width(); ++x) {
            QColor c = img.pixelColor(x, y);
            if (std::abs(c.red() - want.red()) < tol &&
                std::abs(c.green() - want.green()) < tol &&
                std::abs(c.blue() - want.blue()) < tol) ++n;
        }
    }
    return n;
}

static int failures = 0;

static void check(bool ok, const char* label, const QString& detail) {
    printf("[%s] %s %s\n", ok ? "PASS" : "FAIL", label, detail.toUtf8().constData());
    if (!ok) ++failures;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    GridGuideScene scene;
    scene.setSceneRect(0, 0, 600, 400);
    QGraphicsView view(&scene);
    view.resize(600, 400);
    view.show();
    view.resetTransform();

    SceneGrid::Config cfg;
    cfg.enabled = true;
    cfg.showGuides = true;
    cfg.cell = 56.0;
    SceneGrid::setConfig(&scene, cfg);
    QApplication::processEvents();

    QImage img = view.viewport()->grab().toImage();
    const int gridPixels = countColor(img, UiTheme::canvasGrid(), 6);
    check(gridPixels > 500, "grid renders when enabled", QString("pixels=%1").arg(gridPixels));

    check(scene.items().isEmpty(), "grid adds no scene items", QString("items=%1").arg(scene.items().size()));
    check(!scene.itemsBoundingRect().isNull(), "grid keeps scene bounds valid",
          QString("bounds=%1,%2 %3x%4").arg(scene.itemsBoundingRect().x())
              .arg(scene.itemsBoundingRect().y())
              .arg(scene.itemsBoundingRect().width())
              .arg(scene.itemsBoundingRect().height()));

    SceneGrid::Config off = cfg;
    off.enabled = false;
    off.showGuides = false;
    SceneGrid::setConfig(&scene, off);
    QApplication::processEvents();
    img = view.viewport()->grab().toImage();
    const int gridPixelsOff = countColor(img, UiTheme::canvasGrid(), 6);
    check(gridPixelsOff < gridPixels / 2, "grid hidden when disabled",
          QString("on=%1 off=%2").arg(gridPixels).arg(gridPixelsOff));

    SceneGrid::setConfig(&scene, cfg);
    QApplication::processEvents();

    QGraphicsRectItem* rect = scene.addRect(0, 0, 100, 100);
    rect->setBrush(Qt::red);
    rect->setPen(Qt::NoPen);
    scene.clear();
    QApplication::processEvents();
    img = view.viewport()->grab().toImage();
    const int gridAfterClear = countColor(img, UiTheme::canvasGrid(), 6);
    check(gridAfterClear > 500, "grid survives scene clear", QString("pixels=%1").arg(gridAfterClear));

    MainWindow w;
    w.resize(1400, 900);
    w.show();
    app.processEvents();
    QGraphicsScene* appScene = w.findChild<QGraphicsScene*>();
    check(appScene != nullptr, "main window scene found", QString("found=%1").arg(appScene != nullptr));
    check(dynamic_cast<GridGuideScene*>(appScene) != nullptr, "main window uses GridGuideScene",
          QString("isGridScene=%1").arg(dynamic_cast<GridGuideScene*>(appScene) != nullptr));

    printf("\n%s failures=%d\n", failures == 0 ? "ALL PASS" : "FAILED", failures);
    return failures == 0 ? 0 : 1;
}

