class Probe : public QGraphicsRectItem {
public:
    explicit Probe(QGraphicsScene* s) : QGraphicsRectItem(0, 0, 100, 100, s) {
        setBrush(Qt::red);
        setPen(Qt::NoPen);
    }
    void mousePressEvent(QGraphicsSceneMouseEvent* event) override {
        ++presses;
        QGraphicsRectItem::mousePressEvent(event);
    }
    int presses = 0;
};

class OverlayView : public QGraphicsView {
public:
    explicit OverlayView(QWidget* parent = nullptr) : QGraphicsView(parent) {
        m_overlay = new QGraphicsScene(this);
    }
    QGraphicsScene* overlay() const { return m_overlay; }

protected:
    void drawForeground(QPainter* painter, const QRectF& rect) override {
        QGraphicsView::drawForeground(painter, rect);
        if (!m_overlay || m_overlay->items().isEmpty()) return;
        painter->save();
        QRectF sceneRect = QRectF(mapToScene(viewport()->rect().topLeft()),
                                  mapToScene(viewport()->rect().bottomRight()));
        m_overlay->render(painter, sceneRect, sceneRect, Qt::IgnoreAspectRatio);
        painter->restore();
    }

private:
    QGraphicsScene* m_overlay = nullptr;
};

