    printf("baseItemPresses=%d (expect 1 -> overlay does NOT steal hit-testing)\n", p->presses);
    printf("baseItems=%d overlayItems=%d\n", base->items().size(), view.overlay()->items().size());
    printf("baseItemsBoundingRect=%g,%g %gx%g (must exclude overlay ink)\n",
           base->itemsBoundingRect().x(), base->itemsBoundingRect().y(),
           base->itemsBoundingRect().width(), base->itemsBoundingRect().height());

