static void collectJs(const QString& root, const QString& rel, QJSValue* out, QJSEngine* engine) {
    QDir dir(root + rel);
    if (!dir.exists()) return;
    for (const QString& name : dir.entryList(QDir::Files | QDir::Dirs, QDir::Name)) {
        if (name.startsWith(".")) continue;
        const QString childRel = rel.isEmpty() ? name : rel + "/" + name;
        if (name.endsWith(".js")) {
            QFile f(root + childRel);
            if (!f.open(QIODevice::ReadOnly)) continue;
            const QByteArray d = f.readAll();
            f.close();
            out->setProperty(childRel, QString::fromUtf8(d));
        } else {
            collectJs(root, childRel, out, engine);
        }
    }
}

