const fs = require('fs');
const path = require('path');
const { mathjax } = require('mathjax-full/js/mathjax.js');
const { TeX } = require('mathjax-full/js/input/tex.js');
const { SVG } = require('mathjax-full/js/output/svg.js');
const { liteAdaptor } = require('mathjax-full/js/adaptors/liteAdaptor.js');
const { RegisterHTMLHandler } = require('mathjax-full/js/handlers/html.js');
const { AllPackages } = require('mathjax-full/js/input/tex/AllPackages.js');

const adaptor = liteAdaptor();
RegisterHTMLHandler(adaptor);
const tex = new TeX({ packages: AllPackages });
const svg = new SVG({ fontCache: 'none' });
const html = mathjax.document('', { InputJax: tex, OutputJax: svg });

function renderOne(src) {
    const node = html.convert(src, { display: true });
    let markup = adaptor.outerHTML(node);
    const viewBox = /viewBox="([^"]+)"/.exec(markup);
    let width = 0, height = 0;
    if (viewBox) {
        const parts = viewBox[1].split(/\s+/).map(Number);
        width = parts[2]; height = parts[3];
    }
    markup = markup.replace(/<mjx-container[^>]*>/, '').replace(/<\/mjx-container>/, '');
    return { tex: src, svg: markup, width, height };
}

const tmp = path.join(__dirname, '..', 'build', 'latex_srv');
fs.mkdirSync(tmp, { recursive: true });
const inFile = path.join(tmp, 'req.json');
const outFile = path.join(tmp, 'res.json');

let busy = false;
function pump() {
    if (busy) return;
    busy = true;
    try {
        if (!fs.existsSync(inFile)) { busy = false; return; }
        const raw = fs.readFileSync(inFile, 'utf8').trim();
        if (!raw) { busy = false; return; }
        const req = JSON.parse(raw);
        const result = { id: req.id, ok: true, formula: renderOne(req.tex) };
        fs.writeFileSync(outFile, JSON.stringify(result));
        fs.writeFileSync(inFile, '');
    } catch (e) {
        try { fs.writeFileSync(outFile, JSON.stringify({ ok: false, error: String(e && e.message || e) })); } catch (e2) {}
    }
    busy = false;
}

setInterval(pump, 30);
console.log('latex-server-ready');

