void GraphNode::beginEdit() {
    if (!m_editable || !m_editor.isNull()) return;
    QGraphicsScene* sc = scene();
    if (!sc) return;
    QString current = valueText.isEmpty() ? QString::number(value) : valueText;
    m_editor = sc->addText(current);

void GraphNode::beginEdit() {
    if (!m_editable || !m_editor.isNull()) return;
    QGraphicsScene* sc = scene();
    if (!sc) return;
    QString current = ownValueText();
    if (current.isEmpty()) current = QString::number(value);
    m_editor = sc->addText(current);

void GraphNode::commitEdit() {
    if (m_editor.isNull()) return;
    QString text = m_editor->toPlainText().trimmed();
    destroyEditor(m_editor);
    update();
    if (text.isEmpty()) return;
    bool ok = false;
    int parsed = text.toInt(&ok);
    if (ok) {
        value = parsed;
        if (!customValueText.isEmpty()) setCustomValueText(QString::number(parsed));
        else setValueText(QString("v:%1").arg(parsed));
    } else {
        if (!customValueText.isEmpty()) setCustomValueText(text);
        else setValueText(text);
    }
    update();
    emit valueEdited(id, text);
}

void GraphNode::commitEdit() {
    if (m_editor.isNull()) return;
    QString text = m_editor->toPlainText().trimmed();
    destroyEditor(m_editor);
    update();
    if (text.isEmpty()) return;
    bool ok = false;
    int parsed = text.toInt(&ok);
    if (ok) {
        value = parsed;
        if (!customValueText.isEmpty()) setCustomValueText(QString::number(parsed));
        else setValueText(text);
    } else {
        if (!customValueText.isEmpty()) setCustomValueText(text);
        else setValueText(text);
    }
    update();
    emit valueEdited(id, text);
}

