class ProbeView : public QGraphicsView {
public:
    int strategy = 0;
protected:
    void drawForeground(QPainter* painter, const QRectF& rect) override {
        QGraphicsView::drawForeground(painter, rect);
        if (!g_overlay) return;
        painter->save();
        if (strategy == 1) {
            painter->setTransform(transform().inverted(), false);
            QRectF src = g_overlay->itemsBoundingRect();
            QRectF dst = transform().inverted().mapRect(src);
            g_overlay->render(painter, src, dst, Qt::IgnoreAspectRatio);
        } else if (strategy == 2) {
            QRectF src = g_overlay->itemsBoundingRect();
            g_overlay->render(painter, src, src, Qt::IgnoreAspectRatio);
        } else if (strategy == 3) {
            painter->setTransform(transform().inverted(), false);
            QRectF src = g_overlay->itemsBoundingRect();
            g_overlay->render(painter, QRectF(), QRectF(), Qt::IgnoreAspectRatio);
        } else if (strategy == 4) {
            for (QGraphicsItem* item : g_overlay->items()) {
                QPainterPath path;
                path.addEllipse(QPointF(0, 0), 30, 30);
                painter->setBrush(Qt::blue);
                painter->setPen(Qt::NoPen);
                painter->drawPath(path);
            }
        }
        painter->restore();
    }
};

static QImage renderWith(int strategy) {
    QGraphicsScene base;
    base.setSceneRect(-200, -200, 800, 600);
    base.setBackgroundBrush(Qt::white);
    QGraphicsRectItem* r = base.addRect(-50, -50, 100, 100);
    r->setBrush(Qt::red);

    QGraphicsScene overlay;
    QGraphicsEllipseItem* e = overlay.addEllipse(-30, -30, 60, 60);
    e->setBrush(Qt::blue);
    g_overlay = &overlay;

    ProbeView view(&base);
    view.strategy = strategy;
    view.resize(400, 300);
    view.setSceneRect(-200, -200, 800, 600);
    view.setBackgroundBrush(Qt::white);
    view.show();
    QApplication::processEvents();
    QImage img = view.grab().toImage();
    return img;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    for (int s = 1; s <= 4; ++s) {
        QImage img = renderWith(s);
        QColor at0 = img.pixelColor(200, 150);
        QColor at1 = img.pixelColor(200 + 15, 150);
        printf("strategy %d: center=%s  blueish=%s\n", s, at0.name().toUtf8().constData(),
               at1.name().toUtf8().constData());
        img.save(QString("probe_strategy_%1.png").arg(s));
    }
    return 0;
}

#include <QApplication>
#include <QGraphicsScene>
