#include "LatexService.h"
#include <QCoreApplication>
#include <QDir>
#include <QFileInfo>
#include <QJsonDocument>
#include <QJsonObject>
#include <QStandardPaths>
#include <QTimer>

namespace {
QString findHelperScript() {
    const QStringList candidates = {
        QCoreApplication::applicationDirPath() + "/tools/latex/serve.js",
        QCoreApplication::applicationDirPath() + "/../tools/latex/serve.js",
        QCoreApplication::applicationDirPath() + "/../../tools/latex/serve.js",
        QCoreApplication::applicationDirPath() + "/../../../tools/latex/serve.js",
        QDir::current().absoluteFilePath("tools/latex/serve.js")
    };
    for (const QString& path : candidates) {
        if (QFileInfo::exists(path)) return QFileInfo(path).absoluteFilePath();
    }
    return QString();
}

QString findNodeExe() {
    const QString local = QCoreApplication::applicationDirPath() + "/node.exe";
    if (QFileInfo::exists(local)) return local;
    return QStringLiteral("node");
}
}

LatexService* LatexService::instance() {
    static LatexService* s_instance = new LatexService();
    return s_instance;
}

LatexService::LatexService(QObject* parent) : QObject(parent) {}

bool LatexService::isAvailable() const {
    if (m_failed) return false;
    return !findHelperScript().isEmpty();
}

void LatexService::ensureStarted() {
    if (m_process) return;
    const QString script = findHelperScript();
    if (script.isEmpty()) {
        m_failed = true;
        m_lastError = "未找到 tools/latex/serve.js";
        return;
    }
    m_process = new QProcess(this);
    m_process->setWorkingDirectory(QFileInfo(script).absolutePath());
    connect(m_process, &QProcess::readyReadStandardOutput, this, [this]() {
        while (m_process->canReadLine()) {
            const QString line = QString::fromUtf8(m_process->readLine()).trimmed();
            if (line.isEmpty()) continue;
            QJsonParseError err;
            const QJsonDocument doc = QJsonDocument::fromJson(line.toUtf8(), &err);
            if (err.error != QJsonParseError::NoError || !doc.isObject()) continue;
            const QJsonObject obj = doc.object();
            const int id = obj.value("id").toInt();
            const QString tex = m_pending.take(id);
            if (tex.isEmpty()) continue;
            if (!obj.value("ok").toBool()) continue;
            emit rendered(tex,
                          obj.value("svg").toString(),
                          obj.value("width").toDouble(),
                          obj.value("height").toDouble());
        }
    });
    connect(m_process, &QProcess::errorOccurred, this, [this](QProcess::ProcessError) {
        m_failed = true;
    });
    m_process->start(findNodeExe(), {script});
    if (!m_process->waitForStarted(3000)) {
        m_failed = true;
        m_lastError = "无法启动 Node 渲染助手";
    }
}

QString LatexService::render(const QString& tex, bool* ok, QSize* size) {
    if (ok) *ok = false;
    if (size) *size = QSize();
    ensureStarted();
    if (!m_process || m_process->state() != QProcess::Running) return QString();

    const int id = m_nextId++;
    m_pending.insert(id, tex);
    QJsonObject request;
    request["id"] = id;
    request["src"] = tex;
    m_process->write(QJsonDocument(request).toJson(QJsonDocument::Compact) + "\n");
    m_process->flush();

    QEventLoop loop;
    bool finished = false;
    QString result;
    double w = 0.0;
    double h = 0.0;
    QMetaObject::Connection conn = connect(this, &LatexService::rendered, &loop, [&](const QString& src, const QString& svg, double width, double height) {
        if (src != tex) return;
        result = svg;
        w = width;
        h = height;
        finished = true;
        loop.quit();
    });
    QTimer::singleShot(4000, &loop, [&loop]() { loop.quit(); });
    if (!finished) {
        loop.exec();
    }
    disconnect(conn);
    if (ok) *ok = !result.isEmpty();
    if (size) *size = QSize(static_cast<int>(w), static_cast<int>(h));
    return result;
}

void LatexService::send(const QString& tex) {
    ensureStarted();
    if (!m_process || m_process->state() != QProcess::Running) return;
    QJsonObject request;
    request["id"] = m_nextId++;
    request["src"] = tex;
    m_process->write(QJsonDocument(request).toJson(QJsonDocument::Compact) + "\n");
    m_process->flush();
}

