void ToolController::setTool(Tool tool) {
    if (m_tool == tool) return;
    if (m_drawing) finishStroke();
    m_tool = tool;
    if (m_view) {
        if (m_view->toolController() == this) {
            if (m_tool == Select) m_view->setDragMode(QGraphicsView::ScrollHandDrag);
            else m_view->setDragMode(QGraphicsView::NoDrag);
            m_view->viewport()->setCursor(m_tool == Select ? Qt::OpenHandCursor : Qt::CrossCursor);
