void ToolController::pushCommand(const Command& cmd) {
    m_undoStack.push_back(cmd);
    if (m_undoStack.size() > 120) m_undoStack.removeFirst();
    m_redoStack.clear();
    emit historyChanged(canUndo(), canRedo());
}

bool ToolController::undo() {
    if (m_undoStack.isEmpty()) return false;
    const Command cmd = m_undoStack.takeLast();
    for (int i = cmd.items.size() - 1; i >= 0; --i) {
        AnnotationItem* item = cmd.items.at(i);
        if (!item) continue;
        if (cmd.kind == Command::Add) {
            if (item->scene()) m_scene->removeItem(item);
            else item->deleteLater();
        }
    }
    if (cmd.kind == Command::Modify) {
        for (AnnotationItem* item : cmd.items) {
            if (auto* text = qgraphicsitem_cast<TextBoxItem*>(item)) {
                text->setPlainText(cmd.before);
            } else if (auto* md = qgraphicsitem_cast<MarkdownItem*>(item)) {
                md->setMarkdown(cmd.before);
            } else if (auto* latex = qgraphicsitem_cast<LatexItem*>(item)) {
                latex->setSvg(cmd.before, latex->contentBounds().width(), latex->contentBounds().height());
            }
        }
    }
    m_redoStack.push_back(cmd);
    emit historyChanged(canUndo(), canRedo());
    return true;
}

bool ToolController::redo() {
    if (m_redoStack.isEmpty()) return false;
    const Command cmd = m_redoStack.takeLast();
    if (cmd.kind == Command::Add) {
        for (AnnotationItem* item : cmd.items) {
            if (item && !item->scene()) m_scene->addItem(item);
        }
    } else if (cmd.kind == Command::Modify) {
        for (AnnotationItem* item : cmd.items) {
            if (auto* text = qgraphicsitem_cast<TextBoxItem*>(item)) {
                text->setPlainText(cmd.after);
            } else if (auto* md = qgraphicsitem_cast<MarkdownItem*>(item)) {
                md->setMarkdown(cmd.after);
            }
        }
    }
    m_undoStack.push_back(cmd);
    emit historyChanged(canUndo(), canRedo());
    return true;
}

void ToolController::clearAll() {
    const QVector<AnnotationItem*> all = m_scene->annotationItems();
    if (all.isEmpty()) return;
    Command cmd;
    cmd.kind = Command::Add;
    cmd.items = all;
    for (AnnotationItem* item : all) {
        m_scene->removeItem(item);
    }
    pushCommand(cmd);
    emit statusMessage("已清空批注层");
}

bool ToolController::exportToFile(const QString& path, QString* error) {
    QFile file(path);
    if (!file.open(QIODevice::WriteOnly)) {
        if (error) *error = "无法写入文件: " + path;
        return false;
    }
    const QJsonObject obj = m_scene->toJson();
    file.write(QJsonDocument(obj).toJson(QJsonDocument::Indented));
    file.close();
    return true;
}

bool ToolController::eventFilter(QObject* obj, QEvent* event) {
    if (!m_view || obj != m_view->viewport()) return false;

    if (event->type() == QEvent::MouseButtonPress) {
        onMousePress(static_cast<QGraphicsSceneMouseEvent*>(event));
        return isDrawingTool();
    }
    if (event->type() == QEvent::MouseMove) {
        onMouseMove(static_cast<QGraphicsSceneMouseEvent*>(event));
        return isDrawingTool();
    }
    if (event->type() == QEvent::MouseButtonRelease) {
        onMouseRelease(static_cast<QGraphicsSceneMouseEvent*>(event));
        return isDrawingTool();
    }
    if (event->type() == QEvent::KeyPress) {
        onKeyPress(static_cast<QKeyEvent*>(event));
        return false;
    }
    return false;
}

void ToolController::onMousePress(QGraphicsSceneMouseEvent* event) {
    if (!m_scene) return;
    const QPointF pos = event->scenePos();

    switch (m_tool) {
    case Pen:
        beginStroke(pos);
        break;
    case Eraser:
        eraseAt(pos);
        break;
    case Line:
    case Rect:
    case Circle:
    case Arrow:
    case Triangle:
        beginShape(pos);
        break;
    case Mosaic:
        beginMosaic(pos);
        break;
    default:
        break;
    }
    event->accept();
}

void ToolController::onMouseMove(QGraphicsSceneMouseEvent* event) {
    if (!m_drawing) return;
    const QPointF pos = event->scenePos();
    m_currentPos = pos;
    if (m_activeStroke) updateStroke(pos);
    if (m_activeShape) updateShape(pos);
    if (m_tool == Mosaic) updateMosaic(pos);
    event->accept();
}

void ToolController::onMouseRelease(QGraphicsSceneMouseEvent* event) {
    if (!m_drawing) return;
    if (m_tool == Pen) finishStroke();
    else if (m_tool == Mosaic) finishMosaic();
    else if (m_activeShape) finishShape();
    event->accept();
}

void ToolController::onKeyPress(QKeyEvent* event) {
    if (event->key() == Qt::Key_Z && (event->modifiers().testFlag(Qt::ControlModifier))) {
        if (event->modifiers().testFlag(Qt::ShiftModifier)) redo();
        else undo();
        event->accept();
        return;
    }
    if (event->key() == Qt::Key_Y && event->modifiers().testFlag(Qt::ControlModifier)) {
        redo();
        event->accept();
        return;
    }
}

