void ToolController::onMousePress(QGraphicsSceneMouseEvent* event) {
    if (!m_scene) return;
    const QPointF pos = event->scenePos();
    m_modifiers = event->modifiers();

    switch (m_tool) {
    case Pen:
        beginStroke(pos);
        break;
    case Eraser:
        eraseAt(pos);
        break;
    case Line:
    case Rect:
    case Circle:
    case Arrow:
    case Triangle:
        beginShape(pos);
        break;
    case Mosaic:
        beginMosaic(pos);
        break;
    case TextBox:
    case Markdown:
    case Latex:
    case Table:
        createItemForTool(pos);
