class FlowLayout : public QLayout {
    Q_OBJECT
public:
    explicit FlowLayout(QWidget* parent, int margin = -1);
    ~FlowLayout() override;

    void addItem(QLayoutItem* item) override;
    int horizontalSpacing() const;
    int verticalSpacing() const;
    void setHorizontalSpacing(int spacing);
    void setVerticalSpacing(int spacing);

    QSize sizeHint() const override;
    QSize minimumSize() const override;
    int count() const override;
    QLayoutItem* itemAt(int index) const override;
    QLayoutItem* takeAt(int index) override;
    QSize expandingDirections(const QRect& rect) const override;
    bool hasHeightForWidth() const override;
    int heightForWidth(int width) const override;
    int minimumHeightForWidth(int width) const override;
    void setGeometry(const QRect& rect) override;
    QSize sizeHintForItem(int index) const;
    QSize minimumSizeForItem(int index) const;

private:
    int doLayout(const QRect& rect, bool testOnly) const;
    int m_hSpace = 8;
    int m_vSpace = 8;
};

#endif

#include "FlowLayout.h"
#include <QWidget>

FlowLayout::FlowLayout(QWidget* parent, int margin) : QLayout(parent) {
    if (margin >= 0) setContentsMargins(margin, margin, margin, margin);
}

FlowLayout::~FlowLayout() {
    while (QLayoutItem* item = takeAt(0)) {
        delete item;
    }
}

void FlowLayout::addItem(QLayoutItem* item) {
    if (item) QLayout::addItem(item);
}

int FlowLayout::horizontalSpacing() const { return m_hSpace; }
int FlowLayout::verticalSpacing() const { return m_vSpace; }

void FlowLayout::setHorizontalSpacing(int spacing) {
    m_hSpace = spacing;
    invalidate();
}

void FlowLayout::setVerticalSpacing(int spacing) {
    m_vSpace = spacing;
    invalidate();
}

int FlowLayout::count() const { return QLayout::count(); }

QLayoutItem* FlowLayout::itemAt(int index) const { return QLayout::itemAt(index); }

QLayoutItem* FlowLayout::takeAt(int index) { return QLayout::takeAt(index); }

QSize FlowLayout::expandingDirections(const QRect& rect) const {
    Q_UNUSED(rect);
    return Qt::Orientations();
}

bool FlowLayout::hasHeightForWidth() const { return true; }

int FlowLayout::heightForWidth(int width) const {
    return doLayout(QRect(0, 0, width, 0), true);
}

int FlowLayout::minimumHeightForWidth(int width) const {
    Q_UNUSED(width);
    return minimumSize().height();
}

int FlowLayout::doLayout(const QRect& rect, bool testOnly) const {
    QRect effective = rect;
    effective.adjust(contentsMargins().left(), contentsMargins().top(),
                     -contentsMargins().right(), -contentsMargins().bottom());
    int x = effective.x();
    int y = effective.y();
    int lineHeight = 0;
    int maxWidth = effective.width();

    for (int i = 0; i < count(); ++i) {
        QLayoutItem* item = itemAt(i);
        if (!item || item->isEmpty()) continue;
        QWidget* widget = item->widget();
        if (widget && widget->isHidden()) continue;

        int spaceX = horizontalSpacing();
        int spaceY = verticalSpacing();
        if (widget) {
            if (spaceX < 0) spaceX = widget->style()->layoutSpacing(QSizePolicy::PushButton, QSizePolicy::PushButton, Qt::Horizontal);
            if (spaceY < 0) spaceY = widget->style()->layoutSpacing(QSizePolicy::PushButton, QSizePolicy::PushButton, Qt::Vertical);
        }
        spaceX = qMax(0, spaceX);
        spaceY = qMax(0, spaceY);

        const QSize itemSize = item->sizeHint();
        int next = x + itemSize.width();
        int nextLine = y + lineHeight + spaceY;
        if (next - effective.x() > maxWidth && lineHeight > 0) {
            x = effective.x();
            y = nextLine;
            next = x + itemSize.width();
            nextLine = y + lineHeight + spaceY;
        }
        if (!testOnly) {
            item->setGeometry(QRect(QPoint(x, y), itemSize));
        }
        x = next + spaceX;
        lineHeight = qMax(lineHeight, itemSize.height());
    }
    return y + lineHeight - rect.y() + contentsMargins().bottom();
}

void FlowLayout::setGeometry(const QRect& rect) {
    QLayout::setGeometry(rect);
    doLayout(rect, false);
}

QSize FlowLayout::sizeHint() const {
    return minimumSize();
}

QSize FlowLayout::minimumSize() const {
    QSize size;
    int lineWidth = 0;
    int lineHeight = 0;
    int maxLineWidth = 0;

    for (int i = 0; i < count(); ++i) {
        QLayoutItem* item = itemAt(i);
        if (!item || item->isEmpty()) continue;
        QWidget* widget = item->widget();
        if (widget && widget->isHidden()) continue;
        const QSize itemSize = item->sizeHint();
        lineWidth += itemSize.width();
        lineHeight = qMax(lineHeight, itemSize.height());
        maxLineWidth = qMax(maxLineWidth, lineWidth);
        int spaceX = horizontalSpacing();
        int spaceY = verticalSpacing();
        if (widget) {
            if (spaceX < 0) spaceX = widget->style()->layoutSpacing(QSizePolicy::PushButton, QSizePolicy::PushButton, Qt::Horizontal);
            if (spaceY < 0) spaceY = widget->style()->layoutSpacing(QSizePolicy::PushButton, QSizePolicy::PushButton, Qt::Vertical);
        }
        lineWidth += qMax(0, spaceX);
    }
    size.setWidth(maxLineWidth);
    size.setHeight(lineHeight);
    return size;
}

QSize FlowLayout::sizeHintForItem(int index) const {
    if (index < 0 || index >= count()) return QSize();
    return itemAt(index)->sizeHint();
}

QSize FlowLayout::minimumSizeForItem(int index) const {
    if (index < 0 || index >= count()) return QSize();
    return itemAt(index)->minimumSize();
}

