QString toolGlyph(ToolController::Tool tool) {
    switch (tool) {
    case ToolController::Select: return QString::fromUtf8("\xE7B3");
    case ToolController::AnnotationSelect: return QString::fromUtf8("\xE8A5");
    case ToolController::Pen: return QString::fromUtf8("\xE795");
    case ToolController::Eraser: return QString::fromUtf8("\xE75C");
    case ToolController::Line: return QString::fromUtf8("\xE8AB");
    case ToolController::Rect: return QString::fromUtf8("\xE7A4");
    case ToolController::Circle: return QString::fromUtf8("\xE81E");
    case ToolController::Arrow: return QString::fromUtf8("\xE88A");
    case ToolController::Triangle: return QString::fromUtf8("\xE7C5");
    case ToolController::Mosaic: return QString::fromUtf8("\xE8B3");
    case ToolController::TextBox: return QString::fromUtf8("\xE8D2");
    case ToolController::Markdown: return QString::fromUtf8("\xE8D5");
    case ToolController::Latex: return QString::fromUtf8("\xF0B4");
    case ToolController::Table: return QString::fromUtf8("\xE80C");
    default: return QString();
    }
}

QString toolLabel(ToolController::Tool tool) {
