CanvasToolBar::CanvasToolBar(ToolController* controller, QWidget* parent)
    : QWidget(parent), m_controller(controller) {
    setObjectName("canvasToolBar");
    setAttribute(Qt::WA_TranslucentBackground, true);

    QVBoxLayout* root = new QVBoxLayout(this);
    root->setContentsMargins(10, 8, 10, 8);
    root->setSpacing(8);

    FlowLayout* flow = new FlowLayout(this);
    flow->setHorizontalSpacing(6);
    flow->setVerticalSpacing(6);
    root->addLayout(flow);

    buildToolButtons();
    buildStyleBar();
}

void CanvasToolBar::buildToolButtons() {
    FlowLayout* flow = nullptr;
    for (int i = 0; i < layout()->count(); ++i) {
        if (auto* f = qobject_cast<FlowLayout*>(layout()->itemAt(i)->layout())) {
            flow = f;
            break;
        }
    }
    if (!flow) {
        flow = new FlowLayout(this);
        layout()->addItem(flow);
    }

    const ToolController::Tool tools[] = {
        ToolController::Select, ToolController::AnnotationSelect, ToolController::Pen,
        ToolController::Eraser, ToolController::Line, ToolController::Rect,
        ToolController::Circle, ToolController::Arrow, ToolController::Triangle,
        ToolController::Mosaic, ToolController::TextBox, ToolController::Markdown,
        ToolController::Latex, ToolController::Table
    };

    for (ToolController::Tool tool : tools) {
        auto* button = new ToolIconButton(toolLabel(tool), toolGlyph(tool), this);
        button->setVariant(MyButton::Ghost);
        connect(button, &MyButton::clicked, this, [this, tool]() {
            m_controller->setTool(tool);
        });
        m_toolButtons.push_back(button);
        flow->addWidget(button);
    }
}

void CanvasToolBar::buildStyleBar() {
    QWidget* styleBar = new QWidget(this);
    styleBar->setObjectName("canvasStyleBar");
    QHBoxLayout* layout = new QHBoxLayout(styleBar);
    layout->setContentsMargins(0, 0, 0, 0);
    layout->setSpacing(8);

    MyColorSwatch* swatch = new MyColorSwatch(styleBar);
    swatch->setColor(m_controller->penColor());
    connect(swatch, &MyColorSwatch::colorPicked, this, [this](const QColor& c) {
        m_controller->setPenColor(c);
    });
    layout->addWidget(swatch);

    QLabel* widthLabel = new QLabel("粗细", styleBar);
    widthLabel->setObjectName("canvasToolLabel");
    layout->addWidget(widthLabel);

    auto* widthSlider = new MySlider(styleBar);
    widthSlider->setRange(1, 16);
    widthSlider->setValue(static_cast<int>(m_controller->penWidth()));
    widthSlider->setFixedWidth(120);
    connect(widthSlider, &MySlider::valueChanged, this, [this](int v) {
        m_controller->setPenWidth(v);
    });
    layout->addWidget(widthSlider);

    QLabel* opacityLabel = new QLabel("不透明度", styleBar);
    opacityLabel->setObjectName("canvasToolLabel");
    layout->addWidget(opacityLabel);

    auto* opacitySlider = new MySlider(styleBar);
    opacitySlider->setRange(10, 100);
    opacitySlider->setValue(static_cast<int>(m_controller->opacity() * 100));
    opacitySlider->setFixedWidth(110);
    connect(opacitySlider, &MySlider::valueChanged, this, [this](int v) {
        m_controller->setOpacity(v / 100.0);
    });
    layout->addWidget(opacitySlider);

    m_btnUndo = new MyButton("撤销", styleBar);
    m_btnUndo->setVariant(MyButton::Ghost);
    m_btnUndo->setCompact(true);
    connect(m_btnUndo, &MyButton::clicked, this, [this]() { m_controller->undo(); });
    layout->addWidget(m_btnUndo);

    m_btnRedo = new MyButton("重做", styleBar);
    m_btnRedo->setVariant(MyButton::Ghost);
    m_btnRedo->setCompact(true);
    connect(m_btnRedo, &MyButton::clicked, this, [this]() { m_controller->redo(); });
    layout->addWidget(m_btnRedo);

    m_btnVisibility = new MyButton("隐藏批注", styleBar);
    m_btnVisibility->setVariant(MyButton::Ghost);
    m_btnVisibility->setCompact(true);
    layout->addWidget(m_btnVisibility);

    m_btnLock = new MyButton("锁定批注", styleBar);
    m_btnLock->setVariant(MyButton::Ghost);
    m_btnLock->setCompact(true);
    layout->addWidget(m_btnLock);

    layout->addStretch(1);

    FlowLayout* flow = nullptr;
    for (int i = 0; i < layout()->count(); ++i) {
        if (auto* f = qobject_cast<FlowLayout*>(this->layout()->itemAt(i)->layout())) {
            flow = f;
            break;
        }
    }
    if (flow) flow->addWidget(styleBar);
    else this->layout()->addWidget(styleBar);

    connect(m_controller, &ToolController::historyChanged, this, [this](bool canUndo, bool canRedo) {
        if (m_btnUndo) m_btnUndo->setEnabled(canUndo);
        if (m_btnRedo) m_btnRedo->setEnabled(canRedo);
    });
}

