bool ToolController::eventFilter(QObject* obj, QEvent* event) {
    if (!m_view || obj != m_view->viewport()) return false;

    switch (event->type()) {
    case QEvent::MouseButtonPress:
        onMousePress(static_cast<QGraphicsSceneMouseEvent*>(event));
        return isDrawingTool();
    case QEvent::MouseMove:
        onMouseMove(static_cast<QGraphicsSceneMouseEvent*>(event));
        return isDrawingTool();
    case QEvent::MouseButtonRelease:
        onMouseRelease(static_cast<QGraphicsSceneMouseEvent*>(event));
        return isDrawingTool();
    case QEvent::KeyPress:
        onKeyPress(static_cast<QKeyEvent*>(event));
        return false;
    default:
        break;
    }
    return false;
}

void ToolController::onMousePress(QGraphicsSceneMouseEvent* event) {
    if (!m_scene) return;
    const QPointF pos = event->scenePos();
    m_modifiers = event->modifiers();

    switch (m_tool) {
    case Pen:
        beginStroke(pos);
        break;
    case Eraser:
        eraseAt(pos);
        break;
    case Line:
    case Rect:
    case Circle:
    case Arrow:
    case Triangle:
        beginShape(pos);
        break;
    case Mosaic:
        beginMosaic(pos);
        break;
    case TextBox:
    case Markdown:
    case Latex:
    case Table:
        createItemForTool(pos);
        break;
    default:
        break;
    }
    event->accept();
}

void ToolController::onMouseMove(QGraphicsSceneMouseEvent* event) {
    if (!m_drawing) return;
    m_modifiers = event->modifiers();
    const QPointF pos = event->scenePos();
    m_currentPos = pos;
    if (m_activeStroke) updateStroke(pos);
    if (m_activeShape && m_tool != Mosaic) updateShape(pos);
    if (m_tool == Mosaic) updateMosaic(pos);
    event->accept();
}

void ToolController::onMouseRelease(QGraphicsSceneMouseEvent* event) {
    if (!m_drawing) return;
    m_modifiers = event->modifiers();
    if (m_tool == Pen) finishStroke();
    else if (m_tool == Mosaic) finishMosaic();
    else if (m_activeShape) finishShape();
    event->accept();
}

