class ProbeView : public QGraphicsView {
public:
    QGraphicsScene* overlay = nullptr;
    void drawForeground(QPainter* painter, const QRectF& rect) override {
        QGraphicsView::drawForeground(painter, rect);
        if (!overlay) return;
        const QRectF items = overlay->itemsBoundingRect();
        if (items.isEmpty()) return;
        painter->save();
        const int mode = m_mode;
        if (mode == 0) {
            painter->setTransform(transform(), false);
            overlay->render(painter, items, items, Qt::IgnoreAspectRatio);
        } else if (mode == 1) {
            overlay->render(painter, items, items, Qt::IgnoreAspectRatio);
        } else if (mode == 2) {
            painter->setTransform(transform(), false);
            overlay->render(painter, items, items, Qt::KeepAspectRatio);
        } else {
            painter->resetTransform();
            overlay->render(painter, transform().mapRect(items), items, Qt::IgnoreAspectRatio);
        }
        painter->restore();
    }
    int m_mode = 0;
};

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    for (int mode = 0; mode < 4; ++mode) {
        QGraphicsScene base;
        base.setSceneRect(0, 0, 400, 300);
        base.setBackgroundBrush(Qt::white);
        QGraphicsScene overlay;
        auto* e = new QGraphicsEllipseItem(50, 50, 100, 80);
        e->setBrush(Qt::red);
        overlay.addItem(e);

        ProbeView view(&base);
        view.overlay = &overlay;
        view.m_mode = mode;
        view.resize(400, 300);
        view.show();
        QEventLoop loop;
        QTimer::singleShot(250, &loop, &QEventLoop::quit);
        loop.exec();
        QImage img = view.grab().toImage();
        int red = 0;
        for (int y = 0; y < img.height(); ++y)
            for (int x = 0; x < img.width(); ++x)
                if (img.pixelColor(x, y).red() > 200 && img.pixelColor(x, y).green() < 120) ++red;
        printf("mode %d: red pixels = %d\n", mode, red);
    }
    return 0;
}

