#include <QEvent>

namespace {

class ToolDockSurface : public QWidget {
public:
    explicit ToolDockSurface(QWidget* parent = nullptr) : QWidget(parent) {
        setAttribute(Qt::WA_TranslucentBackground, true);
    }

protected:
    void paintEvent(QPaintEvent*) override {
        QPainter painter(this);
        painter.setRenderHint(QPainter::Antialiasing);
        const QRectF box = QRectF(rect()).adjusted(0.5, 0.5, -0.5, -0.5);
        QPainterPath path;
        path.addRoundedRect(box, 14, 14);
        painter.setPen(QPen(QColor(0, 0, 0, 34), 1));
        painter.setBrush(QColor(255, 255, 255, 252));
        painter.drawPath(path);
        QPainterPath inner;
        inner.addRoundedRect(box.adjusted(1, 1, -1, -1), 13, 13);
        painter.setPen(QPen(QColor(255, 255, 255, 210), 1));
        painter.setBrush(Qt::NoBrush);
        painter.drawPath(inner);
    }
};

class ToolDivider : public QWidget {
public:
    explicit ToolDivider(QWidget* parent = nullptr) : QWidget(parent) {
        setFixedWidth(1);
        setFixedHeight(20);
        setAttribute(Qt::WA_TranslucentBackground, true);
    }

protected:
    void paintEvent(QPaintEvent*) override {
        QPainter painter(this);
        painter.setPen(QPen(QColor(214, 221, 233), 1));
        painter.drawLine(0, height() / 2, 0, height() / 2 + 1);
    }
};

}  // namespace

CanvasToolBar::CanvasToolBar(ToolController* controller, QWidget* parent)
    : QWidget(parent), m_controller(controller) {
    setObjectName("canvasToolSuite");
    setAttribute(Qt::WA_TranslucentBackground, true);
    setAttribute(Qt::WA_NoSystemBackground, true);
    buildMainBar();
    buildStylePanel();
    if (m_stylePanel) m_stylePanel->hide();
    reposition();
}

void CanvasToolBar::buildMainBar() {
    m_mainBar = new ToolDockSurface(this);
    m_mainBar->setObjectName("canvasToolDock");

    QHBoxLayout* layout = new QHBoxLayout(m_mainBar);
    layout->setContentsMargins(7, 6, 7, 6);
    layout->setSpacing(3);

    const ToolController::Tool tools[] = {
        ToolController::Select, ToolController::AnnotationSelect, ToolController::Pen,
        ToolController::Eraser, ToolController::Line, ToolController::Rect,
        ToolController::Circle, ToolController::Arrow, ToolController::Triangle,
        ToolController::Mosaic
    };
    static const QString tips[] = {
        "指针 / 平移 (V)", "选择批注 (A)", "画笔 (B)", "橡皮 (E)",
        "直线 (L, Shift 锁定 45°)", "矩形 (R, Shift 正方)", "圆形 (O, Shift 正圆)",
        "箭头 (D)", "三角形 (T, Shift 等腰)", "马赛克 (M)"
    };

    for (int i = 0; i < 10; ++i) {
        ToolIconButton* button = new ToolIconButton(
            static_cast<ToolIconButton::Kind>(ToolIconButton::Select) + i,
            tips[i], m_mainBar);
        const ToolController::Tool tool = tools[i];
        button->setObjectName(QString("canvasTool_%1").arg(static_cast<int>(tool)));
        connect(button, &QAbstractButton::clicked, this, [this, tool]() {
            m_controller->setTool(tool);
        });
        m_toolButtons.push_back(button);
        layout->addWidget(button);
    }

    layout->addWidget(new ToolDivider(m_mainBar));

    m_btnStyle = new ToolIconButton(ToolIconButton::Style, "画笔样式 (颜色 / 粗细 / 不透明度)", m_mainBar);
    m_btnStyle->setObjectName("canvasStyleToggle");
    connect(m_btnStyle, &QAbstractButton::clicked, this, [this]() { toggleStylePanel(); });
    layout->addWidget(m_btnStyle);

    layout->addWidget(new ToolDivider(m_mainBar));

    m_btnMore = new ToolIconButton(ToolIconButton::More, "更多工具 (文本 / 笔记 / 公式 / 表格)", m_mainBar);
    m_btnMore->setObjectName("canvasMoreToggle");
    connect(m_btnMore, &QAbstractButton::clicked, this, [this]() { toggleStylePanel(); });
    layout->addWidget(m_btnMore);

    connect(m_controller, &ToolController::toolChanged, this, [this](ToolController::Tool tool) {
        for (ToolIconButton* button : m_toolButtons) {
            if (!button) continue;
            const bool active = static_cast<int>(tool) == static_cast<int>(button->kind());
            button->setActive(active);
        }
    });
}

ToolIconButton* CanvasToolBar::buttonFor(ToolController::Tool tool) const {
    for (ToolIconButton* button : m_toolButtons) {
        if (button && static_cast<int>(button->kind()) == static_cast<int>(tool)) return button;
    }
    return nullptr;
}

void CanvasToolBar::buildStylePanel() {
    m_stylePanel = new ToolDockSurface(this);
    m_stylePanel->setObjectName("canvasStylePanel");

    QVBoxLayout* layout = new QVBoxLayout(m_stylePanel);
    layout->setContentsMargins(14, 12, 14, 12);
    layout->setSpacing(9);

    QLabel* title = new QLabel("样式", m_stylePanel);
    title->setObjectName("canvasStyleTitle");
    layout->addWidget(title);

    QHBoxLayout* colorRow = new QHBoxLayout();
    colorRow->setSpacing(8);
    QLabel* colorLabel = new QLabel("颜色", m_stylePanel);
    colorLabel->setObjectName("canvasStyleLabel");
    colorRow->addWidget(colorLabel);
    colorRow->addStretch(1);
    MyColorSwatch* swatch = new MyColorSwatch(m_stylePanel);
    swatch->setObjectName("canvasStyleColor");
    swatch->setColor(m_controller->penColor());
    connect(swatch, &MyColorSwatch::colorPicked, this, [this](const QColor& c) {
        m_controller->setPenColor(c);
    });
    colorRow->addWidget(swatch);
    layout->addLayout(colorRow);

    auto addSliderRow = [this, layout](const QString& label, int min, int max, int value,
                                       const QString& objectName, const std::function<void(int)>& sink) {
        QHBoxLayout* row = new QHBoxLayout();
        row->setSpacing(8);
        QLabel* text = new QLabel(label, m_stylePanel);
        text->setObjectName("canvasStyleLabel");
        text->setFixedWidth(52);
        row->addWidget(text);
        MySlider* slider = new MySlider(m_stylePanel);
        slider->setObjectName(objectName);
        slider->setRange(min, max);
        slider->setValue(value);
        slider->setFixedWidth(150);
        connect(slider, &MySlider::valueChanged, this, [sink](int v) { sink(v); });
        row->addWidget(slider, 1);
        layout->addLayout(row);
        return slider;
    };

    addSliderRow("粗细", 1, 16, static_cast<int>(m_controller->penWidth()),
                 "canvasStyleWidth", [this](int v) { m_controller->setPenWidth(v); });
    addSliderRow("不透明", 10, 100, static_cast<int>(m_controller->opacity() * 100),
                 "canvasStyleOpacity", [this](int v) { m_controller->setOpacity(v / 100.0); });

    layout->addWidget(new ToolDivider(m_stylePanel));

    QHBoxLayout* textRow = new QHBoxLayout();
    textRow->setSpacing(4);
    MyButton* bold = new MyButton("B", m_stylePanel);
    bold->setObjectName("canvasTextBold");
    bold->setVariant(MyButton::Ghost);
    bold->setCompact(true);
    connect(bold, &MyButton::clicked, this, [this]() { m_controller->toggleSelectedTextBold(); });
    textRow->addWidget(bold);

    MyButton* italic = new MyButton("I", m_stylePanel);
    italic->setObjectName("canvasTextItalic");
    italic->setVariant(MyButton::Ghost);
    italic->setCompact(true);
    connect(italic, &MyButton::clicked, this, [this]() { m_controller->toggleSelectedTextItalic(); });
    textRow->addWidget(italic);

    MyButton* underline = new MyButton("U", m_stylePanel);
    underline->setObjectName("canvasTextUnderline");
    underline->setVariant(MyButton::Ghost);
    underline->setCompact(true);
    connect(underline, &MyButton::clicked, this, [this]() { m_controller->toggleSelectedTextItalic(); });
    textRow->addWidget(underline);

    MySlider* textSize = new MySlider(m_stylePanel);
    textSize->setObjectName("canvasTextSize");
    textSize->setRange(8, 48);
    textSize->setValue(12);
    textSize->setFixedWidth(96);
    connect(textSize, &MySlider::valueChanged, this, [this](int v) {
        m_controller->setSelectedTextSize(v);
    });
    textRow->addWidget(textSize, 1);
    layout->addLayout(textRow);

    QHBoxLayout* tableRow = new QHBoxLayout();
    tableRow->setSpacing(8);
    QLabel* tableLabel = new QLabel("表格行列", m_stylePanel);
    tableLabel->setObjectName("canvasStyleLabel");
    tableLabel->setFixedWidth(52);
    tableRow->addWidget(tableLabel);

    MySlider* tableRows = new MySlider(m_stylePanel);
    tableRows->setObjectName("canvasTableRows");
    tableRows->setRange(1, 12);
    tableRows->setValue(3);
    tableRows->setFixedWidth(70);
    connect(tableRows, &MySlider::valueChanged, this, [this](int v) {
        m_tableRows = v;
        m_controller->setTableSize(v, m_tableCols);
    });
    tableRow->addWidget(tableRows);

    MySlider* tableCols = new MySlider(m_stylePanel);
    tableCols->setObjectName("canvasTableCols");
    tableCols->setRange(1, 12);
    tableCols->setValue(3);
    tableCols->setFixedWidth(70);
    connect(tableCols, &MySlider::valueChanged, this, [this](int v) {
        m_tableCols = v;
        m_controller->setTableSize(m_tableRows, v);
    });
    tableRow->addWidget(tableCols, 1);
    layout->addLayout(tableRow);

    layout->addWidget(new ToolDivider(m_stylePanel));

    QHBoxLayout* actionRow = new QHBoxLayout();
    actionRow->setSpacing(4);

    MyButton* undo = new MyButton("撤销", m_stylePanel);
    undo->setObjectName("canvasUndoButton");
    undo->setVariant(MyButton::Ghost);
    undo->setCompact(true);
    connect(undo, &MyButton::clicked, this, [this]() { m_controller->undo(); });
    actionRow->addWidget(undo);

    MyButton* redo = new MyButton("重做", m_stylePanel);
    redo->setObjectName("canvasRedoButton");
    redo->setVariant(MyButton::Ghost);
    redo->setCompact(true);
    connect(redo, &MyButton::clicked, this, [this]() { m_controller->redo(); });
    actionRow->addWidget(redo);

    MyButton* del = new MyButton("删除", m_stylePanel);
    del->setObjectName("canvasDeleteButton");
    del->setVariant(MyButton::Ghost);
    del->setCompact(true);
    connect(del, &MyButton::clicked, this, [this]() { m_controller->deleteSelected(); });
    actionRow->addWidget(del);
    layout->addLayout(actionRow);

    QHBoxLayout* actionRow2 = new QHBoxLayout();
    actionRow2->setSpacing(4);

