    connect(m_controller, &ToolController::historyChanged, this, [this](bool canUndo, bool canRedo) {
        if (undo) undo->setEnabled(canUndo);
        if (redo) redo->setEnabled(canRedo);
    });
    connect(m_controller, &ToolController::selectionChanged, this, [this](int count) {
        const bool has = count > 0;
        if (del) del->setEnabled(has);
        const bool hasText = m_controller->hasSelectedText();
        if (bold) bold->setEnabled(hasText);
        if (italic) italic->setEnabled(hasText);
        if (underline) underline->setEnabled(hasText);
    });
}

void CanvasToolBar::toggleStylePanel() {
    m_styleOpen = !m_styleOpen;
    if (!m_stylePanel) return;
    if (m_styleOpen) {
        m_stylePanel->show();
        m_stylePanel->raise();
    } else {
        m_stylePanel->hide();
    }
    reposition();
}

void CanvasToolBar::setHostWidget(QWidget* host) {
    m_host = host;
    reposition();
}

void CanvasToolBar::reposition() {
    if (!m_host) return;
    const QRect area = m_host->rect();
    if (!m_mainBar) return;

    m_mainBar->adjustSize();
    const int barW = m_mainBar->sizeHint().width();
    const int barH = m_mainBar->sizeHint().height();
    const int x = qMax(8, (area.width() - barW) / 2);
    const int y = 16;
    m_mainBar->setGeometry(x, y, barW, barH);

    if (m_stylePanel && m_styleOpen) {
        m_stylePanel->adjustSize();
        const int panelW = m_stylePanel->sizeHint().width();
        const int panelH = m_stylePanel->sizeHint().height();
        int px = qBound(8, x + barW - panelW, area.width() - panelW - 8);
        int py = y + barH + 10;
        if (py + panelH > area.height() - 8) py = qMax(8, y - panelH - 10);
        m_stylePanel->setGeometry(px, py, panelW, panelH);
    }
}

void drawMore(QPainter& painter, const QRectF& box, const QColor& color) {
    const QPointF c = box.center();
    painter.setPen(Qt::NoPen);
    painter.setBrush(color);
    const double d = qMin(box.width(), box.height()) * 0.11;
    for (int i = -1; i <= 1; ++i) {
        painter.drawEllipse(QPointF(c.x() + i * d * 2.0, c.y()), d, d);
    }
}

void drawMore(QPainter& painter, const QRectF& box, const QColor& color) {
    const QPointF c = box.center();
    painter.setPen(Qt::NoPen);
    painter.setBrush(color);
    const double d = qMin(box.width(), box.height()) * 0.11;
    for (int i = -1; i <= 1; ++i) {
        painter.drawEllipse(QPointF(c.x() + i * d * 2.0, c.y()), d, d);
    }
}

void drawUndo(QPainter& painter, const QRectF& box, const QColor& color) {
    const QPointF c = box.center();
    const double s = qMin(box.width(), box.height()) * 0.5;
    QPainterPath path;
    path.arcMoveTo(QRectF(c.x() - s * 0.55, c.y() - s * 0.45, s * 1.1, s * 0.9), 40, 270);
    iconPen(painter, color, 1.5);
    painter.drawPath(path);
    QPainterPath head;
    head.moveTo(c.x() - s * 0.58, c.y() - s * 0.12);
    head.lineTo(c.x() - s * 0.58, c.y() - s * 0.52);
    head.lineTo(c.x() - s * 0.22, c.y() - s * 0.26);
    head.closeSubpath();
    painter.setBrush(color);
    painter.drawPath(head);
}

void drawRedo(QPainter& painter, const QRectF& box, const QColor& color) {
    painter.save();
    QTransform t;
    t.translate(box.center().x() * 2, 0);
    t.scale(-1, 1);
    painter.setTransform(t, true);
    drawUndo(painter, QRectF(box.center().x() - box.width() / 2, box.top(), box.width(), box.height()), color);
    painter.restore();
}

case Style: drawStyle(painter, box, color); break;
case More: drawMore(painter, box, color); break;
case Undo: drawUndo(painter, box, color); break;
case Redo: drawRedo(painter, box, color); break;

