class ToolDockSurface : public QWidget {
public:
    explicit ToolDockSurface(QWidget* parent = nullptr) : QWidget(parent) {
        setAttribute(Qt::WA_TranslucentBackground, true);
    }

protected:
    void paintEvent(QPaintEvent*) override {
        QPainter painter(this);
        painter.setRenderHint(QPainter::Antialiasing);
        const QRectF box = QRectF(rect()).adjusted(0.5, 0.5, -0.5, -0.5);
        QPainterPath path;
        path.addRoundedRect(box, 14, 14);
        painter.setPen(QPen(QColor(0, 0, 0, 30), 1));
        painter.setBrush(QColor(255, 255, 255, 253));
        painter.drawPath(path);
        QPainterPath inner;
        inner.addRoundedRect(box.adjusted(1, 1, -1, -1), 13, 13);
        painter.setPen(QPen(QColor(255, 255, 255, 200), 1));
        painter.setBrush(Qt::NoBrush);
        painter.drawPath(inner);
    }
};

class ToolDivider : public QWidget {
public:
    explicit ToolDivider(QWidget* parent = nullptr) : QWidget(parent) {
        setFixedWidth(1);
        setFixedHeight(20);
        setAttribute(Qt::WA_TranslucentBackground, true);
    }

protected:
    void paintEvent(QPaintEvent*) override {
        QPainter painter(this);
        painter.setPen(QPen(QColor(214, 221, 233), 1));
        painter.drawLine(0, 2, 0, height() - 2);
    }
};

