void CanvasToolBar::buildMainBar() {
    m_mainBar = new ToolDockSurface(this);
    m_mainBar->setObjectName("canvasToolDock");

    QHBoxLayout* layout = new QHBoxLayout(m_mainBar);
    layout->setContentsMargins(8, 7, 8, 7);
    layout->setSpacing(2);

    const ToolController::Tool tools[] = {
        ToolController::Select, ToolController::AnnotationSelect, ToolController::Pen,
        ToolController::Eraser, ToolController::Line, ToolController::Rect,
        ToolController::Circle, ToolController::Arrow, ToolController::Triangle,
        ToolController::Mosaic
    };
    static const QString tips[] = {
        "指针 / 平移 (V)", "选择批注 (A)", "画笔 (B)", "橡皮 (E)",
        "直线 (L, Shift 锁定 45°)", "矩形 (R, Shift 正方)", "圆形 (O, Shift 正圆)",
        "箭头 (D)", "三角形 (T, Shift 等腰)", "马赛克 (M)"
    };

    for (int i = 0; i < 10; ++i) {
        ToolIconButton* button = new ToolIconButton(
            static_cast<ToolIconButton::Kind>(ToolIconButton::Select + i), tips[i], m_mainBar);
        const ToolController::Tool tool = tools[i];
        button->setObjectName(QString("canvasTool_%1").arg(static_cast<int>(tool)));
        connect(button, &QAbstractButton::clicked, this, [this, tool]() {
            m_controller->setTool(tool);
        });
        m_toolButtons.push_back(button);
        layout->addWidget(button);
    }

    layout->addWidget(new ToolDivider(m_mainBar));

    m_btnStyle = new ToolIconButton(ToolIconButton::Style, "画笔样式 (颜色 / 粗细 / 不透明度)", m_mainBar);
    m_btnStyle->setObjectName("canvasStyleToggle");
    connect(m_btnStyle, &QAbstractButton::clicked, this, [this]() { toggleStylePanel(); });
    layout->addWidget(m_btnStyle);

    m_btnMore = new ToolIconButton(ToolIconButton::More, "更多工具 (文本 / 笔记 / 公式 / 表格)", m_mainBar);
    m_btnMore->setObjectName("canvasMoreToggle");
    connect(m_btnMore, &QAbstractButton::clicked, this, [this]() { toggleMorePanel(); });
    layout->addWidget(m_btnMore);

    connect(m_controller, &ToolController::toolChanged, this, [this](ToolController::Tool tool) {
        for (ToolIconButton* button : m_toolButtons) {
            if (!button) continue;
            const bool active = static_cast<int>(tool) == static_cast<int>(button->kind());
            button->setActive(active);
        }
    });
}

