        ToolIconButton* button = new ToolIconButton(
            static_cast<ToolIconButton::Kind>(ToolIconButton::Text + i), tips[i], m_morePanel);
        const ToolController::Tool tool = extraTools[i];
        button->setObjectName(QString("canvasTool_%1").arg(static_cast<int>(tool)));
