namespace {

constexpr qreal kMinSampleDistance = 0.9;

QPointF midPoint(const QPointF& a, const QPointF& b) {
    return QPointF((a.x() + b.x()) * 0.5, (a.y() + b.y()) * 0.5);
}

}  // namespace

StrokeItem::StrokeItem(QGraphicsItem* parent) : AnnotationItem(parent) {
    setZValue(10);
    applyStyle();
}

void StrokeItem::setMode(Mode m) {
    if (m_mode == m) return;
    m_mode = m;
    applyStyle();
    notifyContentChanged();
}

