bool StrokeItem::hitTest(const QPointF& scenePos, qreal radius) const {
    const QPointF local = mapFromScene(scenePos);
    if (shape().contains(local)) return true;
    qreal best = std::numeric_limits<qreal>::max();
    for (const QPointF& p : m_points) {
        const qreal dx = p.x() - local.x();
        const qreal dy = p.y() - local.y();
        best = qMin(best, std::hypot(dx, dy));
    }
    return best <= radius + m_penWidth * 0.5;
}

void ToolController::eraseAt(const QPointF& pos) {
    const qreal radius = m_eraserRadius;
    QVector<AnnotationItem*> hits;
    for (AnnotationItem* item : m_scene->annotationItems()) {
        if (item->isLocked()) continue;
        const QPointF local = item->mapFromScene(pos);
        if (item->shape().contains(local)) {
            hits.push_back(item);
            continue;
        }
        const QRectF b = item->boundingRect();
        if (b.adjusted(-radius, -radius, radius, radius).contains(local)) {
            hits.push_back(item);
        }
    }

