        QPointF tangent = a - b;
        const qreal len = std::hypot(tangent.x(), tangent.y());
        if (len < 0.0001) continue;
        tangent /= len;
        const QPointF normal(-tangent.y(), tangent.x());
        ribbon.lineTo(a - normal * half);
    }
    ribbon.closeSubpath();

