void ToolController::openEditorFor(AnnotationItem* item) {
    if (!item || item->isLocked()) return;
    if (auto* box = dynamic_cast<TextBoxItem*>(item)) {
        AnnotationEditor editor(AnnotationEditor::TextMode, box->plainText(), nullptr);
        if (editor.exec() == QDialog::Accepted) box->setPlainText(editor.content());
        return;
    }
    if (auto* md = dynamic_cast<MarkdownItem*>(item)) {
        AnnotationEditor editor(AnnotationEditor::MarkdownMode, md->markdown(), nullptr);
        if (editor.exec() == QDialog::Accepted) md->setMarkdown(editor.content());
        return;
    }
    if (auto* latex = dynamic_cast<LatexItem*>(item)) {
        AnnotationEditor editor(AnnotationEditor::LatexMode, latex->tex(), nullptr);
        if (editor.exec() == QDialog::Accepted) latex->setTex(editor.content());
        return;
    }
}

