    check("clipboard: select all picks items", controller.selectedItems().size() == beforeCopy);
    check("clipboard: copy succeeds", controller.copySelection());
    check("clipboard: clipboard is populated", controller.hasClipboard());
    controller.clearSelectionForTest();
    check("clipboard: cut succeeds", controller.cutSelection());
    check("clipboard: cut removes items", overlay.items().size() < beforeCopy);
    const int afterCut = overlay.items().size();
    check("clipboard: paste succeeds", controller.pasteAt(QPointF(0, 400)));
    check("clipboard: paste restores item count", overlay.items().size() == afterCut + beforeCopy);
    controller.undo();
    check("clipboard: undo after paste removes pasted copy", overlay.items().size() == afterCut);
    controller.redo();
    check("clipboard: redo restores pasted copy", overlay.items().size() == afterCut + beforeCopy);

    printf("\n%s  fail=%d\n", g_fail == 0 ? "ALL PASS" : "HAS FAILURE", g_fail);
    return g_fail == 0 ? 0 : 1;
