void CanvasToolBar::showToolPage(ToolController::Tool tool) {
    if (!m_toolPages) return;
    const int count = m_toolPages->count();
    for (int i = 0; i < count; ++i) {
        QWidget* page = m_toolPages->widget(i);
        if (!page) continue;
        if (page->objectName() == QString("canvasToolPage_%1").arg(static_cast<int>(tool))) {
            m_toolPages->setCurrentIndex(i);
            return;
        }
    }
}

if (m_toolPanel) {
    if (m_toolPanelOpen) {
        rebuildToolPanelContent();
        m_toolPanel->layout()->activate();
        m_toolPanel->adjustSize();
        m_toolPanel->show();
        m_toolPanel->raise();
        printf("[toolpanel] children=%d size=%dx%d geom=%d,%d %dx%d\n",
               m_toolPanel->children().size(), m_toolPanel->width(), m_toolPanel->height(),
               m_toolPanel->x(), m_toolPanel->y(),
               m_toolPanel->geometry().width(), m_toolPanel->geometry().height());
        for (QObject* obj : m_toolPanel->children()) {
            QWidget* c = qobject_cast<QWidget*>(obj);
            if (!c) continue;
            printf("   child %s geom=%d,%d %dx%d vis=%d\n",
                   c->objectName().toLatin1().constData(),
                   c->x(), c->y(), c->width(), c->height(), c->isVisible());
        }
    } else {
        m_toolPanel->hide();
    }
}

if (m_toolPanel) {
    if (m_toolPanelOpen) {
        showToolPage(m_controller->currentTool());
        m_toolPanel->layout()->activate();
        m_toolPanel->adjustSize();
        m_toolPanel->show();
        m_toolPanel->raise();
    } else {
        m_toolPanel->hide();
    }
}

    for (ToolController::Tool tool : tools) {
        m_toolPages->addWidget(createToolPage(static_cast<int>(tool)));
