void ToolController::openEditorFor(AnnotationItem* item) {
    if (!item || item->isLocked()) return;
    if (auto* box = dynamic_cast<TextBoxItem*>(item)) {
        box->beginInlineEdit();
        if (m_view) m_view->refreshOverlay();
        emit statusMessage("文本框已进入编辑状态，直接在画布上输入。");
        return;
