        emit statusMessage("笔记已进入编辑状态，直接在画布上输入 Markdown 源码。");
        return;
    }
    if (auto* latex = dynamic_cast<LatexItem*>(item)) {
        openLatexEditor(latex);
        return;
    }
}

void ToolController::openLatexEditor(LatexItem* item) {
