namespace {

const QColor& gradientAt(int index) {
    static const QColor palette[] = {
        QColor(229, 72, 77), QColor(240, 140, 40), QColor(240, 196, 40),
        QColor(96, 196, 84), QColor(32, 178, 170), QColor(59, 125, 221),
        QColor(123, 97, 255), QColor(214, 90, 168), QColor(90, 100, 120)
    };
    static const int count = 9;
    return palette[index % count];
}

}  // namespace

MyColorPicker::MyColorPicker(QWidget* parent) : QWidget(parent) {
    setFixedWidth(244);
    setAttribute(Qt::WA_TranslucentBackground, true);

    QVBoxLayout* root = new QVBoxLayout(this);
    root->setContentsMargins(0, 0, 0, 0);
    root->setSpacing(8);

    QWidget* preview = new QWidget(this);
    preview->setObjectName("colorPreview");
    preview->setFixedHeight(34);
    preview->setStyleSheet("QWidget#colorPreview { border:1px solid #dbe1ea; border-radius:8px; background:#1f2733; }");
    root->addWidget(preview);

    QLabel* hint = new QLabel("拖动色相条无极取色", this);
    hint->setFont(UiTheme::uiFont(8));
    hint->setStyleSheet("color:#8b95a6; background:transparent;");
    root->addWidget(hint);

    auto addSlider = [this, root](const QString& label, int value) {
        QWidget* row = new QWidget(this);
        QHBoxLayout* rowLayout = new QHBoxLayout(row);
        rowLayout->setContentsMargins(0, 0, 0, 0);
        rowLayout->setSpacing(7);
        QLabel* text = new QLabel(label, row);
        text->setFixedWidth(26);
        text->setFont(UiTheme::uiFont(8));
        text->setStyleSheet("color:#7a8494; background:transparent;");
        rowLayout->addWidget(text);
        MySlider* slider = new MySlider(row);
        slider->setRange(0, 255);
        slider->setValue(value);
        slider->setFixedHeight(18);
        rowLayout->addWidget(slider, 1);
        root->addWidget(row);
        return slider;
    };

    m_hue = addSlider("色相", m_color.hue());
    m_sat = addSlider("饱和", m_color.saturation());
    m_val = addSlider("明度", m_color.value());

    QWidget* hexRow = new QWidget(this);
    QHBoxLayout* hexLayout = new QHBoxLayout(hexRow);
    hexLayout->setContentsMargins(0, 0, 0, 0);
    hexLayout->setSpacing(7);
    QLabel* hexLabel = new QLabel("色值", hexRow);
    hexLabel->setFixedWidth(26);
    hexLabel->setFont(UiTheme::uiFont(8));
    hexLabel->setStyleSheet("color:#7a8494; background:transparent;");
    hexLayout->addWidget(hexLabel);
    m_hex = new MyTextInput(hexRow);
    m_hex->setPlaceholderText("#1F2733");
    m_hex->setMaxLength(7);
    hexLayout->addWidget(m_hex, 1);
    root->addWidget(hexRow);

    QWidget* rgbRow = new QWidget(this);
    QHBoxLayout* rgbLayout = new QHBoxLayout(rgbRow);
    rgbLayout->setContentsMargins(0, 0, 0, 0);
    rgbLayout->setSpacing(5);
    auto addNumber = [this, rgbLayout, rgbRow](const QString& label, int value) {
        QLabel* text = new QLabel(label, rgbRow);
        text->setFont(UiTheme::uiFont(8));
        text->setStyleSheet("color:#7a8494; background:transparent;");
        rgbLayout->addWidget(text);
        MyTextInput* input = new MyTextInput(rgbRow);
        input->setText(QString::number(value));
        input->setMaxLength(3);
        input->setFixedWidth(48);
        rgbLayout->addWidget(input);
        return input;
    };
    m_red = addNumber("R", m_color.red());
    m_green = addNumber("G", m_color.green());
    m_blue = addNumber("B", m_color.blue());
    root->addWidget(rgbRow);

    QLabel* presetLabel = new QLabel("渐变预设", this);
    presetLabel->setFont(UiTheme::uiFont(8));
    presetLabel->setStyleSheet("color:#7a8494; background:transparent;");
    root->addWidget(presetLabel);

    QWidget* presetRow = new QWidget(this);
    QHBoxLayout* presetLayout = new QHBoxLayout(presetRow);
    presetLayout->setContentsMargins(0, 0, 0, 0);
    presetLayout->setSpacing(4);
    for (int i = 0; i < 9; ++i) {
        const QColor c = gradientAt(i);
        QWidget* chip = new QWidget(presetRow);
        chip->setFixedSize(20, 20);
        chip->setCursor(Qt::PointingHandCursor);
        chip->setProperty("chipColor", c);
        chip->setStyleSheet("QWidget { border-radius:5px; background:" + c.name() + "; border:1px solid rgba(0,0,0,30); }");
        connect(chip, &QWidget::mousePressEvent, this, [this, c]() {
            setColor(c);
            emitColor();
        });
        presetLayout->addWidget(chip);
    }
    root->addWidget(presetRow);

    connect(m_hue, &MySlider::valueChanged, this, [this](int v) {
        QColor c = m_color;
        c.setHsv(qBound(0, v, 359), m_color.saturation(), m_color.value());
        m_color = c;
        emitColor();
    });
    connect(m_sat, &MySlider::valueChanged, this, [this](int v) {
        QColor c = m_color;
        c.setHsv(m_color.hue(), qBound(0, v, 255), m_color.value());
        m_color = c;
        emitColor();
    });
    connect(m_val, &MySlider::valueChanged, this, [this](int v) {
        QColor c = m_color;
        c.setHsv(m_color.hue(), m_color.saturation(), qBound(0, v, 255));
        m_color = c;
        emitColor();
    });
    connect(m_hex, &MyTextInput::editingFinished, this, [this]() { applyHex(m_hex->text()); });
    connect(m_red, &MyTextInput::editingFinished, this, [this]() {
        applyRgb(m_red->text().toInt(), m_green->text().toInt(), m_blue->text().toInt());
    });
    connect(m_green, &MyTextInput::editingFinished, this, [this]() {
        applyRgb(m_red->text().toInt(), m_green->text().toInt(), m_blue->text().toInt());
    });
    connect(m_blue, &MyTextInput::editingFinished, this, [this]() {
        applyRgb(m_red->text().toInt(), m_green->text().toInt(), m_blue->text().toInt());
    });

    syncInputs();
}

void MyColorPicker::setColor(const QColor& c) {
    if (m_color == c) return;
    m_color = c;
    syncInputs();
    update();
}

void MyColorPicker::syncInputs() {
    const bool hue = m_hue && m_hue->value() != m_color.hue();
    const bool sat = m_sat && m_sat->value() != m_color.saturation();
    const bool val = m_val && m_val->value() != m_color.value();
    if (hue) m_hue->setValue(m_color.hue());
    if (sat) m_sat->setValue(m_color.saturation());
    if (val) m_val->setValue(m_color.value());
    if (m_hex) m_hex->setText(m_color.name().toUpper());
    if (m_red) m_red->setText(QString::number(m_color.red()));
    if (m_green) m_green->setText(QString::number(m_color.green()));
    if (m_blue) m_blue->setText(QString::number(m_color.blue()));
}

void MyColorPicker::applyHex(const QString& text) {
    QString t = text.trimmed();
    if (!t.startsWith('#')) t.prepend('#');
    QColor c(t);
    if (!c.isValid()) {
        syncInputs();
        return;
    }
    m_color = c;
    syncInputs();
    emitColor();
}

void MyColorPicker::applyRgb(int r, int g, int b) {
    QColor c(qBound(0, r, 255), qBound(0, g, 255), qBound(0, b, 255));
    m_color = c;
    syncInputs();
    emitColor();
}

void MyColorPicker::emitColor() {
    update();
    emit colorPicked(m_color);
}

int MyColorPicker::hueAt(int x) const {
    const int w = qMax(1, width());
    return qBound(0, static_cast<int>(x * 360.0 / w), 359);
}

void MyColorPicker::mousePressEvent(QMouseEvent* event) {
    const int y = event->position().y();
    if (y < 34) {
        m_dragging = true;
        return;
    }
    QWidget::mousePressEvent(event);
}

void MyColorPicker::mouseMoveEvent(QMouseEvent* event) {
    if (m_dragging) {
        const int h = hueAt(static_cast<int>(event->position().x()));
        QColor c = m_color;
        c.setHsv(h, m_color.saturation(), m_color.value());
        m_color = c;
        syncInputs();
        emitColor();
        return;
    }
    QWidget::mouseMoveEvent(event);
}

void MyColorPicker::mouseReleaseEvent(QMouseEvent* event) {
    if (m_dragging) {
        m_dragging = false;
        return;
    }
    QWidget::mouseReleaseEvent(event);
}

void MyColorPicker::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);

    QRectF bar(0, 0, width(), 34);
    QLinearGradient gradient(0, 0, width(), 0);
    for (int i = 0; i <= 12; ++i) {
        const QColor c = QColor::fromHsv(i * 30, 220, 235);
        gradient.setColorAt(i / 12.0, c);
    }
    painter.setPen(Qt::NoPen);
    painter.setBrush(gradient);
    painter.drawRoundedRect(bar, 8, 8);

    painter.setBrush(Qt::NoBrush);
    painter.setPen(QPen(QColor(0, 0, 0, 40), 1));
    painter.drawRoundedRect(bar.adjusted(0.5, 0.5, -0.5, -0.5), 8, 8);

    const qreal markerX = bar.left() + bar.width() * (m_color.hue() / 359.0);
    painter.setPen(QPen(QColor(255, 255, 255, 230), 2));
    painter.setBrush(QColor(31, 39, 51));
    painter.drawEllipse(QPointF(markerX, bar.center().y()), 6.5, 6.5);
    painter.setPen(QPen(QColor(255, 255, 255, 235), 1.2));
    painter.setBrush(Qt::NoBrush);
    painter.drawEllipse(QPointF(markerX, bar.center().y()), 8.5, 8.5);
}

#include "StrokeItem.h"
#include <QPainter>
#include <QJsonArray>
#include <QJsonObject>
#include <QtMath>
#include <limits>
#include <cmath>

namespace {

constexpr qreal kMinSampleDistance = 0.4;
constexpr qreal kResampleSpacing = 3.0;
constexpr qreal kCentripetalAlpha = 0.5;

}  // namespace

StrokeItem::StrokeItem(QGraphicsItem* parent) : AnnotationItem(parent) {
    setZValue(10);
    applyStyle();
}

void StrokeItem::setMode(Mode m) {
    if (m_mode == m) return;
    m_mode = m;
    applyStyle();
    notifyContentChanged();
}

void StrokeItem::applyStyle() {
    setAcceptedMouseButtons(Qt::NoButton);
}

void StrokeItem::addPoint(const QPointF& p) {
    if (!m_points.isEmpty()) {
        const QPointF last = m_points.last();
        const qreal dx = p.x() - last.x();
        const qreal dy = p.y() - last.y();
        if (dx * dx + dy * dy < kMinSampleDistance * kMinSampleDistance) return;
    }
    m_points.push_back(p);
    rebuild();
    notifyContentChanged();
}

void StrokeItem::setPoints(const QVector<QPointF>& pts) {
    m_points = pts;
    rebuild();
    notifyContentChanged();
}

void StrokeItem::rebuild() {
    prepareGeometryChange();
    m_center = buildCenterPath();
    update();
}

QVector<QPointF> StrokeItem::resampledPoints() const {
    QVector<QPointF> out;
    if (m_points.isEmpty()) return out;
    out << m_points.first();
    for (int i = 1; i < m_points.size(); ++i) {
        const QPointF a = m_points.at(i - 1);
        const QPointF b = m_points.at(i);
        const qreal len = std::hypot(b.x() - a.x(), b.y() - a.y());
        if (len < 1e-6) continue;
        const int steps = qMax(1, static_cast<int>(std::ceil(len / kResampleSpacing)));
        for (int s = 1; s <= steps; ++s) {
            const qreal t = static_cast<qreal>(s) / steps;
            out << (a + (b - a) * t);
        }
    }
    return out;
}

QVector<QPointF> StrokeItem::smoothPoints() const {
    QVector<QPointF> out;
    const QVector<QPointF> pts = resampledPoints();
    if (pts.isEmpty()) return out;
    if (pts.size() == 1) {
        out << pts.first();
        return out;
    }
    if (pts.size() == 2) {
        out << pts.at(0) << pts.at(1);
        return out;
    }
    for (int i = 0; i < pts.size() - 1; ++i) {
        const QPointF p0 = pts.at(i > 0 ? i - 1 : 0);
        const QPointF p1 = pts.at(i);
        const QPointF p2 = pts.at(i + 1);
        const QPointF p3 = pts.at(i + 2 < pts.size() ? i + 2 : i + 1);

        const QPointF c1 = p1 + (p2 - p0) / 6.0;
        const QPointF c2 = p2 - (p3 - p1) / 6.0;

        for (int s = 0; s < 8; ++s) {
            const qreal t = static_cast<qreal>(s) / 8.0;
            const qreal mt = 1.0 - t;
            const qreal a = mt * mt * mt;
            const qreal b = 3.0 * mt * mt * t;
            const qreal c = 3.0 * mt * t * t;
            const qreal d = t * t * t;
            out << QPointF(a * p1.x() + b * c1.x() + c * c2.x() + d * p2.x(),
                           a * p1.y() + b * c1.y() + c * c2.y() + d * p2.y());
        }
    }
    out << pts.last();
    return out;
}

QPainterPath StrokeItem::buildCenterPath() const {
    QPainterPath path;
    const QVector<QPointF> pts = resampledPoints();
    if (pts.isEmpty()) return path;
    path.moveTo(pts.first());
    if (pts.size() == 1) {
        path.lineTo(pts.first() + QPointF(0.01, 0.0));
        return path;
    }
    if (pts.size() == 2) {
        path.lineTo(pts.at(1));
        return path;
    }

    const int n = pts.size();
    for (int i = 0; i < n - 1; ++i) {
        const QPointF p1 = pts.at(i);
        const QPointF p2 = pts.at(i + 1);
        const QPointF p0 = (i > 0) ? pts.at(i - 1) : (p1 * 2.0 - p2);
        const QPointF p3 = (i + 2 < n) ? pts.at(i + 2) : (p2 * 2.0 - p1);

        const qreal d1 = std::pow(std::hypot(p1.x() - p0.x(), p1.y() - p0.y()), kCentripetalAlpha);
        const qreal d2 = std::pow(std::hypot(p2.x() - p1.x(), p2.y() - p1.y()), kCentripetalAlpha);
        const qreal d3 = std::pow(std::hypot(p3.x() - p2.x(), p3.y() - p2.y()), kCentripetalAlpha);
        const qreal e1 = qMax(d1, 1e-4);
        const qreal e2 = qMax(d2, 1e-4);
        const qreal e3 = qMax(d3, 1e-4);

        const qreal k1 = 3.0 * e1 * (e1 + e2);
        const qreal k2 = 3.0 * e3 * (e3 + e2);

        const QPointF c1(
            (e1 * e1 * p2.x() - e2 * e2 * p0.x() + (2.0 * e1 * e1 + 3.0 * e1 * e2 + e2 * e2) * p1.x()) / k1,
            (e1 * e1 * p2.y() - e2 * e2 * p0.y() + (2.0 * e1 * e1 + 3.0 * e1 * e2 + e2 * e2) * p1.y()) / k1);
        const QPointF c2(
            (e3 * e3 * p1.x() - e2 * e2 * p3.x() + (2.0 * e3 * e3 + 3.0 * e3 * e2 + e2 * e2) * p2.x()) / k2,
            (e3 * e3 * p1.y() - e2 * e2 * p3.y() + (2.0 * e3 * e3 + 3.0 * e3 * e2 + e2 * e2) * p2.y()) / k2);

        path.cubicTo(c1, c2, p2);
    }
    return path;
}

QPainterPath StrokeItem::buildPath() const {
    return m_center;
}

QRectF StrokeItem::boundingRect() const {
    if (m_points.isEmpty()) return QRectF(-2, -2, 4, 4);
    const QRectF r = m_center.boundingRect();
    const qreal pad = m_penWidth + 3.0;
    return r.adjusted(-pad, -pad, pad, pad);
}

QPainterPath StrokeItem::shape() const {
    QPainterPath p = m_center;
    QPainterPathStroker stroker;
    stroker.setWidth(m_penWidth);
    stroker.setCapStyle(Qt::RoundCap);
    stroker.setJoinStyle(Qt::RoundJoin);
    return stroker.createStroke(p);
}

void StrokeItem::paint(QPainter* painter, const QStyleOptionGraphicsItem*, QWidget*) {
    if (m_points.isEmpty()) return;
    painter->save();
    painter->setRenderHint(QPainter::Antialiasing, true);
    painter->setBrush(Qt::NoBrush);

    const qreal width = qMax(0.6, m_penWidth);
    if (m_mode == Highlighter) {
        QColor ink = m_penColor;
        ink.setAlphaF(0.36 * qBound(0.0, m_fillOpacity, 1.0));
        QPen pen(ink, width * 2.4, Qt::SolidLine, Qt::FlatCap, Qt::RoundJoin);
        painter->setPen(pen);
        painter->drawPath(m_center);
    } else {
        QColor ink = m_penColor;
        ink.setAlphaF(qBound(0.0, m_fillOpacity, 1.0));
        QPen pen(ink, width, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
        painter->setPen(pen);
        painter->drawPath(m_center);
    }
    painter->restore();
    drawSelectionFrame(painter);
}

QVariant StrokeItem::itemChange(GraphicsItemChange change, const QVariant& value) {
    const QVariant result = AnnotationItem::itemChange(change, value);
    if (change == ItemPositionHasChanged || change == ItemTransformHasChanged) {
        notifyContentChanged();
    }
    return result;
}

QRectF StrokeItem::contentBounds() const {
    if (m_points.isEmpty()) return QRectF();
    return m_center.boundingRect();
}

bool StrokeItem::hitTest(const QPointF& scenePos, qreal radius) const {
    const QPointF local = mapFromScene(scenePos);
    if (shape().contains(local)) return true;
    qreal best = std::numeric_limits<qreal>::max();
    for (const QPointF& p : m_points) {
        const qreal dx = p.x() - local.x();
        const qreal dy = p.y() - local.y();
        best = qMin(best, std::hypot(dx, dy));
    }
    return best <= radius + m_penWidth * 0.5;
}

AnnotationItem* StrokeItem::cloneItem() const {
    auto* copy = new StrokeItem();
    copy->setMode(m_mode);
    copy->setPoints(m_points);
    copy->setPenColor(m_penColor);
    copy->setPenWidth(m_penWidth);
    copy->setFillOpacity(m_fillOpacity);
    copy->setLocked(m_locked);
    return copy;
}

QJsonObject StrokeItem::toJson() const {
    QJsonObject obj = AnnotationItem::toJson();
    obj["mode"] = static_cast<int>(m_mode);
    QJsonArray pts;
    for (const QPointF& p : m_points) {
        QJsonObject o;
        o["x"] = p.x();
        o["y"] = p.y();
        pts.push_back(o);
    }
    obj["points"] = pts;
    return obj;
}

void StrokeItem::fromJson(const QJsonObject& obj) {
    AnnotationItem::fromJson(obj);
    m_mode = static_cast<Mode>(obj.value("mode").toInt(static_cast<int>(m_mode)));
    QVector<QPointF> pts;
    const QJsonArray arr = obj.value("points").toArray();
    for (const QJsonValue& v : arr) {
        QJsonObject o = v.toObject();
        pts.push_back(QPointF(o.value("x").toDouble(), o.value("y").toDouble()));
    }
    setPoints(pts);
}

private:
    QPainterPath buildPath() const;
    QPainterPath buildCenterPath() const;
    QVector<QPointF> resampledPoints() const;
    QVector<QPointF> smoothPoints() const;
    void rebuild();

    QVector<QPointF> m_points;
    QVector<QPointF> m_smooth;
    QPainterPath m_path;
    QPainterPath m_center;
    Mode m_mode = Ink;
};

private:
    QPainterPath buildPath() const;
    QPainterPath buildCenterPath() const;
    QVector<QPointF> resampledPoints() const;
    void rebuild();

    QVector<QPointF> m_points;
    QPainterPath m_path;
    QPainterPath m_center;
    Mode m_mode = Ink;
};

#ifndef INLINETEXTEDIT_H
#define INLINETEXTEDIT_H
#include <QTextCursor>
#include <QKeyEvent>

namespace InlineTextEdit {

enum Action { NotHandled, Handled, Commit, Cancel };

Action handleKey(QTextCursor& cursor, QKeyEvent* event);

}  // namespace InlineTextEdit

#endif

#include "InlineTextEdit.h"

namespace InlineTextEdit {

Action handleKey(QTextCursor& cursor, QKeyEvent* event) {
    const int key = event->key();
    const bool ctrl = event->modifiers().testFlag(Qt::ControlModifier);

    if (ctrl) {
        switch (key) {
        case Qt::Key_A:
            cursor.select(QTextCursor::Document);
            return Handled;
        case Qt::Key_Z:
        case Qt::Key_Y:
            return NotHandled;
        default:
            return NotHandled;
        }
    }

    switch (key) {
    case Qt::Key_Escape:
        return Cancel;
    case Qt::Key_Return:
    case Qt::Key_Enter:
        return Commit;
    case Qt::Key_Backspace:
    case Qt::Key_Delete:
    case Qt::Key_Left:
    case Qt::Key_Right:
    case Qt::Key_Up:
    case Qt::Key_Down:
    case Qt::Key_Home:
    case Qt::Key_End:
    case Qt::Key_PageUp:
    case Qt::Key_PageDown:
    case Qt::Key_ShiftLeft:
    case Qt::Key_ShiftRight:
    case Qt::Key_ControlLeft:
    case Qt::Key_ControlRight:
    case Qt::Key_AltLeft:
    case Qt::Key_AltRight:
        return NotHandled;
    default:
        break;
    }

    if (event->text().isEmpty()) return NotHandled;
    if (event->text().at(0).isNull()) return NotHandled;
    if (event->text().at(0).isPrint()) return NotHandled;
    return Handled;
}

}  // namespace InlineTextEdit

#include "AnnotationItem.h"
#include <QPainter>
#include <QJsonValue>
#include <QJsonObject>
#include <QCursor>
#include <QUuid>

AnnotationItem::AnnotationItem(QGraphicsItem* parent) : QGraphicsObject(parent) {
    m_uid = QUuid::createUuid().toString(QUuid::WithoutBraces);
    setFlag(ItemIsMovable, true);
    setFlag(ItemSendsGeometryChanges, true);
    setFlag(ItemIsSelectable, true);
    setZValue(10);
    setCursor(QCursor(Qt::OpenHandCursor));
}

QJsonObject AnnotationItem::toJson() const {
    QJsonObject obj;
    obj["uid"] = m_uid;
    obj["type"] = type();
    obj["x"] = pos().x();
    obj["y"] = pos().y();
    obj["penColor"] = colorToJson(m_penColor);
    obj["penWidth"] = m_penWidth;
    obj["fillOpacity"] = m_fillOpacity;
    obj["locked"] = m_locked;
    obj["scale"] = scale();
    return obj;
}

void AnnotationItem::fromJson(const QJsonObject& obj) {
    if (obj.contains("uid")) m_uid = obj.value("uid").toString();
    setPenColor(colorFromJson(obj.value("penColor"), m_penColor));
    setPenWidth(obj.value("penWidth").toDouble(m_penWidth));
    setFillOpacity(obj.value("fillOpacity").toDouble(m_fillOpacity));
    setLocked(obj.value("locked").toBool(false));
    setPos(obj.value("x").toDouble(), obj.value("y").toDouble());
    const qreal s = obj.value("scale").toDouble(1.0);
    if (s > 0.001 && !qFuzzyCompare(s, 1.0)) {
        setTransformOriginPoint(QPointF(0, 0));
        setScale(s);
    }
}

void AnnotationItem::setPenColor(const QColor& c) {
    if (m_penColor == c) return;
    m_penColor = c;
    applyStyle();
    update();
}

void AnnotationItem::setPenWidth(qreal w) {
    if (qFuzzyCompare(m_penWidth, w)) return;
    m_penWidth = w;
    applyStyle();
    update();
}

void AnnotationItem::setFillOpacity(qreal v) {
    if (qFuzzyCompare(m_fillOpacity, v)) return;
    m_fillOpacity = v;
    applyStyle();
    update();
}

void AnnotationItem::setLocked(bool on) {
    if (m_locked == on) return;
    m_locked = on;
    setFlag(ItemIsMovable, !on);
    setCursor(on ? QCursor(Qt::ArrowCursor) : QCursor(Qt::OpenHandCursor));
    update();
}

void AnnotationItem::scaleBy(qreal factor, const QPointF& pivot) {
    scaleAbout(pivot, factor, factor);
}

void AnnotationItem::scaleAbout(const QPointF& scenePivot, qreal sx, qreal sy) {
    if (sx <= 0.0001 || sy <= 0.0001) return;
    prepareGeometryChange();
    setTransformOriginPoint(QPointF(0, 0));
    const QPointF p = pos();
    const QPointF np(scenePivot.x() + (p.x() - scenePivot.x()) * sx,
                     scenePivot.y() + (p.y() - scenePivot.y()) * sy);
    setScale(scale() * sx, scale() * sy);
    setPos(np);
    notifyContentChanged();
}

void AnnotationItem::notifyContentChanged() {
    update();
    emit contentChanged();
}

bool AnnotationItem::hitTest(const QPointF& scenePos, qreal radius) const {
    const QPointF local = mapFromScene(scenePos);
    if (shape().contains(local)) return true;
    const QRectF b = boundingRect();
    return b.adjusted(-radius, -radius, radius, radius).contains(local);
}

void AnnotationItem::drawSelectionFrame(QPainter* painter) const {
    if (!m_selected) return;
    painter->save();
    painter->setRenderHint(QPainter::Antialiasing);
    QPen pen(QColor(59, 125, 221), 1.4, Qt::DashLine);
    pen.setDashPattern({4.0, 3.0});
    painter->setPen(pen);
    painter->setBrush(Qt::NoBrush);
    painter->drawRect(contentBounds().adjusted(-5.0, -5.0, 5.0, 5.0));
    painter->restore();
}

QVariant AnnotationItem::itemChange(GraphicsItemChange change, const QVariant& value) {
    if (change == ItemSelectedHasChanged) {
        m_selected = value.toBool();
        update();
    }
    return QGraphicsObject::itemChange(change, value);
}

QJsonObject AnnotationItem::colorToJson(const QColor& c) {
    QJsonObject obj;
    obj["r"] = c.red();
    obj["g"] = c.green();
    obj["b"] = c.blue();
    obj["a"] = c.alpha();
    return obj;
}

QColor AnnotationItem::colorFromJson(const QJsonValue& v, const QColor& fallback) {
    if (!v.isObject()) return fallback;
    QJsonObject obj = v.toObject();
    return QColor(obj.value("r").toInt(fallback.red()),
                  obj.value("g").toInt(fallback.green()),
                  obj.value("b").toInt(fallback.blue()),
                  obj.value("a").toInt(fallback.alpha()));
}

#ifndef SELECTIONOVERLAY_H
#define SELECTIONOVERLAY_H
#include <QObject>
#include <QPointF>
#include <QRectF>
#include <QVector>

class AnnotationItem;
class ToolController;

class SelectionOverlay : public QObject {
    Q_OBJECT
public:
    enum Handle {
        None,
        TopLeft,
        TopCenter,
        TopRight,
        MiddleRight,
        BottomRight,
        BottomCenter,
        BottomLeft,
        MiddleLeft
    };

    explicit SelectionOverlay(ToolController* controller, QObject* parent = nullptr);

    void setItems(const QVector<AnnotationItem*>& items);
    void clear();
    bool isActive() const { return !m_items.isEmpty(); }

    QRectF sceneBounds() const;
    Handle handleAt(const QPointF& scenePos, qreal tolerance) const;
    QPointF handlePoint(Handle handle) const;

    void beginScale(const QPointF& scenePos, Handle handle);
    void updateScale(const QPointF& scenePos);
    void finishScale();
    bool isScaling() const { return m_scaling; }

    void paint(QPainter* painter) const;

private:
    ToolController* m_controller = nullptr;
    QVector<AnnotationItem*> m_items;
    bool m_scaling = false;
    Handle m_handle = None;
    QPointF m_scaleAnchor = QPointF();
    QRectF m_startBounds;
};

#endif

#include "SelectionOverlay.h"
#include "AnnotationItem.h"
#include "ToolController.h"
#include <QPainter>
#include <cmath>

SelectionOverlay::SelectionOverlay(ToolController* controller, QObject* parent)
    : QObject(parent), m_controller(controller) {}

void SelectionOverlay::setItems(const QVector<AnnotationItem*>& items) {
    m_items = items;
}

void SelectionOverlay::clear() {
    m_items.clear();
    m_scaling = false;
    m_handle = None;
}

QRectF SelectionOverlay::sceneBounds() const {
    QRectF bounds;
    for (AnnotationItem* item : m_items) {
        if (!item) continue;
        const QRectF r = item->mapRectToScene(item->contentBounds());
        bounds = bounds.isNull() ? r : bounds.united(r);
    }
    return bounds;
}

SelectionOverlay::Handle SelectionOverlay::handleAt(const QPointF& scenePos, qreal tolerance) const {
    if (m_items.isEmpty()) return None;
    const QRectF b = sceneBounds();
    if (b.isEmpty()) return None;
    static const Handle handles[] = {
        TopLeft, TopCenter, TopRight,
        MiddleRight, BottomRight, BottomCenter,
        BottomLeft, MiddleLeft
    };
    for (Handle h : handles) {
        const QPointF p = handlePoint(h);
        const qreal dx = scenePos.x() - p.x();
        const qreal dy = scenePos.y() - p.y();
        if (std::hypot(dx, dy) <= tolerance) return h;
    }
    return None;
}

QPointF SelectionOverlay::handlePoint(Handle handle) const {
    const QRectF b = sceneBounds();
    const qreal cx = b.center().x();
    const qreal cy = b.center().y();
    switch (handle) {
    case TopLeft: return b.topLeft();
    case TopCenter: return QPointF(cx, b.top());
    case TopRight: return b.topRight();
    case MiddleRight: return QPointF(b.right(), cy);
    case BottomRight: return b.bottomRight();
    case BottomCenter: return QPointF(cx, b.bottom());
    case BottomLeft: return b.bottomLeft();
    case MiddleLeft: return QPointF(b.left(), cy);
    default: return QPointF();
    }
}

void SelectionOverlay::beginScale(const QPointF& scenePos, Handle handle) {
    if (m_items.isEmpty() || handle == None) return;
    m_scaling = true;
    m_handle = handle;
    m_scaleAnchor = scenePos;
    m_startBounds = sceneBounds();
}

void SelectionOverlay::updateScale(const QPointF& scenePos) {
    if (!m_scaling || !m_controller) return;
    const QRectF b = m_startBounds;
    if (b.width() < 1.0 || b.height() < 1.0) return;

    qreal sx = 1.0;
    qreal sy = 1.0;
    QPointF anchor = b.topLeft();

    switch (m_handle) {
    case TopLeft:
        sx = (scenePos.x() - b.right()) / b.width();
        sy = (scenePos.y() - b.bottom()) / b.height();
        anchor = b.bottomRight();
        break;
    case TopCenter:
        sy = (scenePos.y() - b.bottom()) / b.height();
        anchor = b.bottomCenter();
        break;
    case TopRight:
        sx = (scenePos.x() - b.left()) / b.width();
        sy = (scenePos.y() - b.bottom()) / b.height();
        anchor = b.bottomLeft();
        break;
    case MiddleRight:
        sx = (scenePos.x() - b.left()) / b.width();
        anchor = b.leftCenter();
        break;
    case BottomRight:
        sx = (scenePos.x() - b.left()) / b.width();
        sy = (scenePos.y() - b.top()) / b.height();
        anchor = b.topLeft();
        break;
    case BottomCenter:
        sy = (scenePos.y() - b.top()) / b.height();
        anchor = b.topCenter();
        break;
    case BottomLeft:
        sx = (scenePos.x() - b.right()) / b.width();
        sy = (scenePos.y() - b.top()) / b.height();
        anchor = b.topRight();
        break;
    case MiddleLeft:
        sx = (scenePos.x() - b.right()) / b.width();
        anchor = b.rightCenter();
        break;
    default:
        return;
    }

    if (sx < 0.05 || sy < 0.05) return;
    m_controller->scaleSelectionAbout(anchor, sx, sy);
}

void SelectionOverlay::finishScale() {
    m_scaling = false;
    m_handle = None;
}

void SelectionOverlay::paint(QPainter* painter) const {
    if (m_items.isEmpty()) return;
    const QRectF b = sceneBounds();
    if (b.isEmpty()) return;

    painter->save();
    painter->setRenderHint(QPainter::Antialiasing);

    QPen frame(QColor(59, 125, 221), 1.2);
    frame.setCosmetic(true);
    painter->setPen(frame);
    painter->setBrush(Qt::NoBrush);
    painter->drawRect(b);

    QPen handlePen(QColor(59, 125, 221), 1.4);
    handlePen.setCosmetic(true);
    painter->setPen(handlePen);
    painter->setBrush(QColor(255, 255, 255));

    static const Handle handles[] = {
        TopLeft, TopCenter, TopRight,
        MiddleRight, BottomRight, BottomCenter,
        BottomLeft, MiddleLeft
    };
    for (Handle h : handles) {
        const QPointF p = handlePoint(h);
        painter->drawRect(QRectF(p.x() - 3.5, p.y() - 3.5, 7, 7));
    }
    painter->restore();
}

#ifndef CANVASTABLEITEM_H
