    m_activeShape = new ShapeItem(kind);
    m_activeShape->setPenColor(m_penColor);
    m_activeShape->setPenWidth(m_penWidth);
    m_activeShape->setFillOpacity(m_opacity);
    m_activeShape->setPos(0, 0);
