            sendKey(&view, Qt::Key_H, QString("H"));
            sendKey(&view, Qt::Key_I, QString("i"));
            pump(150);
            check("textbox: typing lands in the text box", box->plainText() == QString("Hi"));
            QImage shot = view.grab().toImage();
            shot.save("smart_textbox.png");
            const QPoint tl = view.mapFromScene(box->mapRectToScene(box->contentBounds()).topLeft());
            bool whiteBg = false;
            for (int dy = 2; dy < 14 && !whiteBg; ++dy) {
                for (int dx = 2; dx < 14; ++dx) {
                    const QPoint p = tl + QPoint(dx, dy);
                    if (p.x() < 0 || p.y() < 0 || p.x() >= shot.width() || p.y() >= shot.height()) continue;
                    const QColor c = shot.pixelColor(p);
                    if (c.red() > 245 && c.green() > 245 && c.blue() > 245) { whiteBg = true; break; }
                }
            }
            check("textbox: background is fully transparent (no white card)", !whiteBg);
        }
