void AnnotationItem::scaleAbout(const QPointF& scenePivot, qreal sx, qreal sy) {
    if (sx <= 0.0001 || sy <= 0.0001) return;
    prepareGeometryChange();
    setTransformOriginPoint(QPointF(0, 0));
    const QPointF p = pos();
    const QPointF np(scenePivot.x() + (p.x() - scenePivot.x()) * sx,
                     scenePivot.y() + (p.y() - scenePivot.y()) * sy);
    const qreal s = scale() * sx;
    setScale(s);
    setPos(np);
    notifyContentChanged();
}

void AnnotationItem::scaleAbout(const QPointF& scenePivot, qreal sx, qreal sy) {
    if (sx <= 0.0001 || sy <= 0.0001) return;
    prepareGeometryChange();
    setTransformOriginPoint(QPointF(0, 0));
    const qreal k = scale();
    const QPointF p = pos();
    const qreal newScaleX = k * sx;
    const qreal newScaleY = k * sy;
    const QPointF newPos(p.x() * sx + scenePivot.x() * (1.0 - sx),
                         p.y() * sy + scenePivot.y() * (1.0 - sy));
    setScale(newScaleX, newScaleY);
    setPos(newPos);
    notifyContentChanged();
}

