void AnnotationItem::applyFrame(const Frame& frame) {
    prepareGeometryChange();
    setTransformOriginPoint(QPointF(0, 0));
    QTransform t;
    t.setMatrix(frame.basisX.x(), frame.basisY.x(), 0.0,
                frame.basisX.y(), frame.basisY.y(), 0.0,
                0.0, 0.0, 1.0);
    setTransform(t);
    setPos(frame.origin);
}

void AnnotationItem::applyFrame(const Frame& frame) {
    prepareGeometryChange();
    setTransformOriginPoint(QPointF(0, 0));
    const qreal sx = std::hypot(frame.basisX.x(), frame.basisX.y());
    const qreal sy = std::hypot(frame.basisY.x(), frame.basisY.y());
    const qreal uniform = qMax(sx, sy);
    if (uniform > 0.0001 && qFuzzyCompare(sx / uniform, sy / uniform)) {
        setScale(uniform);
    } else {
        QTransform t;
        t.setMatrix(frame.basisX.x(), frame.basisY.x(), 0.0,
                    frame.basisX.y(), frame.basisY.y(), 0.0,
                    0.0, 0.0, 1.0);
        setTransform(t);
    }
    setPos(frame.origin);
}

void CanvasToolBar::placePanel(QWidget* panel, int barX, int barW, int barY, int barH) {
    if (!panel || !m_host) return;
    panel->adjustSize();
    const int panelW = panel->sizeHint().width();
    const int panelH = panel->sizeHint().height();
    const int areaW = m_host->width();
    const int areaH = m_host->height();
    int px = barX + barW - panelW;
    if (px + panelW > areaW - 8) px = areaW - panelW - 8;
    if (px < 8) px = 8;
    int py = barY + barH + 10;
    if (py + panelH > areaH - 8) py = barY - panelH - 10;
    if (py < 8) py = 8;
    panel->setGeometry(px, py, panelW, panelH);
}

