    QAction* kCols = menu.addAction("插入 k 列...");
    connect(kCols, &QAction::triggered, this, [this]() { promptInsertCols(); });
    menu.addSeparator();
    QAction* delRow = menu.addAction("删除当前行");
    delRow->setEnabled(currentRow() >= 0);
