static int g_fail = 0;
static void check(const char* name, bool ok) {
    printf("[%s] %s\n", ok ? "PASS" : "FAIL", name);
    if (!ok) g_fail++;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    MyColorPicker picker;
    picker.resize(244, 430);
    picker.setColor(QColor(229, 72, 77));
    picker.show();
    app.processEvents();

    const QImage shot = picker.grab().toImage();

    const ColorField* field = picker.findChild<ColorField*>("colorField");
    check("color field widget exists", field != nullptr);

    const ColorPreview* preview = picker.findChild<ColorPreview*>("colorPreview");
    check("preview widget exists", preview != nullptr);

    if (field) {
        const QRectF hr = QRectF(0, field->height() - 14.0, field->width(), 14.0);
        const QImage fs = field->grab().toImage();
        const QColor left = fs.pixel(3, static_cast<int>(hr.center().y()));
        const QColor mid = fs.pixel(fs.width() / 2, static_cast<int>(hr.center().y()));
        const QColor right = fs.pixel(fs.width() - 4, static_cast<int>(hr.center().y()));
        printf("hue bar left=%s mid=%s right=%s\n", left.name().toLatin1().constData(),
               mid.name().toLatin1().constData(), right.name().toLatin1().constData());
        check("hue bar left is red-ish", left.red() > left.green() + 40);
        check("hue bar mid is green-ish", mid.green() > mid.red() + 20);
        check("hue bar right is magenta-ish", right.red() > 60 && right.blue() > 60);
        check("hue bar is a real gradient, not one solid color",
              left != mid && mid != right);
    }

    if (preview) {
        const QImage ps = preview->grab().toImage();
        const QColor c = ps.pixel(ps.width() / 2, ps.height() / 2);
        printf("preview color=%s\n", c.name().toLatin1().constData());
        check("preview shows the current color, not black", c != QColor(0, 0, 0));
    }

    const QImage top = shot.toImage();
    printf("picker size=%dx%d\n", shot.width(), shot.height());

    check("no label reads the old gradient preset name", true);
    for (QLabel* l : picker.findChildren<QLabel*>()) {
        if (l->text() == "渐变预设") {
            check("label renamed to 预设", false);
            break;
        }
    }
    bool hasPreset = false;
    for (QLabel* l : picker.findChildren<QLabel*>()) {
        if (l->text() == "预设") hasPreset = true;
    }
    check("label renamed to 预设", hasPreset);

    printf("\nfailures=%d\n", g_fail);
    return g_fail;
}

