bool ToolController::handleKeyPress(QKeyEvent* event) {
    if (!event) return false;
    onKeyPress(event);
    return event->isAccepted();
}

void ToolController::onKeyPress(QKeyEvent* event) {
    if (m_editingItem) {
        if (!m_editingItem->isInlineEditing()) {
            m_editingItem = nullptr;
        } else {
            m_editingItem->handleEditKey(event);
            event->accept();
            return;
        }
    }

    const bool ctrl = event->modifiers().testFlag(Qt::ControlModifier);
    if (ctrl) {
        if (event->key() == Qt::Key_Z) {
            if (event->modifiers().testFlag(Qt::ShiftModifier)) redo();
            else undo();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_Y) {
            redo();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_C) {
            copySelection();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_X) {
            cutSelection();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_V) {
            pasteAtCursor();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_A) {
            selectAll();
            event->accept();
            return;
        }
        return;
    }

    if (event->key() == Qt::Key_Backspace || event->key() == Qt::Key_Delete) {
        if (!m_selected.isEmpty()) {
            deleteSelected();
            event->accept();
            return;
        }
    }

    if (event->modifiers().testFlag(Qt::ShiftModifier)) {
        return;
    }

    if (applyColorShortcut(event)) {
        event->accept();
        return;
    }
}

