void FastPowModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    if (tokens.size() >= 3) {
        m_base = tokens[0].toInt(&ok);
        bool ok2 = ok;
        m_exp = tokens[1].toInt(&ok2);
        bool ok3 = ok2;
        m_mod = tokens[2].toInt(&ok3);
        m_valid = ok3 && m_base > 0 && m_exp >= 1 && m_exp <= 40 && m_mod >= 2 && m_mod <= 2000000000;
    }

    m_mathText = scene->addText(m_valid ? "快速幂：qpow 外层位分解 + qmul 内层竖式乘法" : "输入格式：a b p（底数 指数 模数）");
    m_mathText->setFont(QFont("Consolas", 14, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(60, 18);
    if (!m_valid) return;

    QFont labelFont("Microsoft YaHei", 10, QFont::Bold);
    auto addLabel = [scene, labelFont](const QString& text, QPointF pos) {
        QGraphicsTextItem* item = scene->addText(text);
        item->setFont(labelFont);
        item->setDefaultTextColor(QColor(60, 75, 95));
        item->setPos(pos);
    };

    addLabel("底数 a", QPointF(40, 130));
    m_baseBlock = new ArrayBlock(1, m_base, "a");
    m_baseBlock->setCellSize(120, 52);
    m_baseBlock->setPos(60, 155);
    m_baseBlock->color = kFpBase;
    scene->addItem(m_baseBlock);

    addLabel("结果 res", QPointF(40, 250));
    m_resBlock = new ArrayBlock(2, 1, "res");
    m_resBlock->setCellSize(120, 52);
    m_resBlock->setPos(60, 275);
    m_resBlock->color = kFpRes;
    scene->addItem(m_resBlock);

    addLabel("指数 b", QPointF(40, 370));
    m_expBlock = new ArrayBlock(3, m_exp, "b");
    m_expBlock->setCellSize(120, 52);
    m_expBlock->setPos(60, 395);
    scene->addItem(m_expBlock);

    addLabel("指数的二进制位（从低位到高位）", QPointF(230, 130));
    std::vector<int> bits;
    int tmp = m_exp;
    while (tmp > 0) {
        bits.push_back(tmp & 1);
        tmp >>= 1;
    }
    for (size_t i = 0; i < bits.size(); ++i) {
        ArrayBlock* block = new ArrayBlock(static_cast<int>(i) + 10, bits[i], QString::number(i));
        block->setCellSize(52, 46);
