}

std::vector<AnimFrame> FastPowModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;
    m_base = liveValue("a", 0, m_base);
    m_exp = liveValue("b", 0, m_exp);
    m_mod = liveValue("p", 0, m_mod);

    m_frames.push_back({ActionType::FP_RESET, 0, 0, m_base, m_exp, {},
                        QString("初始化：res = 1，a = %1，b = %2").arg(m_base).arg(m_exp),
                        QString("res = 1　a = %1　b = %2　p = %3").arg(m_base).arg(m_exp).arg(m_mod)});

    long long res = 1;
    long long a = m_base;
    long long b = m_exp;
    int bitIndex = 0;

    auto qmul = [&](long long x, long long y) {
        if (x < y) std::swap(x, y);
        long long acc = 0;
        m_frames.push_back({ActionType::FP_QMUL_INIT, static_cast<int>(x), static_cast<int>(y), 0, 0, {},
                            QString("qmul(%1, %2)：进入竖式乘法").arg(x).arg(y),
                            QString("qmul(%1, %2)　res = 0").arg(x).arg(y)});
        long long bb = y;
        while (bb > 0) {
            bool odd = (bb & 1);
            m_frames.push_back({ActionType::FP_QMUL_ROW, static_cast<int>(bb), odd ? 1 : 0,
                                static_cast<int>(a), static_cast<int>(res), {},
                                odd ? QString("b 的最低位为 1，res += a")
                                    : QString("b 的最低位为 0，只右移"),
                                odd ? QString("res = (res + a) mod p")
                                    : QString("b >>= 1")});
            if (odd) {
                res = (res + a) % m_mod;
                m_frames.push_back({ActionType::FP_QMUL_ACC, static_cast<int>(res), 0, static_cast<int>(res), 0, {},
                                    QString("累加后 res = %1").arg(res),
                                    QString("res = %1").arg(res)});
            }
            bb >>= 1;
            a = (a + a) % m_mod;
            m_frames.push_back({ActionType::FP_QMUL_ROW, static_cast<int>(bb), 2, static_cast<int>(a), 0, {},
                                QString("底数自我平方，a = %1").arg(a),
                                QString("a = (a + a) mod p = %1").arg(a)});
        }
        m_frames.push_back({ActionType::FP_QMUL_DONE, static_cast<int>(res), 0, static_cast<int>(res), 0, {},
                            QString("qmul 完成，返回 %1").arg(res),
                            QString("qmul 返回 %1").arg(res)});
        return res;
    };

    while (b > 0) {
        int currentBit = static_cast<int>(b & 1);
        m_frames.push_back({ActionType::FP_BIT, bitIndex, currentBit, currentBit, static_cast<int>(b), {},
                            QString("处理第 %1 个二进制位，b = %2").arg(bitIndex).arg(b),
                            QString("b & 1 = %1").arg(currentBit)});
        if (currentBit == 1) {
            m_frames.push_back({ActionType::FP_MUL, 0, 0, static_cast<int>(res), static_cast<int>(a), {},
                                QString("该位为 1，res = qmul(res, a) mod p").arg(a),
                                QString("res = qmul(res, a) mod p")});
            res = qmul(res, a) % m_mod;
            m_frames.push_back({ActionType::FP_RESULT, static_cast<int>(res), 0, static_cast<int>(res), 0, {},
                                QString("res 更新为 %1").arg(res),
                                QString("res = %1").arg(res)});
        }
        m_frames.push_back({ActionType::FP_SQUARE, 0, 0, static_cast<int>(a), 0, {},
                            QString("底数平方：a = qmul(a, a) mod p").arg(a),
                            QString("a = qmul(a, a) mod p")});
        long long squared = qmul(a, a) % m_mod;
        m_frames.push_back({ActionType::FP_SQUARE, 1, 0, static_cast<int>(squared), 0, {},
                            QString("平方完成，a = %1").arg(squared),
                            QString("a = %1").arg(squared)});
        a = squared;
        b >>= 1;
        bitIndex++;
        m_frames.push_back({ActionType::FP_SHIFT, 0, 0, static_cast<int>(b), bitIndex, {},
                            QString("指数右移，b = %1").arg(b),
                            QString("b >>= 1 → %1").arg(b)});
    }
    m_frames.push_back({ActionType::FP_RESULT, static_cast<int>(res), 1, static_cast<int>(res), 0, {},
                        QString("%1 ^ %2 mod %3 = %4").arg(m_base).arg(m_exp).arg(m_mod).arg(res),
                        QString("最终结果 = %1").arg(res)});
    return m_frames;
}

void FastPowModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::FP_RESET) {
        if (m_baseBlock) {
            m_baseBlock->value = m_base;
            m_baseBlock->customValue.clear();
            m_baseBlock->showValue = true;
            m_baseBlock->color = kFpBase;
            m_baseBlock->update();
        }
        if (m_resBlock) {
            m_resBlock->value = 1;
            m_resBlock->customValue.clear();
            m_resBlock->showValue = true;
            m_resBlock->color = kFpRes;
            m_resBlock->update();
        }
        if (m_expBlock) {
            m_expBlock->value = m_exp;
            m_expBlock->customValue.clear();
            m_expBlock->showValue = true;
            m_expBlock->update();
        }
        for (size_t i = 0; i < m_bitBlocks.size(); ++i) {
            m_bitBlocks[i]->color = kFpPale;
            m_bitBlocks[i]->update();
        }
        if (m_qmulTitle) m_qmulTitle->setPlainText("");
        if (m_qmulText) m_qmulText->setPlainText("");
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_ptrK) m_ptrK->setOpacity(0);
    } else if (frame.type == ActionType::FP_BIT) {
        for (size_t i = 0; i < m_bitBlocks.size(); ++i) {
            m_bitBlocks[i]->color = kFpPale;
            m_bitBlocks[i]->update();
        }
        int index = frame.u;
        if (index >= 0 && index < static_cast<int>(m_bitBlocks.size())) {
            ArrayBlock* block = m_bitBlocks[index];
            block->color = frame.val1 == 1 ? kFpHit : kFpBit;
            block->update();
            if (m_animated) playScalePulse(block, 1.2, 240);
        }
        if (m_ptrK) {
            m_ptrK->setOpacity(1);
            m_ptrK->setPos(240 + index * 60 + 26, 145);
        }
        if (m_ptrB && m_expBlock) {
            m_ptrB->setOpacity(1);
            m_ptrB->setPos(m_expBlock->pos().x() + 60, 440);
        }
    } else if (frame.type == ActionType::FP_SQUARE) {
        if (frame.v == 1 && m_baseBlock) {
            m_baseBlock->value = frame.val1;
            m_baseBlock->customValue.clear();
            m_baseBlock->showValue = true;
            m_baseBlock->update();
            if (m_animated) playScaleAnim(m_baseBlock);
        }
    } else if (frame.type == ActionType::FP_RESULT) {
        if (m_resBlock) {
            m_resBlock->value = frame.val1;
            m_resBlock->customValue.clear();
            m_resBlock->showValue = true;
            m_resBlock->update();
            if (m_animated) playScalePulse(m_resBlock, 1.24, 300);
        }
    } else if (frame.type == ActionType::FP_QMUL_INIT) {
        if (m_qmulTitle) m_qmulTitle->setPlainText(QString("qmul(%1, %2)").arg(frame.val1).arg(frame.u));
        if (m_qmulText) {
            m_qmulText->setPlainText(QString("res = 0\n底数 a = %1　乘数 b = %2").arg(frame.val1).arg(frame.u));
            m_qmulText->setDefaultTextColor(QColor(30, 60, 100));
        }
    } else if (frame.type == ActionType::FP_QMUL_ROW) {
        if (!m_qmulText) return;
        if (frame.v == 1) {
            m_qmulText->setPlainText(QString("res = (res + a) mod p\na = %1　b = %2").arg(frame.val1).arg(frame.u));
        } else if (frame.v == 2) {
            m_qmulText->setPlainText(QString("b >>= 1\na = (a + a) mod p = %1").arg(frame.val1));
        } else {
            m_qmulText->setPlainText(QString("b 的最低位为 0，只右移\na = %1　b = %2").arg(frame.val1).arg(frame.u));
        }
    } else if (frame.type == ActionType::FP_QMUL_ACC) {
        if (m_qmulText) {
            m_qmulText->setPlainText(QString("res = (res + a) mod p = %1").arg(frame.val1));
            m_qmulText->setDefaultTextColor(QColor(40, 140, 70));
        }
    } else if (frame.type == ActionType::FP_QMUL_DONE) {
        if (m_qmulText) {
            m_qmulText->setPlainText(QString("qmul 返回 %1").arg(frame.val1));
            m_qmulText->setDefaultTextColor(QColor(40, 140, 70));
        }
    }
}

