void DijkstraHeapModule::layoutHeapView(int capacity) {
    const double cellW = 56.0;
    const double cellH = 38.0;
    const double arrayX = 80.0;
    const double arrayY = 520.0;
    const double treeCenterX = 320.0;
    const double treeTop = 300.0;
    const double levelGap = 66.0;

    QGraphicsTextItem* arrayTitle = m_scene->addText("优先队列（数组存储）");
    arrayTitle->setFont(QFont("Microsoft YaHei", 10, QFont::Bold));
    arrayTitle->setDefaultTextColor(QColor(60, 75, 95));
    arrayTitle->setPos(arrayX - 10, arrayY - 28);

    for (int i = 1; i <= capacity; ++i) {
        ArrayBlock* block = new ArrayBlock(i, 0, QString::number(i));
        block->setCellSize(cellW, cellH);
        block->setPos(arrayX + (i - 1) * cellW, arrayY);
        block->color = kDhPale;
        block->setOpacity(0);
        m_scene->addItem(block);
        m_heapArrayBlocks[i] = block;
    }

    QGraphicsTextItem* treeTitle = m_scene->addText("最小堆（完全二叉树）");
    treeTitle->setFont(QFont("Microsoft YaHei", 10, QFont::Bold));
    treeTitle->setDefaultTextColor(QColor(60, 75, 95));
    treeTitle->setPos(treeCenterX - 90, treeTop - 74);

    for (int i = 1; i <= capacity; ++i) {
        int depth = 0;
        while ((1 << (depth + 1)) <= i) ++depth;
        int levelStart = 1 << depth;
        int levelCount = std::min(1 << depth, capacity - levelStart + 1);
        int posInLevel = i - levelStart;
        double span = 150.0 * std::pow(2.0, depth) / std::pow(2.0, 5);
        double x = treeCenterX + (posInLevel - (levelCount - 1) / 2.0) * (span * 2.0 / std::max(1, levelCount));
        double y = treeTop + depth * levelGap;
        GraphNode* node = new GraphNode(i);
        node->setPos(x, y);
        node->color = kDhPale;
        node->setCustomValueText("");
        node->setSubLabel(QString::number(i));
        node->setOpacity(0);
        m_scene->addItem(node);
        m_heapTreeNodes[i] = node;
        int parent = i / 2;
        if (parent >= 1) {
            GraphEdge* edge = new GraphEdge(m_heapTreeNodes[parent], node, false, false);
            edge->color = QColor(178, 188, 204);
            m_scene->addItem(edge);
            m_heapTreeNodes[parent]->addEdge(edge);
            node->addEdge(edge);
            m_heapTreeEdges[{parent, i}] = edge;
        }
    }
}

void DijkstraHeapModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    GraphModuleUtils::GraphInput input;
    m_valid = GraphModuleUtils::parse(inputData, true, m_options, input);
    if (m_valid && input.weighted) {
        for (const auto& edge : input.edges) if (edge.w < 0) m_valid = false;
    }
    m_mathText = scene->addText(m_valid ? "堆优化 Dijkstra：优先队列 + 懒删除（无 vis 数组）" : "输入格式：n m src，随后输入 m 条非负权边 u v w");
    m_mathText->setFont(QFont("Consolas", 14, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(60, 18);
    if (!m_valid) return;

    m_n = input.n;
    m_m = input.m;
    m_src = input.src;
    m_edgesInput = input.edges;
    m_heapCapacity = std::max(8, std::min(20, m_m * 2 + 2));

    GraphRenderHelper::buildNodes(scene, m_nodes, m_n, QPointF(760, 230), m_n <= 8 ? 130 : 150, this);
    GraphRenderHelper::buildEdges(scene, m_nodes, m_edges, input.edges, m_options, input.weighted);
    GraphRenderHelper::registerEdgeSlots(this, m_edges, input.edges, m_options);

    GraphRenderHelper::addLabel(scene, "dis", QPointF(40, 640));
    for (int i = 1; i <= m_n; ++i) {
        ArrayBlock* dist = new ArrayBlock(i, 0, QString::number(i));
        dist->setCellSize(56, 40);
        dist->setPos(100 + (i - 1) * 60, 655);
        dist->setCustomValue("∞");
        dist->color = kDhPale;
        scene->addItem(dist);
        m_distBlocks[i] = dist;
        registerArraySlot(dist, "dis", i);
    }

    layoutHeapView(m_heapCapacity);

    m_heapText = scene->addText("");
    m_heapText->setFont(QFont("Consolas", 13, QFont::Bold));
    m_heapText->setDefaultTextColor(QColor(40, 70, 110));
    m_heapText->setPos(80, 585);

    m_ptrU = new PointerBlock("u", QColor(210, 80, 55));
    m_ptrU->setOpacity(0);
    scene->addItem(m_ptrU);
}

std::vector<AnimFrame> DijkstraHeapModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;
    constexpr int inf = 1000000000;

    std::vector<int> dist(m_n + 1, inf);
    dist[m_src] = 0;

    std::vector<std::pair<int, int>> heap;
    std::vector<std::vector<std::pair<int, int>>> adj(m_n + 1);
    for (size_t i = 0; i < m_edgesInput.size(); ++i) {
        const auto& edge = m_edgesInput[i];
        int w = liveValue("w", static_cast<int>(i), edge.w);
        adj[edge.u].push_back({edge.v, w});
        if (!m_options.directed) adj[edge.v].push_back({edge.u, w});
    }

    m_frames.push_back({ActionType::DH_RESET, m_src, 0, 0, 0, {},
                        QString("初始化 dis[] = ∞，源点 %1 入堆").arg(m_src),
                        QString("dis[%1] = 0　pq.push({0, %1})").arg(m_src)});
    heap.push_back({0, m_src});
    m_frames.push_back({ActionType::DH_PUSH, static_cast<int>(heap.size()), m_src, 0, m_src, {1, 0, 0},
                        QString("把 {0, %1} 压入最小堆").arg(m_src),
                        QString("pq.push({0, %1})").arg(m_src)});

    int guard = 0;
    while (!heap.empty() && guard++ < 4000) {
        std::pair<int, int> top = heap.front();
        heap.erase(heap.begin());
        int d = top.first;
        int u = top.second;
        m_frames.push_back({ActionType::DH_POP, static_cast<int>(heap.size()) + 1, u, d, 0, {1, 0, 0},
                            QString("弹出堆顶 {d=%1, u=%2}").arg(d).arg(u),
                            QString("pq.top() = {%1, %2}").arg(d).arg(u)});
        if (d > dist[u]) {
            m_frames.push_back({ActionType::DH_SKIP, u, 0, d, dist[u], {},
                                QString("d=%1 > dis[%2]=%3，是过期条目，直接跳过").arg(d).arg(u).arg(dist[u]),
                                QString("if (d > dis[u]) continue")});
            continue;
        }
        m_frames.push_back({ActionType::DH_RELAX, u, 0, dist[u], 0, {2, 0, 0},
                            QString("确定结点 %1 的最短距离 dis[%1] = %2").arg(u).arg(dist[u]),
                            QString("dis[%1] = %2").arg(u).arg(dist[u])});
        for (const auto& pair : adj[u]) {
            int v = pair.first;
            int w = pair.second;
            if (dist[u] + w < dist[v]) {
                int old = dist[v];
                dist[v] = dist[u] + w;
                heap.push_back({dist[v], v});
                m_frames.push_back({ActionType::DH_RELAX, u, v, dist[v], old, {2, 1, v},
                                    QString("松弛成功：dis[%1] = %2，{ %2, %1 } 入堆").arg(v).arg(dist[v]),
                                    QString("dis[%1] = dis[%2] + %3 = %4").arg(v).arg(u).arg(w).arg(dist[v])});
                m_frames.push_back({ActionType::DH_PUSH, static_cast<int>(heap.size()), v, dist[v], v, {1, 0, v},
                                    QString("把 { %1, %2 } 压入最小堆").arg(dist[v]).arg(v),
                                    QString("pq.push({%1, %2})").arg(dist[v]).arg(v)});
            }
        }
    }
    m_frames.push_back({ActionType::DH_FINISH, m_n, 0, 0, 0, {},
                        QString("Dijkstra 堆优化完成", QString()),
                        QString("时间复杂度 O(M log N)")});
    return m_frames;
}

void DijkstraHeapModule::syncHeapTree() {
    for (auto& kv : m_heapTreeNodes) {
        kv.second->update();
    }
}

void DijkstraHeapModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::DH_RESET) {
        for (auto& kv : m_nodes) { kv.second->color = Qt::white; kv.second->update(); }
        for (auto& kv : m_edges) { kv.second->setColor(Qt::black); kv.second->update(); }
        for (int i = 1; i <= m_n; ++i) {
            if (!m_distBlocks.count(i)) continue;
            m_distBlocks[i]->setCustomValue("∞");
            m_distBlocks[i]->color = kDhPale;
            m_distBlocks[i]->update();
        }
        for (auto& kv : m_heapArrayBlocks) { kv.second->setOpacity(0); kv.second->color = kDhPale; kv.second->update(); }
        for (auto& kv : m_heapTreeNodes) { kv.second->setOpacity(0); kv.second->color = kDhPale; kv.second->update(); }
        for (auto& kv : m_heapTreeEdges) { kv.second->color = QColor(178, 188, 204); kv.second->update(); }
        if (m_distBlocks.count(m_src)) {
            m_distBlocks[m_src]->setCustomValue("0");
            m_distBlocks[m_src]->color = QColor(170, 220, 245);
            m_distBlocks[m_src]->update();
        }
        if (m_ptrU) m_ptrU->setOpacity(0);
        if (m_heapText) m_heapText->setPlainText("");
    } else if (frame.type == ActionType::DH_PUSH) {
        int slot = frame.u;
        int node = frame.val2;
        if (slot >= 1 && slot <= static_cast<int>(m_heapArrayBlocks.size()) && m_heapArrayBlocks.count(slot)) {
            ArrayBlock* block = m_heapArrayBlocks[slot];
            block->value = frame.val1;
            block->customValue.clear();
            block->showValue = true;
            block->color = kDhHeap;
            block->setOpacity(1.0);
            block->update();
            if (m_animated) playScalePulse(block, 1.2, 260);
        }
        if (node > 0 && m_heapTreeNodes.count(node)) {
            GraphNode* tn = m_heapTreeNodes[node];
            tn->setCustomValueText(QString("%1,%2").arg(frame.val1).arg(node));
            tn->color = kDhHeap;
            tn->setOpacity(1.0);
            tn->update();
        }
        if (m_heapText) {
            m_heapText->setPlainText(QString("堆大小 %1　新元素 { %2, %3 }").arg(slot).arg(frame.val1).arg(node));
        }
    } else if (frame.type == ActionType::DH_POP) {
        int slot = frame.u;
        if (slot >= 1 && slot <= static_cast<int>(m_heapArrayBlocks.size()) && m_heapArrayBlocks.count(slot)) {
            ArrayBlock* block = m_heapArrayBlocks[slot];
            block->setOpacity(0);
            block->color = kDhPale;
            block->update();
        }
        int node = frame.v;
        if (node > 0 && m_heapTreeNodes.count(node)) {
            GraphNode* tn = m_heapTreeNodes[node];
            tn->setCustomValueText("");
            tn->color = kDhTop;
            tn->setOpacity(1.0);
            tn->update();
            if (m_animated) playScalePulse(tn, 1.28, 300);
        }
        if (m_ptrU) {
            m_ptrU->setOpacity(1);
            if (m_nodes.count(node)) {
                m_ptrU->setAnchorNode(m_nodes[node]);
                m_ptrU->syncToAnchor();
            }
        }
        if (m_heapText) {
            m_heapText->setPlainText(QString("弹出堆顶 { %1, %2 }，剩余 %3 个").arg(frame.val1).arg(node).arg(slot - 1));
        }
    } else if (frame.type == ActionType::DH_SKIP) {
        int node = frame.u;
        if (node > 0 && m_heapTreeNodes.count(node)) {
            GraphNode* tn = m_heapTreeNodes[node];
            tn->color = kDhStale;
            tn->setCustomValueText(QString("%1,%2").arg(frame.val1).arg(node));
            tn->update();
        }
        if (m_heapText) {
            m_heapText->setPlainText(QString("过期条目：%1 > dis[%2]，跳过").arg(frame.val1).arg(node));
        }
    } else if (frame.type == ActionType::DH_RELAX) {
        int u = frame.u;
        int v = frame.v;
        bool isUpdate = frame.group.size() > 1 && frame.group[1] == 1;
        if (frame.group.size() > 0 && frame.group[0] == 2) {
            if (u > 0 && m_nodes.count(u)) {
                m_nodes[u]->color = QColor(150, 220, 190);
                m_nodes[u]->update();
            }
            if (v > 0 && m_distBlocks.count(v)) {
                m_distBlocks[v]->setCustomValue(QString::number(frame.val1));
                m_distBlocks[v]->color = QColor(170, 220, 245);
                m_distBlocks[v]->update();
            }
            if (isUpdate) {
                auto it = m_edges.find({u, v});
                if (it == m_edges.end()) it = m_edges.find({v, u});
                if (it != m_edges.end()) {
                    it->second->setColor(QColor(70, 175, 125));
                    it->second->update();
                }
                if (v > 0 && m_nodes.count(v)) {
                    m_nodes[v]->color = QColor(155, 220, 245);
                    m_nodes[v]->update();
                }
                if (m_animated && m_nodes.count(v)) {
                    playRipple(m_nodes[v]->pos(), QColor(110, 200, 150), 50.0, 560);
                }
            }
            if (m_heapText) {
                m_heapText->setPlainText(isUpdate
                    ? QString("松弛 %1 → %2：dis[%2] = %3").arg(u).arg(v).arg(frame.val1)
                    : QString("确定结点 %1：dis[%1] = %2").arg(u).arg(frame.val1));
            }
        }
    } else if (frame.type == ActionType::DH_FINISH) {
        if (m_ptrU) m_ptrU->setOpacity(0);
        if (m_heapText) m_heapText->setPlainText("堆优化 Dijkstra 完成");
    }
}

