int TreeDiameterModule::parentOf(int root, int node) const {
    for (const auto& kv : m_children) {
        const auto& list = kv.second;
        for (size_t i = 0; i < list.size(); ++i) {
            if (list[i] != node) continue;
            if (kv.first == root && i == 0) continue;
            return kv.first;
        }
    }
    return root;
}

