std::vector<AnimFrame> FastPowModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;
    m_base = liveValue("a", 0, static_cast<int>(m_base));
    m_exp = liveValue("b", 0, static_cast<int>(m_exp));
    if (m_hasMod) m_mod = liveValue("p", 0, static_cast<int>(m_mod));

    const QString modSuffix = m_hasMod ? QString(" mod %1").arg(m_mod) : QString();

    m_frames.push_back({ActionType::FP_RESET, 0, 0, static_cast<int>(m_base), static_cast<int>(m_exp), {},
                        QString("初始化：a = %1，b = %2，res = 1").arg(m_base).arg(m_exp),
                        QString("a = %1　b = %2　res = 1%3").arg(m_base).arg(m_exp).arg(modSuffix)});

    long long res = 1;
    long long a = m_base;
    long long b = m_exp;
    int bitIndex = 0;

    while (b > 0) {
        long long bit = b & 1LL;
        m_frames.push_back({ActionType::FP_BIT, bitIndex, static_cast<int>(bit), static_cast<int>(bit), static_cast<int>(b), {},
                            QString("b %% 2 = %1，写入二进制第 %2 位").arg(bit).arg(bitIndex),
                            QString("b & 1 = %1　→　二进制第 %2 位").arg(bit).arg(bitIndex)});
        if (bit == 1) {
            res = res * a;
            if (m_hasMod) res %= m_mod;
            m_frames.push_back({ActionType::FP_MUL, bitIndex, 0, static_cast<int>(res), static_cast<int>(a), {},
                                QString("该位为 1，res = res × a = %1").arg(res),
                                QString("res = res × a = %1%2").arg(res).arg(modSuffix)});
        }
        long long squared = a * a;
        if (m_hasMod) squared %= m_mod;
        m_frames.push_back({ActionType::FP_SQUARE, bitIndex, 0, static_cast<int>(squared), 0, {},
                            QString("底数自乘：a = a × a = %1").arg(squared),
                            QString("a = a × a = %1%2").arg(squared).arg(modSuffix)});
        a = squared;
        b >>= 1;
        m_frames.push_back({ActionType::FP_ADVANCE, bitIndex, 0, static_cast<int>(b), static_cast<int>(a), {},
                            QString("指数折半：b = b / 2 = %1").arg(b),
                            QString("b = b >> 1 = %1　a = %2").arg(b).arg(a)});
        ++bitIndex;
    }

    m_frames.push_back({ActionType::FP_RESULT, 0, 1, static_cast<int>(res), 0, {},
                        QString("%1 ^ %2%3 = %4").arg(m_base).arg(m_exp).arg(modSuffix).arg(res),
                        QString("最终结果 = %1").arg(res)});
    return m_frames;
}

void FastPowModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    const double bitCell = 46.0;
    const double bitGap = 10.0;
    const double bitBaseX = leftXBitOrigin();

    if (frame.type == ActionType::FP_RESET) {
        applyBase(m_base);
        applyExp(m_exp);
        applyRes(1);
        for (size_t i = 0; i < m_bitBlocks.size(); ++i) {
            m_bitBlocks[i]->color = kFpPale;
            m_bitBlocks[i]->setCustomValue("");
            m_bitBlocks[i]->showValue = false;
            m_bitBlocks[i]->update();
        }
        if (m_stepText) m_stepText->setPlainText("等待取位");
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_ptrK) m_ptrK->setOpacity(0);
    } else if (frame.type == ActionType::FP_BIT) {
        int index = frame.u;
        for (size_t i = 0; i < m_bitBlocks.size(); ++i) {
            if (static_cast<int>(i) == index) continue;
            if (m_bitBlocks[i]->showValue) continue;
            m_bitBlocks[i]->color = kFpPale;
            m_bitBlocks[i]->update();
        }
        if (index >= 0 && index < static_cast<int>(m_bitBlocks.size())) {
            ArrayBlock* block = m_bitBlocks[index];
            block->setCustomValue(QString::number(frame.val1));
            block->showValue = true;
            block->color = frame.val1 == 1 ? kFpHit : kFpBit;
            block->update();
            if (m_animated) playScalePulse(block, 1.24, 260);
        }
        if (m_ptrK) {
            m_ptrK->setOpacity(1);
            m_ptrK->setPos(bitBaseX + index * (bitCell + bitGap) + bitCell / 2.0, 452);
        }
        if (m_ptrB && m_expBlock) {
            m_ptrB->setOpacity(1);
            m_ptrB->setPos(m_expBlock->pos().x() + m_expBlock->cellWidth() / 2.0, 300);
        }
        if (m_stepText) {
            m_stepText->setPlainText(QString("b %% 2 = %1　→　第 %2 位").arg(frame.val1).arg(index));
        }
    } else if (frame.type == ActionType::FP_MUL) {
        applyRes(frame.val1);
        if (m_animated) playScalePulse(m_resBlock, 1.26, 300);
        if (m_stepText) {
            m_stepText->setPlainText(QString("res = res × a = %1").arg(frame.val1));
        }
    } else if (frame.type == ActionType::FP_SQUARE) {
        applyBase(frame.val1);
        if (m_animated) playScalePulse(m_baseBlock, 1.2, 280);
        if (m_stepText) {
            m_stepText->setPlainText(QString("a = a × a = %1").arg(frame.val1));
        }
    } else if (frame.type == ActionType::FP_ADVANCE) {
        applyExp(frame.val1);
        if (m_animated) playScalePulse(m_expBlock, 1.18, 260);
        if (m_stepText) {
            m_stepText->setPlainText(QString("b = b / 2 = %1　a = %2").arg(frame.val1).arg(frame.val2));
        }
    } else if (frame.type == ActionType::FP_RESULT) {
        applyRes(frame.val1);
        if (m_animated) playScalePulse(m_resBlock, 1.3, 340);
        if (m_stepText) {
            m_stepText->setPlainText(QString("最终结果 = %1").arg(frame.val1));
        }
    }
}

