        : QString("输入格式：a b（精确值）或 a b p（取模）");
    m_mathText = scene->addText(title);
    m_mathText->setFont(QFont("Consolas", 14, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(60, 18);
    if (!m_valid) return;

    layoutPanels();

    int bitCount = 0;
    long long tmp = m_exp;
    while (tmp > 0) {
        ++bitCount;
        tmp >>= 1;
    }
    m_bitCount = bitCount;

    m_bitTitle = m_scene->addText("指数 b 的二进制位（最右为第 0 位）");
    m_bitTitle->setFont(QFont("Microsoft YaHei", 11, QFont::Bold));
    m_bitTitle->setDefaultTextColor(QColor(60, 75, 95));
    m_bitTitle->setPos(kFpLeftX, 452);

    for (int i = 0; i < bitCount; ++i) {
        ArrayBlock* block = new ArrayBlock(10 + i, 0, QString::number(i));
        block->setCellSize(kFpBitCell, 42);
        block->setPos(bitCellX(i), 500);
        block->color = kFpPale;
        block->showValue = false;
        m_scene->addItem(block);
        m_bitBlocks.push_back(block);
    }

    m_ptrB = new PointerBlock("b", QColor(210, 80, 55));
    m_ptrB->setOpacity(0);
    m_scene->addItem(m_ptrB);

    m_ptrK = new PointerBlock("k", QColor(45, 130, 210));
    m_ptrK->setOpacity(0);
    m_scene->addItem(m_ptrK);
}

double FastPowModule::bitCellX(int bitIndex) const {
    int count = std::max(1, m_bitCount);
    int column = count - 1 - bitIndex;
    return kFpLeftX + column * (kFpBitCell + kFpBitGap);
}

void FastPowModule::applyBase(long long value) {
    if (!m_baseBlock) return;
    m_baseBlock->customValue = QString::number(value);
    m_baseBlock->showValue = true;
    m_baseBlock->update();
}

void FastPowModule::applyExp(long long value) {
    if (!m_expBlock) return;
    m_expBlock->customValue = QString::number(value);
    m_expBlock->showValue = true;
    m_expBlock->update();
}

void FastPowModule::applyRes(long long value) {
    if (!m_resBlock) return;
    m_resBlock->customValue = QString::number(value);
    m_resBlock->showValue = true;
    m_resBlock->update();
}

std::vector<AnimFrame> FastPowModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;
    m_base = liveValue("a", 0, static_cast<int>(m_base));
    m_exp = liveValue("b", 0, static_cast<int>(m_exp));
    if (m_hasMod) m_mod = liveValue("p", 0, static_cast<int>(m_mod));

    const QString modSuffix = m_hasMod ? QString(" mod %1").arg(m_mod) : QString();

    m_frames.push_back({ActionType::FP_RESET, 0, 0, static_cast<int>(m_base), static_cast<int>(m_exp), {},
                        QString("初始化：a = %1，b = %2，res = 1").arg(m_base).arg(m_exp),
                        QString("a = %1　b = %2　res = 1%3").arg(m_base).arg(m_exp).arg(modSuffix)});

    long long res = 1;
    long long a = m_base;
    long long b = m_exp;
    int bitIndex = 0;

    while (b > 0) {
        long long bit = b & 1LL;
        m_frames.push_back({ActionType::FP_BIT, bitIndex, static_cast<int>(bit), static_cast<int>(bit), static_cast<int>(b), {},
                            QString("b %% 2 = %1，写入二进制第 %2 位").arg(bit).arg(bitIndex),
                            QString("b %% 2 = %1　→　第 %2 位").arg(bit).arg(bitIndex)});
        if (bit == 1) {
            res = res * a;
            if (m_hasMod) res %= m_mod;
            m_frames.push_back({ActionType::FP_MUL, bitIndex, 0, static_cast<int>(res), static_cast<int>(a), {},
                                QString("该位为 1，res = res × a = %1").arg(res),
                                QString("res = res × a = %1%2").arg(res).arg(modSuffix)});
        }
        long long squared = a * a;
        if (m_hasMod) squared %= m_mod;
        a = squared;
        b >>= 1;
        m_frames.push_back({ActionType::FP_ADVANCE, bitIndex, 0, static_cast<int>(b), static_cast<int>(a), {},
                            QString("底数自乘 a = a × a = %1，指数折半 b = b / 2 = %2").arg(a).arg(b),
                            QString("a = a × a = %1　b = b >> 1 = %2").arg(a).arg(b)});
        ++bitIndex;
    }

    m_frames.push_back({ActionType::FP_RESULT, 0, 1, static_cast<int>(res), 0, {},
                        QString("%1 ^ %2%3 = %4").arg(m_base).arg(m_exp).arg(modSuffix).arg(res),
                        QString("最终结果 = %1").arg(res)});
    return m_frames;
}

void FastPowModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::FP_RESET) {
        applyBase(m_base);
        applyExp(m_exp);
        applyRes(1);
        for (size_t i = 0; i < m_bitBlocks.size(); ++i) {
            m_bitBlocks[i]->color = kFpPale;
            m_bitBlocks[i]->setCustomValue("");
            m_bitBlocks[i]->showValue = false;
            m_bitBlocks[i]->update();
        }
        if (m_stepText) m_stepText->setPlainText("等待取位");
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_ptrK) m_ptrK->setOpacity(0);
    } else if (frame.type == ActionType::FP_BIT) {
        int index = frame.u;
        if (index >= 0 && index < static_cast<int>(m_bitBlocks.size())) {
            ArrayBlock* block = m_bitBlocks[index];
            block->setCustomValue(QString::number(frame.val1));
            block->showValue = true;
            block->color = frame.val1 == 1 ? kFpHit : kFpBit;
            block->update();
            if (m_animated) playScalePulse(block, 1.24, 260);
        }
        if (m_ptrK) {
            m_ptrK->setOpacity(1);
            m_ptrK->setPos(bitCellX(index) + kFpBitCell / 2.0, 476);
        }
        if (m_ptrB && m_expBlock) {
            m_ptrB->setOpacity(1);
            m_ptrB->setPos(m_expBlock->pos().x() + m_expBlock->cellWidth() / 2.0, 290);
        }
        if (m_stepText) {
            m_stepText->setPlainText(QString("b %% 2 = %1　→　第 %2 位").arg(frame.val1).arg(index));
        }
    } else if (frame.type == ActionType::FP_MUL) {
        applyRes(frame.val1);
        if (m_animated) playScalePulse(m_resBlock, 1.26, 300);
        if (m_stepText) {
            m_stepText->setPlainText(QString("res = res × a = %1").arg(frame.val1));
        }
    } else if (frame.type == ActionType::FP_ADVANCE) {
        applyBase(frame.val2);
        applyExp(frame.val1);
        if (m_animated) {
            playScalePulse(m_baseBlock, 1.18, 260);
            playScalePulse(m_expBlock, 1.18, 260);
        }
        if (m_stepText) {
            m_stepText->setPlainText(QString("a = a × a = %1　b = b >> 1 = %2").arg(frame.val2).arg(frame.val1));
        }
    } else if (frame.type == ActionType::FP_RESULT) {
        applyRes(frame.val1);
        if (m_animated) playScalePulse(m_resBlock, 1.3, 340);
        if (m_stepText) {
            m_stepText->setPlainText(QString("最终结果 = %1").arg(frame.val1));
        }
    }
}

