void PointerBlock::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    painter->setRenderHint(QPainter::Antialiasing);
    painter->setPen(QPen(color, 3, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
    double w = labelWidth();
    if (m_horizontal) {
        painter->drawLine(-26, 0, 0, 0);
        painter->drawLine(0, 0, -9, -7);
        painter->drawLine(0, 0, -9, 7);
        QFont f("Consolas", 14, QFont::Bold);
        painter->setFont(f);
        painter->drawText(QRectF(-w - 46, -10, w, 20), Qt::AlignCenter, label);
        return;
    }
    painter->drawLine(0, 25, 0, 3);
    painter->drawLine(0, 3, -7, 13);
    painter->drawLine(0, 3, 7, 13);
    QFont f("Consolas", 14, QFont::Bold);
    painter->setFont(f);
    painter->drawText(QRectF(-w / 2.0, 25, w, 20), Qt::AlignCenter, label);
}

void PointerBlock::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    painter->setRenderHint(QPainter::Antialiasing);
    painter->setPen(QPen(color, 3, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
    double w = labelWidth();
    QFont f("Consolas", 14, QFont::Bold);
    painter->setFont(f);
    if (m_direction == Left || m_direction == Right) {
        double sign = (m_direction == Right) ? 1.0 : -1.0;
        painter->drawLine(-26 * sign, 0, 0, 0);
        painter->drawLine(0, 0, -9 * sign, -7);
        painter->drawLine(0, 0, -9 * sign, 7);
        painter->drawText(QRectF(-w - 46, -10, w, 20), Qt::AlignCenter, label);
        return;
    }
    if (m_direction == Down) {
        painter->drawLine(0, 0, 0, 22);
        painter->drawLine(0, 22, -7, 12);
        painter->drawLine(0, 22, 7, 12);
        painter->drawText(QRectF(-w / 2.0, 26, w, 20), Qt::AlignCenter, label);
        return;
    }
    painter->drawLine(0, 25, 0, 3);
    painter->drawLine(0, 3, -7, 13);
    painter->drawLine(0, 3, 7, 13);
    painter->drawText(QRectF(-w / 2.0, 25, w, 20), Qt::AlignCenter, label);
}

QRectF PointerBlock::boundingRect() const {
    double w = labelWidth();
    if (m_direction == Left || m_direction == Right) {
        return QRectF(-w - 46, -16, w + 46, 32);
    }
    return QRectF(-w / 2.0, 0, w, 47);
}

QRectF PointerBlock::boundingRect() const {
    double w = labelWidth();
    if (m_direction == Left || m_direction == Right) {
        return QRectF(-w - 46, -16, w + 46, 32);
    }
    if (m_direction == Down) {
        return QRectF(-w / 2.0, 0, w, 47);
    }
    return QRectF(-w / 2.0, 0, w, 47);
}

