                   b->id, qPrintable(b->labelText()), qPrintable(b->displayText()),
                   (int)b->showValue, b->pos().x(), b->pos().y(),
                   b->cellWidth(), b->cellHeight());
            continue;
        }
        QGraphicsTextItem* t = qgraphicsitem_cast<QGraphicsTextItem*>(item);
        if (t) printf("text '%s' at (%.0f,%.0f)\n", qPrintable(t->toPlainText()), t->pos().x(), t->pos().y());
    }
    printf("sceneRect = %.0f %.0f %.0f %.0f\n", scene.sceneRect().x(), scene.sceneRect().y(),
           scene.sceneRect().width(), scene.sceneRect().height());
    return 0;
}

