}

std::vector<AnimFrame> FastPowModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;
    m_base = liveValue("a", 0, static_cast<int>(m_base));
    m_exp = liveValue("b", 0, static_cast<int>(m_exp));
    if (m_hasMod) m_mod = liveValue("p", 0, static_cast<int>(m_mod));

    const QString modSuffix = m_hasMod ? QString(" mod %1").arg(m_mod) : QString();

    AnimFrame reset;
    reset.type = ActionType::FP_RESET;
    reset.u = 0;
    reset.v = 0;
    reset.val1 = 0;
    reset.val2 = 0;
    reset.big1 = m_base;
    reset.big2 = m_exp;
    reset.explanation = QString("初始化：a = %1，b = %2，res = 1").arg(m_base).arg(m_exp);
    reset.mathText = QString("a = %1　b = %2　res = 1%3").arg(m_base).arg(m_exp).arg(modSuffix);
    m_frames.push_back(reset);

    long long res = 1;
    long long a = m_base;
    long long b = m_exp;
    int bitIndex = 0;

    while (b > 0) {
        long long bit = b & 1LL;
        long long squared = a * a;
        if (m_hasMod) squared %= m_mod;
        long long nextB = b >> 1;

        AnimFrame frame;
        frame.type = ActionType::FP_BIT;
        frame.u = bitIndex;
        frame.v = static_cast<int>(bit);
        frame.val1 = static_cast<int>(bit);
        frame.val2 = static_cast<int>(b);
        frame.big1 = a;
        frame.big2 = b;
        frame.big3 = squared;
        frame.explanation = QString("b %% 2 = %1，写入第 %2 位；随后 a = a×a = %3，b = b>>1 = %4")
            .arg(bit).arg(bitIndex).arg(squared).arg(nextB);
        frame.mathText = QString("b %% 2 = %1　→　第 %2 位　　a = %3　b = %4")
            .arg(bit).arg(bitIndex).arg(squared).arg(nextB);
        m_frames.push_back(frame);

        if (bit == 1) {
            res = res * a;
            if (m_hasMod) res %= m_mod;
            AnimFrame mul;
            mul.type = ActionType::FP_MUL;
            mul.u = bitIndex;
            mul.v = 0;
            mul.val1 = 0;
            mul.val2 = 0;
            mul.big1 = res;
            mul.big2 = a;
            mul.explanation = QString("该位为 1，res = res × a = %1").arg(res);
            mul.mathText = QString("res = res × a = %1%2").arg(res).arg(modSuffix);
            m_frames.push_back(mul);
        }

        a = squared;
        b = nextB;
        ++bitIndex;
    }

    AnimFrame result;
    result.type = ActionType::FP_RESULT;
    result.u = 0;
    result.v = 1;
    result.val1 = 0;
    result.val2 = 0;
    result.big1 = res;
    result.explanation = QString("%1 ^ %2%3 = %4").arg(m_base).arg(m_exp).arg(modSuffix).arg(res);
    result.mathText = QString("最终结果 = %1").arg(res);
    m_frames.push_back(result);
    return m_frames;
}

void FastPowModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::FP_RESET) {
        applyBase(frame.big1);
        applyExp(frame.big2);
        applyRes(1);
        for (size_t i = 0; i < m_bitBlocks.size(); ++i) {
            m_bitBlocks[i]->color = kFpPale;
            m_bitBlocks[i]->setCustomValue("");
            m_bitBlocks[i]->showValue = false;
            m_bitBlocks[i]->update();
        }
        if (m_stepText) m_stepText->setPlainText("等待取位");
        if (m_ptrK) m_ptrK->setOpacity(0);
    } else if (frame.type == ActionType::FP_BIT) {
        int index = frame.u;
        if (index >= 0 && index < static_cast<int>(m_bitBlocks.size())) {
            ArrayBlock* block = m_bitBlocks[index];
            block->setCustomValue(QString::number(frame.val1));
            block->showValue = true;
            block->color = frame.val1 == 1 ? kFpHit : kFpBit;
            block->update();
            if (m_animated) playScalePulse(block, 1.24, 260);
        }
        applyBase(frame.big3);
        applyExp(frame.big3 == 0 ? 0 : frame.big2);
        if (m_animated) {
            playScalePulse(m_baseBlock, 1.16, 240);
            playScalePulse(m_expBlock, 1.16, 240);
        }
        if (m_ptrK) {
            m_ptrK->setOpacity(1);
            m_ptrK->setPos(bitCellX(index) + kFpBitCell / 2.0, 486);
        }
        if (m_stepText) {
            m_stepText->setPlainText(QString("b %% 2 = %1　→　第 %2 位　　a = %3　b = %4")
                .arg(frame.val1).arg(index).arg(frame.big3).arg(frame.big2 >> 1));
        }
    } else if (frame.type == ActionType::FP_MUL) {
        applyRes(frame.big1);
        if (m_animated) playScalePulse(m_resBlock, 1.26, 300);
        if (m_stepText) {
            m_stepText->setPlainText(QString("res = res × a = %1").arg(frame.big1));
        }
    } else if (frame.type == ActionType::FP_RESULT) {
        applyRes(frame.big1);
        if (m_animated) playScalePulse(m_resBlock, 1.3, 340);
        if (m_stepText) {
            m_stepText->setPlainText(QString("最终结果 = %1").arg(frame.big1));
        }
    }
}

void FastPowModule::onLiveDataChanged(const QString& row, int index, int value) {
    Q_UNUSED(index);
    if (row == "a") m_base = value;
    if (row == "b") m_exp = value;
    if (row == "p" && m_hasMod) m_mod = value;
}

void FastPowModule::reset() {
    m_frames.clear();
    m_bitBlocks.clear();
    m_baseBlock = nullptr;
    m_resBlock = nullptr;
    m_expBlock = nullptr;
    m_mathText = nullptr;
    m_bitTitle = nullptr;
    m_stepText = nullptr;
    m_ptrK = nullptr;
    m_data.clear();
    m_base = 0;
    m_exp = 0;
    m_mod = 0;
    m_hasMod = false;
    m_bitCount = 0;
    m_valid = false;
}

