static int g_fail = 0;

static void check(const char* name, bool ok) {
    printf("[%s] %s\n", ok ? "PASS" : "FAIL", name);
    if (!ok) g_fail++;
}

struct Box {
    QRectF rect;
    QString tag;
};

static QRectF itemSceneRect(QGraphicsItem* item) {
    if (auto* t = qgraphicsitem_cast<QGraphicsTextItem*>(item)) {
        const QPointF p = t->scenePos();
        const QRectF br = t->boundingRect();
        QRectF r(br);
        r.moveTopLeft(p + br.topLeft());
        return r;
    }
    if (auto* b = qgraphicsitem_cast<ArrayBlock*>(item)) {
        return b->mapRectToScene(b->boundingRect());
    }
    if (auto* p = qgraphicsitem_cast<PointerBlock*>(item)) {
        return p->mapRectToScene(p->boundingRect());
    }
    if (auto* n = qgraphicsitem_cast<GraphNode*>(item)) {
        return n->mapRectToScene(n->boundingRect());
    }
    return item->mapRectToScene(item->boundingRect());
}

static bool overlaps(const QRectF& a, const QRectF& b, double margin) {
    return a.adjusted(margin, margin, margin, margin).intersects(b);
}

static void auditScene(const char* label, QGraphicsScene& scene) {
    std::vector<Box> boxes;
    for (auto* item : scene.items()) {
        if (qgraphicsitem_cast<QGraphicsLineItem*>(item)) continue;
        if (qgraphicsitem_cast<LinkLine*>(item)) continue;
        if (qgraphicsitem_cast<QGraphicsPolygonItem*>(item)) continue;
        QString tag = QString::number(item->type());
        if (auto* t = qgraphicsitem_cast<QGraphicsTextItem*>(item)) tag = t->toPlainText().left(18);
        else if (auto* b = qgraphicsitem_cast<ArrayBlock*>(item)) tag = QString("cell:%1").arg(b->displayText());
        else if (auto* p = qgraphicsitem_cast<PointerBlock*>(item)) tag = QString("ptr:%1").arg(p->label);
        boxes.push_back({itemSceneRect(item), tag});
    }
    int conflicts = 0;
    for (size_t i = 0; i < boxes.size(); ++i) {
        for (size_t j = i + 1; j < boxes.size(); ++j) {
            if (boxes[i].tag.isEmpty() || boxes[j].tag.isEmpty()) continue;
            if (!overlaps(boxes[i].rect, boxes[j].rect, 1.0)) continue;
            ++conflicts;
            printf("  [%s] OVERLAP '%s' <-> '%s'  (%.0f,%.0f %.0fx%.0f)\n", label,
                   qPrintable(boxes[i].tag), qPrintable(boxes[j].tag),
                   boxes[i].rect.x(), boxes[i].rect.y(),
                   boxes[i].rect.width(), boxes[i].rect.height());
        }
    }
    printf("  [%s] items=%zu conflicts=%d\n", label, boxes.size(), conflicts);
    check(label, conflicts == 0);
}

