        m.buildLayout(&scene, m.getDefaultInput());
        for (auto& f : m.runAlgorithm()) m.renderFrame(f);
        auditScene("forwardstar: no text/pointer overlap", scene);
    }

    {
        QGraphicsScene scene;
        HeapAdjustModule m;
        m.m_animated = false;
        m.buildLayout(&scene, m.getDefaultInput());
        for (auto& f : m.runAlgorithm()) m.renderFrame(f);
        auditScene("heap: no text/pointer overlap", scene);
    }

    {
        QGraphicsScene scene;
        BubbleSortModule m;
        m.m_animated = false;
        m.buildLayout(&scene, m.getDefaultInput());
        for (auto& f : m.runAlgorithm()) m.renderFrame(f);
