static int g_fail = 0;

static void check(const char* name, bool ok) {
    printf("[%s] %s\n", ok ? "PASS" : "FAIL", name);
    if (!ok) g_fail++;
}

struct Box {
    QRectF rect;
    QString tag;
};

static QRectF textSceneRect(QGraphicsTextItem* t) {
    QRectF br = t->boundingRect();
    br.moveTopLeft(t->scenePos() + br.topLeft());
    return br;
}

static void collect(QGraphicsItem* item, std::vector<Box>& out) {
    if (auto* t = qgraphicsitem_cast<QGraphicsTextItem*>(item)) {
        const QString s = t->toPlainText().trimmed();
        if (s.isEmpty()) return;
        out.push_back({textSceneRect(t), s.left(16)});
        return;
    }
    if (auto* b = qgraphicsitem_cast<ArrayBlock*>(item)) {
        const QRectF cell = b->mapRectToScene(QRectF(0, 0, b->cellWidth(), b->cellHeight()));
        out.push_back({cell, QString("cell:%1").arg(b->displayText())});
        if (b->showLabel()) {
            const QRectF lab = b->mapRectToScene(QRectF(0, -25, b->cellWidth(), 20));
            out.push_back({lab, QString("idx:%1").arg(b->displayText())});
        }
        return;
    }
    if (auto* p = qgraphicsitem_cast<PointerBlock*>(item)) {
        out.push_back({p->mapRectToScene(p->boundingRect()), QString("ptr:%1").arg(p->label)});
        return;
    }
    if (auto* n = qgraphicsitem_cast<GraphNode*>(item)) {
        out.push_back({n->mapRectToScene(n->boundingRect()), QString("node:%1").arg(n->id)});
        return;
    }
}

static double overlapArea(const QRectF& a, const QRectF& b) {
    const QRectF r = a.intersected(b);
    if (r.isEmpty()) return 0.0;
    return r.width() * r.height();
}

static void auditScene(const char* label, QGraphicsScene& scene, double minArea = 6.0) {
    std::vector<Box> boxes;
    for (auto* item : scene.items()) {
        if (qgraphicsitem_cast<QGraphicsLineItem*>(item)) continue;
        if (qgraphicsitem_cast<LinkLine*>(item)) continue;
        if (qgraphicsitem_cast<QGraphicsPolygonItem*>(item)) continue;
        if (qgraphicsitem_cast<GraphEdge*>(item)) continue;
        collect(item, boxes);
    }
    int conflicts = 0;
    for (size_t i = 0; i < boxes.size(); ++i) {
        for (size_t j = i + 1; j < boxes.size(); ++j) {
            const double area = overlapArea(boxes[i].rect, boxes[j].rect);
            if (area < minArea) continue;
            ++conflicts;
            printf("  [%s] OVERLAP '%s' <-> '%s' area=%.0f  (%.0f,%.0f %.0fx%.0f)\n", label,
                   qPrintable(boxes[i].tag), qPrintable(boxes[j].tag), area,
                   boxes[i].rect.x(), boxes[i].rect.y(),
                   boxes[i].rect.width(), boxes[i].rect.height());
        }
    }
    printf("  [%s] items=%zu conflicts=%d\n", label, boxes.size(), conflicts);
    check(label, conflicts == 0);
}

