static void collect(QGraphicsItem* item, std::vector<Box>& out) {
    if (auto* t = qgraphicsitem_cast<QGraphicsTextItem*>(item)) {
        const QString s = t->toPlainText().trimmed();
        if (s.isEmpty()) return;
        out.push_back({t->sceneBoundingRect(), s.left(18), KindLabel});
        return;
    }
    if (auto* b = qgraphicsitem_cast<ArrayBlock*>(item)) {
        const QRectF cell = b->mapRectToScene(QRectF(0, 0, b->cellWidth(), b->cellHeight()));
        out.push_back({cell, QString("cell:%1").arg(b->displayText()), KindCell});
        if (b->showLabel) {
            const QRectF lab = b->mapRectToScene(QRectF(0, -25, b->cellWidth(), 20));
            out.push_back({lab, QString("idx:%1").arg(b->displayText()), KindCellIndex});
        }
        return;
    }
    if (auto* p = qgraphicsitem_cast<PointerBlock*>(item)) {
        out.push_back({p->mapRectToScene(p->boundingRect()), QString("ptr:%1").arg(p->label), KindPointer});
        return;
    }
    if (auto* n = qgraphicsitem_cast<GraphNode*>(item)) {
        out.push_back({n->mapRectToScene(n->boundingRect()), QString("node:%1").arg(n->id), KindNode});
    }
}

