void ComboOption::paintTile(QPainter& painter, const QRectF& box) {
    const QColor accent = m_accent;
    const qreal hp = m_hoverProgress;
    const qreal pp = m_pressProgress;

    const double radius = 11.0 - 1.2 * pp;
    const double inset = 1.4 * pp;
    QRectF r = box.adjusted(inset, inset, -inset, -inset);

    QPainterPath path;
    path.addRoundedRect(r, radius, radius);

    QLinearGradient grad(r.topLeft(), r.bottomLeft());
    if (m_selected) {
        const QColor top = QColor::fromRgbF(
            qBound(0.0, accent.redF() + 0.28 * (1.0 - accent.redF()), 1.0),
            qBound(0.0, accent.greenF() + 0.28 * (1.0 - accent.greenF()), 1.0),
            qBound(0.0, accent.blueF() + 0.28 * (1.0 - accent.blueF()), 1.0));
        const QColor bottom = accent.lighter(126);
        grad.setColorAt(0.0, top);
        grad.setColorAt(1.0, bottom);
    } else {
        const QColor baseTop = QColor(250, 252, 255);
        const QColor baseBottom = QColor(238, 244, 252);
        const QColor hovTop = QColor(255, 255, 255);
        const QColor hovBottom = accent.lighter(158);
        grad.setColorAt(0.0, mixColor(baseTop, hovTop, hp));
        grad.setColorAt(1.0, mixColor(baseBottom, hovBottom, hp));
    }
    painter.setBrush(grad);

    if (m_selected) {
        painter.setPen(QPen(accent.darker(112), 1.5));
    } else {
        const QColor idle = QColor(214, 224, 240);
        const QColor hot = accent.lighter(146);
        painter.setPen(QPen(mixColor(idle, hot, hp), 1.0 + 0.5 * hp));
    }
    painter.drawPath(path);

    if (hp > 0.01 && !m_selected) {
        painter.save();
        painter.setClipPath(path);
        painter.setPen(Qt::NoPen);
        const QColor glow = QColor(accent.red(), accent.green(), accent.blue(),
                                  static_cast<int>(64 * hp));
        painter.setBrush(glow);
        const double sweep = r.height() * 0.55;
        const double top = r.top() - sweep + (r.height() + sweep) * hp;
        painter.drawRoundedRect(QRectF(r.left() - 1, top, r.width() + 2, sweep), radius, radius);
        painter.restore();
    }

    if (m_selected || hp > 0.01) {
        painter.save();
        painter.setClipPath(path);
        painter.setPen(Qt::NoPen);
        painter.setBrush(QColor(255, 255, 255, m_selected ? 130 : static_cast<int>(90 * hp)));
        painter.drawRoundedRect(QRectF(r.left() + 1.0, r.top() + 1.0, r.width() - 2.0, r.height() * 0.42),
                                radius, radius);
        painter.restore();
    }

    const double barX = r.left() + 1.4;
    const double barTop = r.top() + (m_selected ? 8.0 : 8.0 + 4.0 * (1.0 - hp));
    const double barH = r.height() - (m_selected ? 16.0 : 16.0 + 8.0 * (1.0 - hp));
    if (m_selected || hp > 0.02) {
        painter.setPen(Qt::NoPen);
        painter.setBrush(QColor(accent.red(), accent.green(), accent.blue(),
                               m_selected ? 235 : static_cast<int>(180 * hp)));
        painter.drawRoundedRect(QRectF(barX, barTop, 3.0, barH), 1.5, 1.5);
    }

    QColor textColor;
    if (m_selected) {
        textColor = accent.darker(152);
    } else {
        textColor = mixColor(UiTheme::textSecondary(), UiTheme::textPrimary(), hp);
    }
    painter.setFont(font());
    painter.setPen(textColor);
    QRectF textRect = r.adjusted(m_selected ? 10.0 : 8.0, 0, -8.0, 0);
    if (pp > 0.01) {
        QFontMetrics fm(font());
        const double dy = fm.height() * 0.5 * pp;
        textRect.translate(0, dy);
    }
    painter.drawText(textRect, Qt::AlignVCenter | Qt::AlignHCenter, m_text);
}

