    QPointer<QWidget> popup = m_popup;
    m_popup = nullptr;
    m_popupLayout = nullptr;
    m_options.clear();
    m_popupWidgets.clear();
    if (!popup) return;
    popup->close();
    popup->deleteLater();
}

