void ComboCard::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    const QRectF box = QRectF(rect()).adjusted(0.5, 0.5, -0.5, -0.5);

    QPainterPath path;
    if (m_style == ComboVisualStyle::SoftGlass) {
        path.addRoundedRect(box, 18.0, 18.0);
        QRadialGradient glow(box.topLeft(), qMax(box.width(), box.height()));
        glow.setColorAt(0.0, QColor(255, 255, 255, 246));
        glow.setColorAt(1.0, QColor(238, 243, 251, 236));
        painter.setBrush(glow);
        painter.setPen(QPen(QColor(255, 255, 255, 170), 1.0));
    } else if (m_style == ComboVisualStyle::MinimalLine) {
        path.addRoundedRect(box, 12.0, 12.0);
        painter.setBrush(QColor(252, 253, 255, 250));
        painter.setPen(QPen(QColor(226, 232, 241), 1.0));
    } else {
        path.addRoundedRect(box, 16.0, 16.0);
        QLinearGradient grad(box.topLeft(), box.bottomLeft());
        grad.setColorAt(0.0, QColor(255, 255, 255, 255));
        grad.setColorAt(1.0, QColor(249, 251, 254, 255));
        painter.setBrush(grad);
        painter.setPen(QPen(QColor(226, 232, 242), 1.0));
    }
    painter.drawPath(path);
}

ComboPopupFrame::ComboPopupFrame(QWidget* parent) : QWidget(parent) {
    setAttribute(Qt::WA_TranslucentBackground, true);
    setAttribute(Qt::WA_NoSystemBackground, true);
}

void ComboPopupFrame::setVisualStyle(ComboVisualStyle style) {
    if (m_style == style) return;
    m_style = style;
    update();
}

void ComboPopupFrame::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setPen(Qt::NoPen);
    if (!m_card) return;
    const QRectF cardRect(m_card->geometry());

    if (m_style == ComboVisualStyle::MinimalLine) {
        painter.setBrush(QColor(15, 28, 48, 16));
        painter.drawRoundedRect(cardRect.adjusted(0, 3, 0, 3), 12.0, 12.0);
        return;
    }
    if (m_style == ComboVisualStyle::SoftGlass) {
        for (int i = 6; i >= 1; --i) {
            const qreal spread = i * 2.2;
            painter.setBrush(QColor(18, 32, 56, 4 + i));
            painter.drawRoundedRect(cardRect.adjusted(-spread, -spread + 4, spread, spread + 4),
                                   18.0 + spread, 18.0 + spread);
        }
        return;
    }
    for (int i = 8; i >= 1; --i) {
        const qreal spread = i * 1.6;
        painter.setBrush(QColor(20, 34, 58, 3 + i));
        painter.drawRoundedRect(cardRect.adjusted(-spread, -spread + 5, spread, spread + 5),
                                16.0 + spread, 16.0 + spread);
    }
}

