static void clickWidget(QWidget* w) {
    QPointF g = w->mapToGlobal(QPoint(w->width() / 2, w->height() / 2));
    QMouseEvent press(QEvent::MouseButtonPress, g, g, Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(w, &press);
    QMouseEvent release(QEvent::MouseButtonRelease, g, g, Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(w, &release);
    QApplication::processEvents();
}

static void pump(int ms) {
    QEventLoop loop;
    QTimer::singleShot(ms, &loop, &QEventLoop::quit);
    loop.exec();
}

static QWidget* findPopup() {
    for (QWidget* w : QApplication::topLevelWidgets()) {
        if (w->isWindow() && w->windowType() == Qt::Popup) return w;
    }
    return nullptr;
}

static void buildCombo(ComboVisualStyle style, const QString& file) {
    MyComboBox combo;
    combo.setVisualStyle(style);
    combo.addItem("请选择...");
    combo.addGroup("排序算法", {"冒泡排序", "选择排序", "插入排序", "希尔排序", "快速排序", "归并排序"});
    combo.addGroup("图论算法", {"广度优先搜索", "拓扑排序", "Dijkstra", "Kruskal", "Tarjan"});
    combo.resize(260, 34);
    combo.move(60, 60);
    combo.show();
    QApplication::processEvents();
    clickWidget(&combo);
    pump(260);
    QWidget* popup = findPopup();
    if (!popup) {
        printf("popup not found for %s\n", file.toStdString().c_str());
        return;
    }
    QPixmap pm = popup->grab();
    pm.save(file);
    printf("saved %s (%dx%d)\n", file.toStdString().c_str(), pm.width(), pm.height());
    popup->close();
    pump(120);
    combo.close();
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    buildCombo(ComboVisualStyle::VueLight, "style_vue_light.png");
    buildCombo(ComboVisualStyle::SoftGlass, "style_soft_glass.png");
    buildCombo(ComboVisualStyle::MinimalLine, "style_minimal_line.png");
    printf("done\n");
    return 0;
}

