static int g_fail = 0;

static void check(const char* name, bool ok) {
    printf("[%s] %s\n", ok ? "PASS" : "FAIL", name);
    if (!ok) g_fail++;
}

static void pump(int ms) {
    QEventLoop loop;
    QTimer::singleShot(ms, &loop, &QEventLoop::quit);
    loop.exec();
}

static void clickWidget(QWidget* w) {
    const QPointF g(w->mapToGlobal(QPoint(w->width() / 2, w->height() / 2)));
    QMouseEvent press(QEvent::MouseButtonPress, g, g, Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(w, &press);
    QMouseEvent release(QEvent::MouseButtonRelease, g, g, Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(w, &release);
    QApplication::processEvents();
}

static void clickSegment(MySegmentedControl* seg, int index) {
    const int count = seg->options().size();
    const qreal w = static_cast<qreal>(seg->width()) / count;
    const QPointF local(w * index + w / 2.0, seg->height() / 2.0);
    const QPointF g = seg->mapToGlobal(local.toPoint());
    QMouseEvent press(QEvent::MouseButtonPress, local, g, Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(seg, &press);
    QMouseEvent release(QEvent::MouseButtonRelease, local, g, Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(seg, &release);
    QApplication::processEvents();
}

