    check("switching to glass updates combo", combo->visualStyle() == ComboVisualStyle::SoftGlass);

    clickSegment(picker, 2);
    pump(150);
    check("switching to minimal updates combo", combo->visualStyle() == ComboVisualStyle::MinimalLine);

    clickSegment(picker, 0);
    pump(150);
    check("switching back to vue updates combo", combo->visualStyle() == ComboVisualStyle::VueLight);

