QString SandboxMatrixModule::moduleSettingsTitle() const {
    return "矩阵设置";
}

QVector<ModuleField> SandboxMatrixModule::moduleSettingsFields() const {
    QVector<ModuleField> fields;
    fields.append(ModuleField::makeSegment("shape", "形态",
                                            {"矩阵", "行列式", "表格"}, m_shapeIndex));
    fields.append(ModuleField::makeInt("rows", "行数", m_rows, 1, 8));
    fields.append(ModuleField::makeInt("cols", "列数", m_cols, 1, 8));
    ModuleField hint = ModuleField::makeText("hint", "说明", "");
    hint.type = ModuleField::TextInput;
    fields.append(ModuleField::makeText("tip", "提示",
                                        "双击画布中的单元格即可就地修改数值"));
    return fields;
}

void SandboxMatrixModule::applyModuleSetting(const QString& key, const ModuleField& field) {
    if (key == "shape") {
        m_shapeIndex = qBound(0, field.intValue, 2);
        applyShape();
    } else if (key == "rows") {
        m_rows = qBound(1, field.intValue, 8);
        applyDimensions();
    } else if (key == "cols") {
        m_cols = qBound(1, field.intValue, 8);
        applyDimensions();
    }
}

void SandboxMatrixModule::applyShape() {
    if (!m_matrix) return;
    MatrixBlock::Shape shape = MatrixBlock::PlainMatrix;
    if (m_shapeIndex == 1) shape = MatrixBlock::Determinant;
    else if (m_shapeIndex == 2) shape = MatrixBlock::BracketedTable;
    m_matrix->setShape(shape);
    if (shape == MatrixBlock::Determinant) {
        m_matrix->cellColor = QColor(252, 248, 238);
        m_matrix->gridColor = QColor(196, 168, 120);
    } else if (shape == MatrixBlock::BracketedTable) {
        m_matrix->cellColor = QColor(255, 255, 255);
        m_matrix->gridColor = QColor(150, 162, 180);
    } else {
        m_matrix->cellColor = QColor(255, 255, 255);
        m_matrix->gridColor = QColor(150, 162, 180);
    }
    m_matrix->update();
}

void SandboxMatrixModule::applyDimensions() {
    if (!m_matrix) return;
    const QStringList lines = QStringList();
    Q_UNUSED(lines);
    const int oldRows = m_matrix->rows;
    const int oldCols = m_matrix->cols;
    QVector<QVector<QString>> oldData = m_matrix->data;
    m_matrix->rows = m_rows;
    m_matrix->cols = m_cols;
    m_matrix->data.resize(m_rows);
    for (int i = 0; i < m_rows; ++i) {
        m_matrix->data[i].resize(m_cols);
        for (int j = 0; j < m_cols; ++j) {
            if (i < oldRows && j < oldCols) {
                m_matrix->data[i][j] = oldData[i][j];
            } else {
                m_matrix->data[i][j] = QString::number(i * m_cols + j + 1);
            }
        }
    }
    m_matrix->prepareGeometryChange();
    m_matrix->update();
}

void SandboxMatrixModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    std::vector<QPair<QString, QString>> kv;
    parseKeyValues(inputData, kv);
    int rows = 3;
    int cols = 3;
    bool determinant = false;
    for (const auto& pair : kv) {
        if (pair.first == "rows") rows = pair.second.toInt();
        else if (pair.first == "cols") cols = pair.second.toInt();
        else if (pair.first == "type") determinant = (pair.second.trimmed().toLower() == "determinant");
    }
    if (rows < 1 || rows > 8 || cols < 1 || cols > 8) return;
    m_determinant = determinant;
    m_rows = rows;
    m_cols = cols;
    m_shapeIndex = determinant ? 1 : 0;
    rebuildMatrix(rows, cols);

    QStringList lines = inputData.split(QRegularExpression("[\\r\\n]"), Qt::SkipEmptyParts);
    int row = 0;
    for (const QString& line : lines) {
        QStringList tokens = line.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
        if (tokens.isEmpty()) continue;
        bool allNumeric = true;
        for (const QString& t : tokens) {
            bool ok = false;
            t.toInt(&ok);
            if (!ok) { allNumeric = false; break; }
        }
        if (!allNumeric) continue;
        for (int j = 0; j < tokens.size() && j < cols; ++j) {
            if (m_matrix) m_matrix->setCell(row, j, tokens[j]);
        }
        ++row;
        if (row >= rows) break;
    }
}

void SandboxMatrixModule::rebuildMatrix(int rows, int cols) {
    if (!m_scene) return;
    if (m_matrix) {
        m_matrix->setParentItem(nullptr);
        if (m_matrix->scene()) m_matrix->scene()->removeItem(m_matrix);
        delete m_matrix;
        m_matrix = nullptr;
    }
    m_matrix = new MatrixBlock(rows, cols);
    m_matrix->setEditable(true);
    m_matrix->setPos(220, 220);
    m_scene->addItem(m_matrix);
    applyShape();
    connect(m_matrix, &MatrixBlock::cellEdited, this, [this](int row, int col, const QString& text) {
        Q_UNUSED(text);
        m_matrix->setCell(row, col, text);
    });
}

void SandboxMatrixModule::reset() {
    FreeStructureBase::reset();
    m_matrix = nullptr;
    m_determinant = false;
    m_shapeIndex = 0;
    m_rows = 3;
    m_cols = 3;
}

