void SandboxMatrixModule::applyDimensions() {
    if (!m_matrix) return;
    const QStringList lines = QStringList();
    Q_UNUSED(lines);
    const int oldRows = m_matrix->rows;
    const int oldCols = m_matrix->cols;
    QVector<QVector<QString>> oldData = m_matrix->data;
    m_matrix->rows = m_rows;
    m_matrix->cols = m_cols;
    m_matrix->data.resize(m_rows);
    for (int i = 0; i < m_rows; ++i) {
        m_matrix->data[i].resize(m_cols);
        for (int j = 0; j < m_cols; ++j) {
            if (i < oldRows && j < oldCols) {
                m_matrix->data[i][j] = oldData[i][j];
            } else {
                m_matrix->data[i][j] = QString::number(i * m_cols + j + 1);
            }
        }
    }
    m_matrix->prepareGeometryChange();
    m_matrix->update();
}

void SandboxMatrixModule::applyDimensions() {
    if (!m_matrix) return;
    m_matrix->resizeGrid(m_rows, m_cols);
}

