static void doubleClick(QGraphicsScene* scene, const QPointF& scenePos) {
    QGraphicsSceneMouseEvent press(QEvent::MouseButtonPress, scenePos, scenePos,
                                   Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(scene, &press);
    QGraphicsSceneMouseEvent release(QEvent::MouseButtonRelease, scenePos, scenePos,
                                     Qt::LeftButton, Qt::NoButton, Qt::NoModifier);
    QApplication::sendEvent(scene, &release);
    pump(30);
    QGraphicsSceneMouseEvent press2(QEvent::MouseButtonPress, scenePos, scenePos,
                                    Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(scene, &press2);
    QGraphicsSceneMouseEvent dbl(QEvent::MouseButtonDblClick, scenePos, scenePos,
                                 Qt::LeftButton, Qt::LeftButton, Qt::NoModifier);
    QApplication::sendEvent(scene, &dbl);
    QGraphicsSceneMouseEvent release2(QEvent::MouseButtonRelease, scenePos, scenePos,
                                      Qt::LeftButton, Qt::NoButton, Qt::NoModifier);
    QApplication::sendEvent(scene, &release2);
    pump(30);
}

