static void send(QGraphicsScene* scene, QEvent::Type type, const QPointF& p,
                  Qt::MouseButton button, Qt::MouseButtons buttons) {
    QGraphicsSceneMouseEvent ev(type);
    ev.setScenePos(p);
    ev.setPos(p);
    ev.setButton(button);
    ev.setButtons(buttons);
    ev.setModifiers(Qt::NoModifier);
    QApplication::sendEvent(scene, &ev);
}

static void doubleClick(QGraphicsScene* scene, const QPointF& scenePos) {
    send(scene, QEvent::MouseButtonPress, scenePos, Qt::LeftButton, Qt::LeftButton);
    send(scene, QEvent::MouseButtonRelease, scenePos, Qt::LeftButton, Qt::NoButton);
    pump(30);
    send(scene, QEvent::MouseButtonPress, scenePos, Qt::LeftButton, Qt::LeftButton);
    send(scene, QEvent::MouseButtonDblClick, scenePos, Qt::LeftButton, Qt::LeftButton);
    send(scene, QEvent::MouseButtonRelease, scenePos, Qt::LeftButton, Qt::NoButton);
    pump(30);
}

