static void dumpRegion(const QImage& img, const QString& name, int x0, int y0, int w, int h) {
    printf("--- %s region x=%d..%d y=%d..%d ---\n", name.toUtf8().constData(),
           x0, x0 + w, y0, y0 + h);
    for (int y = y0; y < y0 + h; ++y) {
        QString line;
        for (int x = x0; x < x0 + w; ++x) {
            if (x < 0 || y < 0 || x >= img.width() || y >= img.height()) { line += " ."; continue; }
            const QColor c = img.pixelColor(x, y);
            const int sum = c.red() + c.green() + c.blue();
            if (sum < 660) line += " #";
            else if (sum < 720) line += " +";
            else if (sum < 750) line += " -";
            else line += " .";
        }
        printf("%4d %s\n", y, line.toUtf8().constData());
    }
}

