    check(mod.matrixBlock()->cellAt(0, 0) == "1", "value 1");
    check(mod.matrixBlock()->cellAt(0, 2) == "3", "value 3");
    check(mod.matrixBlock()->cellAt(1, 2) == "6", "value 6");

    printf("\n%s  fail=%d\n", g_fail == 0 ? "ALL PASS" : "HAS FAILURE", g_fail);
    return g_fail == 0 ? 0 : 1;
}

