static QImage compositeOnWhite(const QImage& src) {
    QImage out(src.size(), QImage::Format_ARGB32);
    out.fill(Qt::white);
    QPainter p(&out);
    p.drawImage(0, 0, src);
    p.end();
    return out;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    MainWindow w;
    w.resize(1500, 950);
    w.show();
    pump(700);

    MyComboBox* combo = w.findChild<MyComboBox*>();
    clickWidget(combo);
    pump(500);

    QWidget* popup = nullptr;
    for (QWidget* top : QApplication::topLevelWidgets()) {
        if (top->isWindow() && top->windowType() == Qt::Popup && top != combo) { popup = top; break; }
    }
    check("popup opened", popup != nullptr);
    if (!popup) { printf("\nfail=%d\n", g_fail); return 1; }

    ComboCard* card = popup->findChild<ComboCard*>();
    check("card found", card != nullptr);
    if (!card) { printf("\nfail=%d\n", g_fail); return 1; }

    const QRect cardGeom = card->geometry();
    const int frameW = popup->width();
    const int frameH = popup->height();
    printf("frame=%dx%d  card=(%d,%d %dx%d)\n", frameW, frameH,
           cardGeom.x(), cardGeom.y(), cardGeom.width(), cardGeom.height());

    QImage white = compositeOnWhite(popup->grab().toImage());
    white.save("popup_on_white.png");

    const int midY = cardGeom.y() + cardGeom.height() / 2;
    printf("\n--- horizontal profile at y=%d, right margin (card right = %d) ---\n",
           midY, cardGeom.right());
    const int cardRight = cardGeom.x() + cardGeom.width();
    for (int x = cardRight - 4; x < frameW; ++x) {
        const QColor c = white.pixelColor(x, midY);
        const int sum = c.red() + c.green() + c.blue();
        printf("  x=%3d %s sum=%3d %s\n", x, c.name().toUtf8().constData(), sum,
               (sum < 748) ? "<-- not white" : "");
    }

    printf("\n--- vertical profile at x=%d, bottom margin (card bottom = %d) ---\n",
           cardRight - 10, cardGeom.y() + cardGeom.height());
    const int cardBottom = cardGeom.y() + cardGeom.height();
    for (int y = cardBottom - 4; y < frameH; ++y) {
        const QColor c = white.pixelColor(cardRight - 10, y);
        const int sum = c.red() + c.green() + c.blue();
        printf("  y=%3d %s sum=%3d %s\n", y, c.name().toUtf8().constData(), sum,
               (sum < 748) ? "<-- not white" : "");
    }

    int hardLine = 0;
    for (int x = cardRight + 2; x < frameW; ++x) {
        int darker = 0;
        for (int y = cardGeom.y() + 4; y < cardGeom.bottom() - 4; ++y) {
            const QColor c = white.pixelColor(x, y);
            const QColor l = white.pixelColor(x - 2, y);
            if ((l.red() + l.green() + l.blue()) - (c.red() + c.green() + c.blue()) > 12) ++darker;
        }
        if (darker > (cardGeom.height() - 8) * 0.6) {
            printf("HARDPASS vertical line at x=%d (darker=%d of %d)\n", x, darker, cardGeom.height() - 8);
            ++hardLine;
        }
    }
    int hardBottom = 0;
    for (int y = cardBottom + 2; y < frameH; ++y) {
        int darker = 0;
        for (int x = cardGeom.x() + 4; x < cardGeom.right() - 4; ++x) {
            const QColor c = white.pixelColor(x, y);
            const QColor l = white.pixelColor(x, y - 2);
            if ((l.red() + l.green() + l.blue()) - (c.red() + c.green() + c.blue()) > 12) ++darker;
        }
        if (darker > (cardGeom.width() - 8) * 0.6) {
            printf("HARDPASS horizontal line at y=%d (darker=%d of %d)\n", y, darker, cardGeom.width() - 8);
            ++hardBottom;
        }
    }

    check("no hard vertical line outside card", hardLine == 0);
    check("no hard horizontal line outside card", hardBottom == 0);

    popup->close();
    printf("\n%s  fail=%d\n", g_fail == 0 ? "ALL PASS" : "HAS FAILURE", g_fail);
    return g_fail == 0 ? 0 : 1;
}

