    w.show();
    w.raise();
    w.activateWindow();
    pump(900);

    MyComboBox* combo = w.findChild<MyComboBox*>();
    clickWidget(combo);
    pump(700);

    QWidget* popup = nullptr;
    for (QWidget* top : QApplication::topLevelWidgets()) {
        if (top->isWindow() && top->windowType() == Qt::Popup && top != combo) { popup = top; break; }
    }
    if (!popup) { printf("no popup\n"); return 1; }

    const QPoint gp = popup->mapToGlobal(QPoint(0, 0));
    popup->raise();
    pump(300);

    QScreen* screen = popup->screen() ? popup->screen() : QGuiApplication::primaryScreen();
    QImage frame = screen->grabWindow(0).toImage();
    frame.save("verify_screen.png");

    const qreal s = frame.width() / qreal(screen->geometry().width());
    const int px = int(gp.x() * s);
    const int py = int(gp.y() * s);
    const int pw = int(popup->width() * s);
    const int ph = int(popup->height() * s);
    printf("popup logical=(%d,%d %dx%d) physical=(%d,%d %dx%d)\n",
           gp.x(), gp.y(), popup->width(), popup->height(), px, py, pw, ph);

    int bad = 0;
    printf("\n--- right edge scan (looking for hard vertical line) ---\n");
    for (int x = px + pw - 120; x < px + pw + 40; ++x) {
        int darker = 0;
        for (int y = py + 80; y < py + ph - 80; ++y) {
            const QColor c = frame.pixelColor(x, y);
            const QColor l = frame.pixelColor(x - 4, y);
            if ((l.red() + l.green() + l.blue()) - (c.red() + c.green() + c.blue()) > 30) ++darker;
        }
        if (darker > 120) {
            printf("  HARDPASS vertical line x=%d darker=%d\n", x, darker);
            ++bad;
        }
    }
    printf("--- bottom edge scan (looking for hard horizontal line) ---\n");
    for (int y = py + ph - 120; y < py + ph + 40; ++y) {
        int darker = 0;
        for (int x = px + 80; x < px + pw - 80; ++x) {
            const QColor c = frame.pixelColor(x, y);
            const QColor l = frame.pixelColor(x, y - 4);
            if ((l.red() + l.green() + l.blue()) - (c.red() + c.green() + c.blue()) > 30) ++darker;
        }
        if (darker > 120) {
            printf("  HARDPASS horizontal line y=%d darker=%d\n", y, darker);
            ++bad;
        }
    }
    printf("\n%s  bad=%d\n", bad == 0 ? "ALL EDGES CLEAN" : "EDGE ARTIFACT FOUND", bad);
    popup->close();
    return bad == 0 ? 0 : 1;
}

