void ValueBar::setGhost(bool on) {
    if (m_ghost == on) return;
    prepareGeometryChange();
    m_ghost = on;
    update();
}

void ValueBar::setDimmed(bool on) {
    if (m_dimmed == on) return;
    m_dimmed = on;
    update();
}

void ValueBar::setFlip(bool on) {
    if (m_flip == on) return;
    prepareGeometryChange();
    m_flip = on;
