#include <QRegularExpression>
#include <algorithm>
#include "ui/UiFonts.h"

static const QColor kGcA = QColor(130, 180, 235);
static const QColor kGcB = QColor(245, 195, 145);
static const QColor kGcR = QColor(140, 205, 160);

GcdModule::GcdModule() {}

QString GcdModule::getModuleName() const { return "GCD 辗转相除"; }
QString GcdModule::getDefaultInput() const { return "48 18"; }
QString GcdModule::getInputHint() const {
    return "第一行输入两个正整数 a b（均不超过 100000）\n"
           "算法用更相相减：a = a % b，交换 a b，直到 b = 0，此时 a 即为最大公约数";
}

void GcdModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    int a = 0;
    int b = 0;
    if (tokens.size() >= 2) {
        a = tokens[0].toInt(&ok);
        const bool okA = ok && a >= 1 && a <= 100000;
        b = tokens[1].toInt(&ok);
        m_valid = okA && ok && b >= 1 && b <= 100000;
    }

    m_mathText = scene->addText(m_valid ? "GCD：更相相减 a = a % b，直到 b = 0"
                                        : "输入格式：两个正整数 a b");
    m_mathText->setFont(UiFonts::mono(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(150, 18);
    if (!m_valid) return;

    const int maxValue = qMax(a, b);
    const int slotCount = 16;
    m_slotCount = slotCount;

    auto makeTitle = [scene](const QString& text, double x, double y) {
        QGraphicsTextItem* item = scene->addText(text);
        item->setFont(UiFonts::cjk(11, true));
        item->setDefaultTextColor(QColor(60, 75, 95));
        item->setPos(x, y);
        return item;
    };
    m_titleA = makeTitle("a（被除数）", 150, 90);
    m_titleB = makeTitle("b（除数）", 150, 250);
    m_titleR = makeTitle("余数 r = a % b", 150, 410);

    const double barWidth = 320.0;
    for (int i = 0; i < slotCount; ++i) {
        ValueBar* bar = new ValueBar(barWidth);
        bar->setMaxValue(maxValue);
        bar->setPos(150, 115 + i * 62);
        bar->setLabel(i == 0 ? QString("a") : QString("a 第 %1 轮").arg(i));
        bar->setGhost(true);
        scene->addItem(bar);
        m_slots.push_back({bar, QString(), 0, false});
    }

    ValueBar* bBar = new ValueBar(barWidth);
    bBar->setMaxValue(maxValue);
    bBar->setPos(150, 275);
    bBar->setColor(kGcB);
    bBar->setLabel("b");
    bBar->setValue(b);
    scene->addItem(bBar);

    ValueBar* rBar = new ValueBar(barWidth);
    rBar->setMaxValue(maxValue);
    rBar->setPos(150, 435);
    rBar->setColor(kGcR);
    rBar->setLabel("r");
    rBar->setValue(0);
    scene->addItem(rBar);

    m_slots.push_back({bBar, "b", b, false});
    m_slots.push_back({rBar, "r", 0, false});
}

std::vector<AnimFrame> GcdModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    int a = m_slots.empty() ? 0 : static_cast<int>(m_slots[0].value);
    int b = m_slots.size() > m_slotCount ? static_cast<int>(m_slots[m_slotCount].value) : 0;
    m_frames.push_back({ActionType::GC_RESET, a, b, 0, 0, {},
                        QString("初始化：a = %1，b = %2").arg(a).arg(b),
                        QString("a = %1, b = %2").arg(a).arg(b)});

    int round = 0;
    int guard = 0;
    while (b != 0 && round < m_slotCount && guard < 200) {
        ++guard;
        int r = a % b;
        m_frames.push_back({ActionType::GC_DIVIDE, a, b, r, round, {},
                            QString("第 %1 轮：%2 %% %3 = %4").arg(round + 1).arg(a).arg(b).arg(r),
                            QString("%1 %% %2 = %3").arg(a).arg(b).arg(r)});
        m_frames.push_back({ActionType::GC_SWAP, b, r, round, 0, {},
                            QString("令 a = b = %1，b = r = %2").arg(b).arg(r),
                            QString("a = %1, b = %2").arg(b).arg(r)});
        a = b;
        b = r;
        ++round;
    }

    m_frames.push_back({ActionType::GC_DONE, a, b, round, 0, {},
                        QString("b = 0，最大公约数为 %1").arg(a),
                        QString("gcd = %1").arg(a)});
    return m_frames;
}

void GcdModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (m_slots.empty()) return;

    if (frame.type == ActionType::GC_RESET) {
        for (auto& slot : m_slots) {
            ValueBar* bar = qgraphicsitem_cast<ValueBar*>(slot.item);
            if (!bar) continue;
            bar->setGhost(slot.item != m_slots[0].item);
            bar->setDimmed(false);
            bar->setValue(0);
        }
        if (!m_slots.empty()) {
            ValueBar* first = qgraphicsitem_cast<ValueBar*>(m_slots[0].item);
            if (first) {
                first->setGhost(false);
                first->setColor(kGcA);
                first->setValue(frame.u);
            }
        }
    } else if (frame.type == ActionType::GC_DIVIDE) {
        const int round = frame.val2;
        ValueBar* cur = nullptr;
        for (int i = 0; i <= round && i < static_cast<int>(m_slots.size()); ++i) {
            ValueBar* bar = qgraphicsitem_cast<ValueBar*>(m_slots[i].item);
            if (bar) bar->setGhost(false);
        }
        if (round < static_cast<int>(m_slots.size())) {
            cur = qgraphicsitem_cast<ValueBar*>(m_slots[round].item);
        }
        if (cur) {
            cur->setColor(kGcA);
            cur->setValue(frame.u);
            cur->setSubLabel(QString("第 %1 轮").arg(round + 1));
        }
        if (m_slotCount < static_cast<int>(m_slots.size())) {
            ValueBar* bBar = qgraphicsitem_cast<ValueBar*>(m_slots[m_slotCount].item);
            if (bBar) {
                bBar->setValue(frame.v);
                bBar->setSubLabel(QString("被除数 %1").arg(frame.u));
            }
            ValueBar* rBar = qgraphicsitem_cast<ValueBar*>(m_slots[m_slotCount + 1].item);
            if (rBar) {
                rBar->setValue(frame.val1);
                rBar->setSubLabel(QString("%1 %% %2").arg(frame.u).arg(frame.v));
                if (m_animated) playScalePulse(rBar, 1.2, 260);
            }
        }
    } else if (frame.type == ActionType::GC_SWAP) {
        const int round = frame.val1;
        if (round + 1 < static_cast<int>(m_slots.size())) {
            ValueBar* next = qgraphicsitem_cast<ValueBar*>(m_slots[round + 1].item);
            if (next) {
                next->setGhost(false);
                next->setColor(kGcA);
                next->setValue(frame.u);
                next->setSubLabel(QString("第 %1 轮").arg(round + 2));
            }
        }
        for (int i = 0; i <= round; ++i) {
            ValueBar* bar = qgraphicsitem_cast<ValueBar*>(m_slots[i].item);
            if (bar) bar->setDimmed(true);
        }
    } else if (frame.type == ActionType::GC_DONE) {
        for (auto& slot : m_slots) {
            ValueBar* bar = qgraphicsitem_cast<ValueBar*>(slot.item);
            if (!bar) continue;
            bar->setGhost(false);
            bar->setDimmed(true);
        }
        if (!m_slots.empty()) {
            ValueBar* first = qgraphicsitem_cast<ValueBar*>(m_slots[0].item);
            if (first) {
                first->setColor(kGcR);
                first->setDimmed(false);
                first->setValue(frame.u);
                first->setSubLabel(QString("gcd = %1").arg(frame.u));
                if (m_animated) playScalePulse(first, 1.3, 320);
            }
        }
        if (m_slotCount < static_cast<int>(m_slots.size())) {
            ValueBar* bBar = qgraphicsitem_cast<ValueBar*>(m_slots[m_slotCount].item);
            if (bBar) bBar->setValue(0);
            ValueBar* rBar = qgraphicsitem_cast<ValueBar*>(m_slots[m_slotCount + 1].item);
            if (rBar) rBar->setValue(0);
        }
    }
}

void GcdModule::reset() {
    m_frames.clear();
    m_slots.clear();
    m_mathText = nullptr;
    m_titleA = nullptr;
    m_titleB = nullptr;
    m_titleR = nullptr;
    m_slotCount = 0;
    m_valid = false;
}

void GcdModule::releaseSceneItems() {
    m_slots.clear();
    m_mathText = nullptr;
    m_titleA = nullptr;
    m_titleB = nullptr;
    m_titleR = nullptr;
}

#ifndef DFSMODULE_H
