    m_frames.clear();
    m_nodes.clear();
    m_edges.clear();
    m_distBlocks.clear();
    m_inBlocks.clear();
    m_edgeBlocks.clear();
    m_edgeList.clear();
    m_pickPointer = nullptr;
    m_mathText = nullptr;
    m_n = 0;
    m_m = 0;
    m_src = 1;
