        block->setCustomValue("—");
        block->setPos(startX + (i - 1) * 60, 365);
        scene->addItem(block);
        m_colorBlocks[i] = block;
    }

    m_verdictText = scene->addText("");
    m_verdictText->setFont(UiFonts::cjk(14, true));
    m_verdictText->setDefaultTextColor(QColor(40, 140, 70));
    m_verdictText->setPos(150, 470);
}

std::vector<AnimFrame> BipartiteModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    int color[101];
    std::fill(std::begin(color), std::end(color), -1);
    bool ok = true;

    m_frames.push_back({ActionType::BP_RESET, 0, 0, 0, 0, {},
                        QString("初始化颜色数组，全部未染色"),
                        QString("col[i] = -1")});

    for (int s = 1; s <= m_n && ok; ++s) {
        if (color[s] != -1) continue;
        color[s] = 0;
        m_frames.push_back({ActionType::BP_COLOR, s, 0, 0, 0, {},
                            QString("从孤立分量起点 %1 开始染成白色").arg(s),
                            QString("col[%1] = 0（白）").arg(s)});
        int queue[101]{};
        int head = 0;
        int tail = 0;
        queue[tail++] = s;
        while (head < tail && ok) {
            const int u = queue[head++];
            for (int edge = m_head[u]; edge; edge = m_next[edge]) {
                const int v = m_to[edge];
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    m_frames.push_back({ActionType::BP_COLOR, v, u, color[v], 0, {},
                                        QString("节点 %1 染成%2色").arg(v).arg(color[v] == 0 ? "白" : "黑"),
                                        QString("col[%1] = col[%2] ^ 1 = %3").arg(v).arg(u).arg(color[v])});
                    queue[tail++] = v;
                } else {
                    m_frames.push_back({ActionType::BP_COLOR, u, v, color[v], 1, {},
                                        QString("检查边 %1—%2，两端颜色%3").arg(u).arg(v)
                                            .arg(color[u] == color[v] ? "相同" : "不同"),
                                        QString("col[%1] = %2，col[%3] = %4")
                                            .arg(u).arg(color[u]).arg(v).arg(color[v])});
                    if (color[u] == color[v]) {
                        ok = false;
                        m_frames.push_back({ActionType::BP_CONFLICT, u, v, color[u], 0, {},
                                            QString("冲突！边 %1—%2 两端同色，图不是二分图").arg(u).arg(v),
                                            QString("col[%1] == col[%2] = %3 ⇒ 存在奇环").arg(u).arg(v).arg(color[u])});
                        break;
                    }
                }
            }
        }
    }

    m_frames.push_back({ActionType::BP_FINISH, ok ? 1 : 0, m_n, 0, 0, {},
                        ok ? QString("染色无冲突，该图是二分图")
                            : QString("存在同色相邻点，该图不是二分图"),
                        ok ? QString("图可二分为两部" ) : QString("存在奇数长度回路")});
    return m_frames;
}

void BipartiteModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::BP_RESET) {
        for (auto& kv : m_nodes) {
            kv.second->color = kBpIdle;
            kv.second->setHighlightColor(Qt::transparent);
            kv.second->update();
        }
        for (auto& kv : m_edges) kv.second->setColor(Qt::black);
        for (auto& kv : m_colorBlocks) {
            kv.second->setCustomValue("—");
            kv.second->color = Qt::white;
            kv.second->update();
        }
        if (m_verdictText) {
            m_verdictText->setPlainText("");
            m_verdictText->setDefaultTextColor(QColor(40, 140, 70));
        }
    } else if (frame.type == ActionType::BP_COLOR) {
        const int u = frame.u;
        const int v = frame.v;
        if (frame.val2 == 1) {
            GraphEdge* edge = GraphRenderHelper::findEdge(m_edges, u, v);
            if (edge) {
                edge->setColor(colorEqual(u, v) ? kBpConflict : QColor(80, 175, 120));
                edge->update();
            }
            if (m_nodes.count(u)) {
                m_nodes[u]->setHighlightColor(QColor(255, 225, 165));
                m_nodes[u]->update();
            }
            if (m_nodes.count(v)) {
                m_nodes[v]->setHighlightColor(QColor(255, 225, 165));
                m_nodes[v]->update();
            }
            return;
        }
        const int c = frame.val1;
        if (m_nodes.count(v > 0 ? v : u)) {
            const int target = v > 0 ? v : u;
            m_nodes[target]->color = c == 0 ? kBpWhite : kBpBlack;
            m_nodes[target]->setHighlightColor(c == 0 ? kBpWhite : kBpBlack);
            m_nodes[target]->update();
            if (m_animated) playScalePulse(m_nodes[target], 1.22, 240);
        }
        if (m_colorBlocks.count(u)) {
            m_colorBlocks[u]->setCustomValue(c == 0 ? "0" : "1");
            m_colorBlocks[u]->color = c == 0 ? kBpWhite : kBpBlack;
            m_colorBlocks[u]->update();
        }
        if (m_colorBlocks.count(v)) {
            m_colorBlocks[v]->setCustomValue(c == 0 ? "0" : "1");
            m_colorBlocks[v]->color = c == 0 ? kBpWhite : kBpBlack;
            m_colorBlocks[v]->update();
        }
    } else if (frame.type == ActionType::BP_CONFLICT) {
        if (m_nodes.count(frame.u)) {
            m_nodes[frame.u]->color = kBpConflict;
            m_nodes[frame.u]->setHighlightColor(kBpConflict);
            m_nodes[frame.u]->update();
            if (m_animated) playScalePulse(m_nodes[frame.u], 1.3, 300);
        }
        if (m_nodes.count(frame.v)) {
            m_nodes[frame.v]->color = kBpConflict;
            m_nodes[frame.v]->setHighlightColor(kBpConflict);
            m_nodes[frame.v]->update();
            if (m_animated) playScalePulse(m_nodes[frame.v], 1.3, 300);
        }
        GraphEdge* edge = GraphRenderHelper::findEdge(m_edges, frame.u, frame.v);
        if (edge) {
            edge->setColor(kBpConflict);
            edge->setPenWidth(5.0);
            edge->update();
        }
        if (m_verdictText) {
            m_verdictText->setPlainText(QString("冲突：%1 与 %2 同色，非二分图").arg(frame.u).arg(frame.v));
            m_verdictText->setDefaultTextColor(kBpConflict.darker(115));
        }
    } else if (frame.type == ActionType::BP_FINISH) {
        if (m_verdictText) {
            const bool ok = frame.u == 1;
            m_verdictText->setPlainText(ok ? QString("结论：该图是二分图")
                                          : QString("结论：该图不是二分图"));
            m_verdictText->setDefaultTextColor(ok ? QColor(40, 140, 70) : kBpConflict.darker(115));
        }
        for (auto& kv : m_nodes) {
            kv.second->setHighlightColor(Qt::transparent);
            kv.second->update();
        }
    }
}

bool BipartiteModule::colorEqual(int u, int v) const {
    if (!m_colorBlocks.count(u) || !m_colorBlocks.count(v)) return false;
    return m_colorBlocks.at(u)->customValue == m_colorBlocks.at(v)->customValue;
}

void BipartiteModule::reset() {
    m_frames.clear();
    m_nodes.clear();
    m_edges.clear();
    m_colorBlocks.clear();
    m_edgeList.clear();
    m_mathText = nullptr;
    m_verdictText = nullptr;
    m_n = 0;
    m_m = 0;
    m_edgeCount = 0;
    m_valid = false;
    std::fill(std::begin(m_head), std::end(m_head), 0);
    std::fill(std::begin(m_to), std::end(m_to), 0);
    std::fill(std::begin(m_next), std::end(m_next), 0);
}

void BipartiteModule::releaseSceneItems() {
    m_nodes.clear();
    m_edges.clear();
    m_colorBlocks.clear();
    m_mathText = nullptr;
    m_verdictText = nullptr;
}

private:
    bool colorEqual(int u, int v) const;

    std::vector<AnimFrame> m_frames;

