    GraphRenderHelper::buildNodes(scene, m_nodes, m_n, QPointF(470, 165), m_n <= 8 ? 110 : 130, this);
    GraphRenderHelper::buildEdges(scene, m_nodes, m_edges, input.edges, options, input.weighted);

