#include "TrieModule.h"
#include <QFont>
#include <QRegularExpression>
#include <algorithm>
#include "ui/UiFonts.h"

static const QColor kTrIdle = QColor(252, 252, 254);
static const QColor kTrPath = QColor(160, 205, 245);
static const QColor kTrNew = QColor(255, 210, 145);
static const QColor kTrEnd = QColor(140, 205, 165);

TrieModule::TrieModule() {}

QString TrieModule::getModuleName() const { return "Trie 字典树"; }
QString TrieModule::getDefaultInput() const { return "4\ncat\ncar\ndog\ncat"; }
QString TrieModule::getInputHint() const {
    return "第一行输入一个正整数 n，表示待插入的单词个数（n <= 6）\n"
           "接下来 n 行，每行一个小写字母组成的单词（长度 2~8）\n"
           "算法沿字符逐层向下走，已有分支直接复用，新分支才建节点";
}

void TrieModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList lines = inputData.split(QRegularExpression("[\\r\\n]"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!lines.isEmpty()) {
        n = lines[0].trimmed().toInt(&ok);
        m_valid = ok && n >= 1 && n <= 6 && lines.size() >= n + 1;
    }

    m_mathText = scene->addText(m_valid ? "Trie 字典树：插入单词，逐字符沿已有分支下行"
                                        : "输入格式：n，随后输入 n 个小写单词；n≤6");
    m_mathText->setFont(UiFonts::mono(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(150, 18);
    if (!m_valid) return;

    std::vector<QString> words;
    for (int i = 1; i <= n; ++i) {
        const QString w = lines[i].trimmed();
        if (w.size() < 2 || w.size() > 8) {
            m_valid = false;
            break;
        }
        words.push_back(w);
    }
    if (!m_valid) return;

    m_wordIndex = 0;
    m_wordText = scene->addText("");
    m_wordText->setFont(UiFonts::mono(17, true));
    m_wordText->setDefaultTextColor(QColor(60, 75, 95));
    m_wordText->setPos(150, 60);

    TrieNode root;
    root.id = 0;
    root.ch = 0;
    root.parent = -1;
    m_nodes.push_back(root);

    for (const QString& w : words) {
        int cur = 0;
        for (const QChar& ch : w) {
            int found = -1;
            for (int child : m_nodes[cur].children) {
                if (m_nodes[child].ch == ch.toLatin1()) {
                    found = child;
                    break;
                }
            }
            if (found < 0) {
                TrieNode node;
                node.id = static_cast<int>(m_nodes.size());
                node.ch = ch.toLatin1();
                node.parent = cur;
                m_nodes.push_back(node);
                m_nodes[cur].children.push_back(node.id);
                found = node.id;
            }
            cur = found;
        }
        m_nodes[cur].isEnd = true;
    }

    layoutTree(scene, words.size());

    const double startX = 150.0;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        ArrayBlock* block = new ArrayBlock(i, 0, QString::number(i));
        block->setCustomValue(m_nodes[i].isEnd ? "1" : "0");
        block->setCellSize(48, 36);
        block->setPos(startX + i * 54, 560);
        scene->addItem(block);
        m_endBlocks[i] = block;
    }
}

void TrieModule::layoutTree(QGraphicsScene* scene, int wordCount) {
    const int maxDepth = 8;
    const double levelGap = 76.0;
    std::vector<int> depth(m_nodes.size(), 0);
    for (size_t i = 1; i < m_nodes.size(); ++i) {
        depth[i] = depth[m_nodes[i].parent] + 1;
    }
    std::vector<int> levelCount(maxDepth + 1, 0);
    for (size_t i = 0; i < m_nodes.size(); ++i) {
        levelCount[qMin(depth[i], maxDepth)]++;
    }
    std::vector<int> levelIndex(maxDepth + 1, 0);
    const double leafGap = 76.0;
    const double centerX = 520.0;
    for (size_t i = 0; i < m_nodes.size(); ++i) {
        const int d = qMin(depth[i], maxDepth);
        const double span = levelCount[d] * leafGap;
        const double x = centerX - span / 2.0 + levelIndex[d] * leafGap + leafGap / 2.0;
        const double y = 130.0 + d * levelGap;
        ++levelIndex[d];

        GraphNode* node = new GraphNode(static_cast<int>(i));
        node->setPos(x, y);
        node->color = kTrIdle;
        node->setCustomValueText(QString(QChar(m_nodes[i].ch)));
        scene->addItem(node);
        m_nodes[i].node = node;
    }
    for (size_t i = 1; i < m_nodes.size(); ++i) {
        GraphNode* parent = m_nodes[m_nodes[i].parent].node;
        GraphNode* child = m_nodes[i].node;
        if (!parent || !child) continue;
        GraphEdge* edge = new GraphEdge(parent, child, true);
        edge->color = QColor(196, 204, 216);
        scene->addItem(edge);
        parent->addEdge(edge);
        child->addEdge(edge);
        m_edges[static_cast<int>(i)] = edge;
    }
    Q_UNUSED(wordCount);
}

std::vector<AnimFrame> TrieModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    const QStringList lines = QStringList();
    Q_UNUSED(lines);

    m_frames.push_back({ActionType::TR_RESET, 0, 0, 0, 0, {},
                        QString("初始化字典树，根节点编号 0"), QString("Trie 根节点为空")});

    const int nodeCount = static_cast<int>(m_nodes.size());
    for (int i = 1; i < nodeCount; ++i) {
        m_frames.push_back({ActionType::TR_CREATE, i, m_nodes[i].parent,
                            static_cast<QChar>(m_nodes[i].ch).toLatin1(), 0, {},
                            QString("节点 %1 是 %2 的子节点，字符 '%3'")
                                .arg(i).arg(m_nodes[m_nodes[i].parent].parent < 0 ? "根" : QString::number(m_nodes[m_nodes[i].parent].parent))
                                .arg(QString(QChar(m_nodes[i].ch))),
                            QString("新建节点 %1").arg(i)});
    }

    m_frames.push_back({ActionType::TR_HIT, 0, 0, 0, 0, {},
                        QString("所有单词插入完成"), QString("末节点标记 end = 1")});
    m_frames.push_back({ActionType::TR_DONE, nodeCount, 0, 0, 0, {},
                        QString("字典树共 %1 个节点").arg(nodeCount),
                        QString("公共前缀只建一份节点")});
    return m_frames;
}

void TrieModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::TR_RESET) {
        for (auto& n : m_nodes) {
            if (!n.node) continue;
            GraphNode* g = qgraphicsitem_cast<GraphNode*>(n.node);
            if (!g) continue;
            g->color = kTrIdle;
            g->setHighlightColor(Qt::transparent);
            g->update();
        }
        for (auto& kv : m_edges) {
            kv.second->setColor(QColor(196, 204, 216));
            kv.second->update();
        }
        for (auto& kv : m_endBlocks) {
            kv.second->setCustomValue(kv.first == 0 ? "0" : "0");
            kv.second->color = Qt::white;
            kv.second->update();
        }
        if (m_wordText) m_wordText->setPlainText("");
    } else if (frame.type == ActionType::TR_CREATE) {
        const int id = frame.u;
        if (id < 0 || id >= static_cast<int>(m_nodes.size())) return;
        if (m_nodes[id].node) {
            GraphNode* g = qgraphicsitem_cast<GraphNode*>(m_nodes[id].node);
            if (g) {
                g->color = kTrNew;
                g->setHighlightColor(kTrNew);
                g->update();
                if (m_animated) playScalePulse(g, 1.25, 260);
            }
        }
        auto edgeIt = m_edges.find(id);
        if (edgeIt != m_edges.end()) {
            edgeIt->second->setColor(QColor(235, 155, 55));
            edgeIt->second->setPenWidth(3.4);
            edgeIt->second->update();
        }
        if (m_wordText) {
            m_wordText->setPlainText(QString("插入字符 '%1' → 节点 %2")
                                     .arg(QString(QChar(static_cast<char>(frame.val1)))).arg(id));
        }
    } else if (frame.type == ActionType::TR_HIT) {
        for (auto& n : m_nodes) {
            if (!n.node) continue;
            GraphNode* g = qgraphicsitem_cast<GraphNode*>(n.node);
            if (!g) continue;
            if (n.isEnd) {
                g->color = kTrEnd;
                g->update();
            }
        }
        for (auto& kv : m_edges) {
            if (kv.second->color == QColor(235, 155, 55)) {
                kv.second->setColor(kTrPath);
                kv.second->setPenWidth(3.0);
                kv.second->update();
            }
        }
        for (auto& kv : m_endBlocks) {
            const bool isEnd = kv.first < static_cast<int>(m_nodes.size()) && m_nodes[kv.first].isEnd;
            kv.second->setCustomValue(isEnd ? "1" : "0");
            kv.second->color = isEnd ? kTrEnd : Qt::white;
            kv.second->update();
        }
        if (m_wordText) m_wordText->setPlainText("");
    } else if (frame.type == ActionType::TR_DONE) {
        for (auto& n : m_nodes) {
            if (!n.node) continue;
            GraphNode* g = qgraphicsitem_cast<GraphNode*>(n.node);
            if (!g) continue;
            g->setHighlightColor(Qt::transparent);
            g->update();
        }
    }
}

