        if (mod.matrixBlock()) {
            check(mod.matrixBlock()->blockShape() == MatrixBlock::BracketedTable, "shape is BracketedTable");
            check(mod.matrixBlock()->cellAt(0, 0) == "1", "row-major value (0,0)=1");
            check(mod.matrixBlock()->cellAt(1, 0) == "4", "row-major value (1,0)=4");
