    bool ok = false;
    int a = 0;
    int b = 0;
    if (tokens.size() >= 2) {
        a = tokens[0].toInt(&ok);
        const bool okA = ok && a >= 1 && a <= 100000;
        b = tokens[1].toInt(&ok);
        m_valid = okA && ok && b >= 1 && b <= 100000;
    }

    m_mathText = scene->addText(m_valid ? "辗转相除：r = a % b，小的替换大的，直到 b = 0"
                                        : "输入格式：两个正整数 a b");
