void HashTableModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!tokens.isEmpty()) {
        n = tokens[0].toInt(&ok);
        m_valid = ok && n >= 1 && n <= 6 && tokens.size() >= n + 1;
        if (m_valid) {
            for (int i = 0; i < n; ++i) {
                const int v = tokens[i + 1].toInt(&ok);
                if (!ok || v < 0 || v > 999) {
                    m_valid = false;
                    break;
                }
                m_keys.push_back(v);
            }
        }
    }

    m_mathText = scene->addText(m_valid ? "哈希表：h(k) = k % 7，冲突则线性探测下一个空槽"
                                        : "输入格式：n，随后输入 n 个非负整数；n≤6");
    m_mathText->setFont(UiFonts::mono(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(140, 18);
    if (!m_valid) return;

    const double cellW = 66.0;
    const double cellH = 42.0;
    const double left = 260.0;

    auto addLabel = [scene](const QString& text, double x, double y) {
        QGraphicsTextItem* item = scene->addText(text);
        item->setFont(UiFonts::cjk(11, true));
        item->setDefaultTextColor(QColor(60, 75, 95));
        item->setPos(x, y);
    };
    addLabel("槽位 table[]", left - 118, 104);
    addLabel("存放的关键字", left - 118, 206);

    for (int i = 0; i < m_capacity; ++i) {
        ArrayBlock* slot = new ArrayBlock(i, 0, QString::number(i));
        slot->setCellSize(cellW, cellH);
        slot->setCustomValue("—");
        slot->setPos(left + i * cellW, 118);
        scene->addItem(slot);
        m_slotBlocks.push_back(slot);

        ArrayBlock* key = new ArrayBlock(i, 0, QString::number(i));
        key->setCellSize(cellW, cellH);
        key->showValue = false;
        key->setPos(left + i * cellW, 220);
        scene->addItem(key);
        m_keyBlocks.push_back(key);
    }

    m_probePointer = new PointerBlock("k", QColor(210, 80, 55));
    m_probePointer->setOpacity(0);
    m_probePointer->setLabelToRight();
    m_probePointer->setAnchorOffset(QPointF(30, 34));
    scene->addItem(m_probePointer);

    m_probeText = scene->addText("");
    m_probeText->setFont(UiFonts::mono(14, true));
    m_probeText->setDefaultTextColor(QColor(200, 110, 40));
    m_probeText->setPos(left, 312);
}

std::vector<AnimFrame> HashTableModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    std::vector<int> table(m_capacity, -1);

    m_frames.push_back({ActionType::HT_RESET, 0, 0, 0, 0, {},
                        QString("初始化 %1 个空槽位").arg(m_capacity),
                        QString("h(k) = k % %1").arg(m_capacity)});

    for (int i = 0; i < static_cast<int>(m_keys.size()); ++i) {
        const int key = m_keys[i];
        int slot = key % m_capacity;
        int probe = 0;
        m_frames.push_back({ActionType::HT_HASH, key, slot, i, 0, {},
                            QString("关键字 %1 计算哈希位置 %2").arg(key).arg(slot),
                            QString("h(%1) = %1 %% %2 = %3").arg(key).arg(m_capacity).arg(slot)});
        while (table[slot] != -1) {
            ++probe;
            const int next = (slot + 1) % m_capacity;
            m_frames.push_back({ActionType::HT_PROBE, key, slot, next, probe, {},
                                QString("冲突！槽 %1 已被 %2 占用，线性探测到槽 %3").arg(slot).arg(table[slot]).arg(next),
                                QString("槽 %1 冲突 → 探测槽 %2").arg(slot).arg(next)});
            slot = next;
        }
        table[slot] = key;
        m_frames.push_back({ActionType::HT_INSERT, key, slot, i, probe, {},
                            QString("关键字 %1 放入空槽 %2").arg(key).arg(slot),
                            QString("table[%1] = %2").arg(slot).arg(key)});
    }

    m_frames.push_back({ActionType::HT_DONE, static_cast<int>(m_keys.size()), m_capacity, 0, 0, {},
                        QString("插入完成，共 %1 个关键字").arg(m_keys.size()),
                        QString("线性探测平均代价低于链地址法")});
    return m_frames;
}

void HashTableModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::HT_RESET) {
        for (size_t i = 0; i < m_slotBlocks.size(); ++i) {
            m_slotBlocks[i]->setCustomValue("—");
            m_slotBlocks[i]->color = kHtEmpty;
            m_slotBlocks[i]->update();
            m_keyBlocks[i]->showValue = false;
            m_keyBlocks[i]->color = kHtEmpty;
            m_keyBlocks[i]->update();
        }
        m_probePointer->setOpacity(0);
        if (m_probeText) {
            m_probeText->setPlainText("");
            m_probeText->setDefaultTextColor(QColor(200, 110, 40));
        }
    } else if (frame.type == ActionType::HT_HASH) {
        const int slot = frame.v;
        if (slot >= 0 && slot < static_cast<int>(m_slotBlocks.size())) {
            m_slotBlocks[slot]->color = kHtProbe;
            m_slotBlocks[slot]->update();
            m_probePointer->setOpacity(1);
            m_probePointer->setAnchorNode(m_slotBlocks[slot]);
            m_probePointer->syncToAnchor();
        }
        if (m_probeText) {
            m_probeText->setPlainText(QString("h(%1) = %1 %% %2 = %3").arg(frame.u).arg(m_capacity).arg(slot));
            m_probeText->setDefaultTextColor(QColor(200, 110, 40));
        }
    } else if (frame.type == ActionType::HT_PROBE) {
        const int from = frame.u;
        const int to = frame.v;
        if (from >= 0 && from < static_cast<int>(m_slotBlocks.size())) {
            m_slotBlocks[from]->color = kHtConflict;
            m_slotBlocks[from]->update();
        }
        if (to >= 0 && to < static_cast<int>(m_slotBlocks.size())) {
            m_slotBlocks[to]->color = kHtProbe;
            m_slotBlocks[to]->update();
            m_probePointer->setAnchorNode(m_slotBlocks[to]);
            m_probePointer->syncToAnchor();
            if (m_animated) playScalePulse(m_slotBlocks[to], 1.14, 220);
        }
        if (m_probeText) {
            m_probeText->setPlainText(QString("槽 %1 冲突（已存 %2），去探测槽 %3").arg(from).arg(frame.u).arg(to));
            m_probeText->setDefaultTextColor(kHtConflict.darker(110));
        }
    } else if (frame.type == ActionType::HT_INSERT) {
        const int slot = frame.v;
        if (slot >= 0 && slot < static_cast<int>(m_slotBlocks.size())) {
            m_slotBlocks[slot]->setCustomValue(QString::number(frame.u));
            m_slotBlocks[slot]->color = kHtFilled;
            m_slotBlocks[slot]->update();
            if (m_animated) playScalePulse(m_slotBlocks[slot], 1.18, 260);
        }
        if (slot >= 0 && slot < static_cast<int>(m_keyBlocks.size())) {
            m_keyBlocks[slot]->showValue = true;
            m_keyBlocks[slot]->value = frame.u;
            m_keyBlocks[slot]->color = kHtKey;
            m_keyBlocks[slot]->update();
        }
        if (m_probeText) {
            m_probeText->setPlainText(QString("关键字 %1 → 槽 %2（探测 %3 次）").arg(frame.u).arg(slot).arg(frame.val2));
            m_probeText->setDefaultTextColor(QColor(40, 140, 70));
        }
    } else if (frame.type == ActionType::HT_DONE) {
        for (auto* b : m_slotBlocks) {
            if (b->customValue != "—") { b->color = kHtFilled; b->update(); }
        }
        for (auto* b : m_keyBlocks) {
            if (b->showValue) { b->color = kHtKey; b->update(); }
        }
        m_probePointer->setOpacity(0);
    }
}

void HashTableModule::reset() {
    m_frames.clear();
    m_slotBlocks.clear();
    m_keyBlocks.clear();
    m_keys.clear();
    m_mathText = nullptr;
    m_probeText = nullptr;
    m_probePointer = nullptr;
    m_capacity = 7;
    m_valid = false;
}

void HashTableModule::releaseSceneItems() {
    m_slotBlocks.clear();
    m_keyBlocks.clear();
    m_mathText = nullptr;
    m_probeText = nullptr;
    m_probePointer = nullptr;
}

#ifndef TRIEMODULE_H
#define TRIEMODULE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <QObject>
#include <QGraphicsTextItem>
#include <map>
#include <vector>

class TrieModule : public QObject, public IModule {
    Q_OBJECT
public:
    TrieModule();
    QString getModuleName() const override;
    QString getDefaultInput() const override;
    QString getInputHint() const override;
    void buildLayout(QGraphicsScene* scene, const QString& inputData) override;
    std::vector<AnimFrame> runAlgorithm() override;
    void renderFrame(const AnimFrame& frame) override;
    void reset() override;
    void releaseSceneItems() override;

private:
    struct TrieNode {
        int id = 0;
        char ch = 0;
        int parent = -1;
        std::vector<int> children;
        bool isEnd = false;
        GraphNode* node = nullptr;
    };

    void createNodeItem(int id);
    void createEdgeItem(int childId);
    void layoutNode(int id, double x, double y);
    void rebuildLayout();
    double slotX(int index) const;
    int findChild(int parent, char ch) const;
    void ensureEndBlock(int index);

    std::vector<AnimFrame> m_frames;
    std::vector<TrieNode> m_nodes;
    std::map<int, GraphEdge*> m_edges;
    std::map<int, ArrayBlock*> m_endBlocks;
    QGraphicsTextItem* m_mathText = nullptr;
    QGraphicsTextItem* m_wordText = nullptr;
    QGraphicsTextItem* m_stateText = nullptr;
    ArrayBlock* m_charBlocks = nullptr;
    std::vector<ArrayBlock*> m_charCells;
    PointerBlock* m_cursorPointer = nullptr;
    PointerBlock* m_indexPointer = nullptr;
    std::vector<QString> m_words;
    bool m_valid = false;
};

#endif

#include "TrieModule.h"
#include <QFont>
#include <QRegularExpression>
#include <algorithm>
#include "ui/UiFonts.h"

static const QColor kTrIdle = QColor(252, 252, 254);
static const QColor kTrNew = QColor(255, 210, 145);
static const QColor kTrEnd = QColor(140, 205, 165);
static const QColor kTrCursor = QColor(255, 235, 180);
static const QColor kTrEdge = QColor(196, 204, 216);

TrieModule::TrieModule() {}

QString TrieModule::getModuleName() const { return "Trie 字典树"; }
QString TrieModule::getDefaultInput() const { return "3\ncat\ncar\ndog"; }
QString TrieModule::getInputHint() const {
    return "第一行输入一个正整数 n，表示待插入的单词个数（n <= 6）\n"
           "接下来 n 行，每行一个小写字母组成的单词（长度 2~8）\n"
           "算法沿字符逐层向下走：已有分支直接复用，新分支才新建节点";
}

double TrieModule::slotX(int index) const {
    return 170.0 + index * 54.0;
}

int TrieModule::findChild(int parent, char ch) const {
    if (parent < 0 || parent >= static_cast<int>(m_nodes.size())) return -1;
    for (int child : m_nodes[parent].children) {
        if (m_nodes[child].ch == ch) return child;
    }
    return -1;
}

void TrieModule::ensureEndBlock(int index) {
    if (index < 0) return;
    if (m_endBlocks.count(index)) return;
    ArrayBlock* block = new ArrayBlock(index, 0, QString::number(index));
    block->setCellSize(54, 38);
    block->setCustomValue("0");
    block->setPos(slotX(index), 560);
    m_scene->addItem(block);
    m_endBlocks[index] = block;
}

void TrieModule::createNodeItem(int id) {
    if (id < 0 || id >= static_cast<int>(m_nodes.size())) return;
    if (m_nodes[id].node) return;
    GraphNode* node = new GraphNode(id);
    node->color = kTrIdle;
    node->setCustomValueText(QString(QChar(m_nodes[id].ch)));
    m_scene->addItem(node);
    m_nodes[id].node = node;
}

void TrieModule::createEdgeItem(int childId) {
    if (childId <= 0 || childId >= static_cast<int>(m_nodes.size())) return;
    if (m_edges.count(childId)) return;
    const int parentId = m_nodes[childId].parent;
    if (parentId < 0) return;
    if (!m_nodes[parentId].node) createNodeItem(parentId);
    if (!m_nodes[childId].node) createNodeItem(childId);
    GraphEdge* edge = new GraphEdge(m_nodes[parentId].node, m_nodes[childId].node, true);
    edge->color = kTrEdge;
    m_scene->addItem(edge);
    m_nodes[parentId].node->addEdge(edge);
    m_nodes[childId].node->addEdge(edge);
    m_edges[childId] = edge;
}

void TrieModule::layoutNode(int id, double x, double y) {
    if (id < 0 || id >= static_cast<int>(m_nodes.size())) return;
    if (!m_nodes[id].node) createNodeItem(id);
    if (m_nodes[id].node) m_nodes[id].node->setPos(x, y);
}

void TrieModule::rebuildLayout() {
    const int count = static_cast<int>(m_nodes.size());
    std::vector<int> depth(count, 0);
    int maxDepth = 0;
    for (int i = 1; i < count; ++i) {
        depth[i] = depth[m_nodes[i].parent] + 1;
        maxDepth = qMax(maxDepth, depth[i]);
    }
    std::vector<int> levelCount(maxDepth + 1, 0);
    for (int i = 0; i < count; ++i) {
        if (i == 0) { levelCount[0] = 1; continue; }
        ++levelCount[depth[i]];
    }
    std::vector<int> levelIndex(maxDepth + 1, 0);
    const double levelGap = 82.0;
    const double leafGap = 74.0;
    const double centerX = 520.0;
    for (int i = 0; i < count; ++i) {
        const int d = depth[i];
        const double span = levelCount[d] * leafGap;
        const double x = centerX - span / 2.0 + levelIndex[d] * leafGap + leafGap / 2.0;
        const double y = 130.0 + d * levelGap;
        ++levelIndex[d];
        layoutNode(i, x, y);
    }
}

void TrieModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList lines = inputData.split(QRegularExpression("[\\r\\n]"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!lines.isEmpty()) {
        n = lines[0].trimmed().toInt(&ok);
        m_valid = ok && n >= 1 && n <= 6 && lines.size() >= n + 1;
    }

    m_mathText = scene->addText(m_valid ? "Trie 字典树：逐字符动态建树，已有分支直接复用"
                                        : "输入格式：n，随后输入 n 个小写单词；n≤6");
    m_mathText->setFont(UiFonts::mono(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(150, 18);
    if (!m_valid) return;

    for (int i = 1; i <= n; ++i) {
        const QString w = lines[i].trimmed();
        if (w.size() < 2 || w.size() > 8) {
            m_valid = false;
            break;
        }
        m_words.push_back(w);
    }
    if (!m_valid) return;

    m_wordText = scene->addText("");
    m_wordText->setFont(UiFonts::cjk(13, true));
    m_wordText->setDefaultTextColor(QColor(60, 75, 95));
    m_wordText->setPos(150, 62);

    m_stateText = scene->addText("");
    m_stateText->setFont(UiFonts::mono(14, true));
    m_stateText->setDefaultTextColor(QColor(40, 70, 110));
    m_stateText->setPos(150, 92);

    const int maxLen = 8;
    const double cellW = 54.0;
    const double rowY = 470.0;
    const double startX = 170.0;

    for (int i = 0; i < maxLen; ++i) {
        ArrayBlock* cell = new ArrayBlock(i, 0, QString::number(i));
        cell->setCellSize(cellW, 38);
        cell->setCustomValue("·");
        cell->color = QColor(250, 250, 252);
        cell->setPos(startX + i * cellW, rowY);
        scene->addItem(cell);
        m_charCells.push_back(cell);
    }

    QGraphicsTextItem* rowLabel = scene->addText("当前单词");
    rowLabel->setFont(UiFonts::cjk(11, true));
    rowLabel->setDefaultTextColor(QColor(60, 75, 95));
    rowLabel->setPos(40, rowY + 8);

    QGraphicsTextItem* slotLabel = scene->addText("节点槽位（树内存）");
    slotLabel->setFont(UiFonts::cjk(11, true));
    slotLabel->setDefaultTextColor(QColor(60, 75, 95));
    slotLabel->setPos(40, 570);

    m_indexPointer = new PointerBlock("i", QColor(210, 80, 55));
    m_indexPointer->setOpacity(0);
    m_indexPointer->setDirection(PointerBlock::Down);
    m_indexPointer->setLabelOffset(QPointF(0, 46));
    scene->addItem(m_indexPointer);

    m_cursorPointer = new PointerBlock("p", QColor(60, 140, 220));
    m_cursorPointer->setOpacity(0);
    m_cursorPointer->setLabelAbove(true);
    scene->addItem(m_cursorPointer);

    TrieNode root;
    root.id = 0;
    root.ch = 0;
    root.parent = -1;
    m_nodes.push_back(root);
    createNodeItem(0);
    m_nodes[0].node->setCustomValueText(QString("根"));
    rebuildLayout();
    ensureEndBlock(0);
}

std::vector<AnimFrame> TrieModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    m_frames.push_back({ActionType::TR_RESET, 0, 0, 0, 0, {},
                        QString("初始化：画布上只有根节点，游标 p 指向根节点"),
                        QString("p = 根节点（编号 0）")});

    int nodeCount = 1;

    for (int w = 0; w < static_cast<int>(m_words.size()); ++w) {
        const QString word = m_words[w];
        m_frames.push_back({ActionType::TR_WORD, w, 0, 0, 0, {},
                            QString("取第 %1 个单词 \"%2\"").arg(w + 1).arg(word),
                            QString("插入 %1").arg(word)});

        int cursor = 0;
        for (int pos = 0; pos < word.size(); ++pos) {
            const char ch = word.at(pos).toLatin1();
            const int existing = findChild(cursor, ch);
            if (existing >= 0) {
                m_frames.push_back({ActionType::TR_HIT, cursor, existing, ch, pos, {},
                                    QString("节点 %1 已有子节点 '%2'（编号 %3），直接复用")
                                        .arg(cursor).arg(QString(QChar(ch))).arg(existing),
                                    QString("p = %1（复用）").arg(existing)});
                cursor = existing;
            } else {
                const int newId = nodeCount++;
                m_frames.push_back({ActionType::TR_CREATE, cursor, newId, ch, pos, {},
                                    QString("节点 %1 没有 '%2' 子节点，新建节点 %3")
                                        .arg(cursor).arg(QString(QChar(ch))).arg(newId),
                                    QString("新建节点 %1").arg(newId)});
                cursor = newId;
            }
        }
        m_frames.push_back({ActionType::TR_END, cursor, word.size(), 0, 0, {},
                            QString("单词 \"%1\" 插入完毕，末节点 %2 标记 end = 1").arg(word).arg(cursor),
                            QString("end[%1] = 1").arg(cursor)});
    }

    m_frames.push_back({ActionType::TR_DONE, nodeCount, 0, 0, 0, {},
                        QString("字典树共 %1 个节点，公共前缀只建一份").arg(nodeCount),
                        QString("节点总数 = %1").arg(nodeCount)});
    return m_frames;
}

void TrieModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::TR_RESET) {
        for (auto& n : m_nodes) {
            if (!n.node) continue;
            n.node->color = kTrIdle;
            n.node->setHighlightColor(Qt::transparent);
            n.node->update();
        }
        for (auto& kv : m_edges) {
            kv.second->setColor(kTrEdge);
            kv.second->setPenWidth(2.0);
            kv.second->update();
        }
        for (auto& kv : m_endBlocks) {
            kv.second->setCustomValue("0");
            kv.second->color = Qt::white;
            kv.second->update();
        }
        for (size_t i = 0; i < m_charCells.size(); ++i) {
            m_charCells[i]->setCustomValue("·");
            m_charCells[i]->color = QColor(250, 250, 252);
            m_charCells[i]->update();
        }
        if (m_wordText) m_wordText->setPlainText("");
        if (m_stateText) {
            m_stateText->setPlainText("p → 根节点");
            m_stateText->setDefaultTextColor(QColor(40, 70, 110));
        }
        m_cursorPointer->setOpacity(1);
        if (m_nodes[0].node) {
            m_cursorPointer->setAnchorNode(m_nodes[0].node);
            m_cursorPointer->syncToAnchor();
        }
        m_indexPointer->setOpacity(0);
    } else if (frame.type == ActionType::TR_WORD) {
        const int wordIndex = frame.u;
        const QString word = wordIndex >= 0 && wordIndex < static_cast<int>(m_words.size())
            ? m_words[wordIndex] : QString();
        if (m_wordText) {
            m_wordText->setPlainText(QString("当前单词：%1").arg(word));
        }
        for (size_t i = 0; i < m_charCells.size(); ++i) {
            m_charCells[i]->setCustomValue(i < static_cast<size_t>(word.size())
                ? QString(word.at(static_cast<int>(i))) : QString("·"));
            m_charCells[i]->color = i < static_cast<size_t>(word.size())
                ? QColor(226, 238, 252) : QColor(250, 250, 252);
            m_charCells[i]->update();
        }
        m_indexPointer->setOpacity(1);
        if (!m_charCells.empty()) {
            m_indexPointer->setAnchorNode(m_charCells[0]);
            m_indexPointer->syncToAnchor();
        }
        m_cursorPointer->setOpacity(1);
        if (m_nodes[0].node) {
            m_cursorPointer->setAnchorNode(m_nodes[0].node);
            m_cursorPointer->syncToAnchor();
        }
    } else if (frame.type == ActionType::TR_HIT) {
        const int from = frame.u;
        const int target = frame.v;
        const char ch = static_cast<char>(frame.val1);
        const int pos = frame.val2;

        if (pos >= 0 && pos < static_cast<int>(m_charCells.size())) {
            m_charCells[pos]->color = kTrCursor;
            m_charCells[pos]->update();
            m_indexPointer->setAnchorNode(m_charCells[pos]);
            m_indexPointer->syncToAnchor();
        }
        if (m_stateText) {
            m_stateText->setPlainText(QString("p = %1：找 '%2' → 已有，p 移到 %3")
                                      .arg(from).arg(QString(QChar(ch))).arg(target));
        }
        auto edgeIt = m_edges.find(target);
        if (edgeIt != m_edges.end()) {
            edgeIt->second->setColor(QColor(80, 175, 120));
            edgeIt->second->setPenWidth(3.0);
            edgeIt->second->update();
        }
        m_cursorPointer->setOpacity(1);
        if (m_nodes.count(target) && m_nodes[target].node) {
            m_cursorPointer->setAnchorNode(m_nodes[target].node);
            m_cursorPointer->syncToAnchor();
            if (m_animated) playScalePulse(m_nodes[target].node, 1.12, 200);
        }
    } else if (frame.type == ActionType::TR_CREATE) {
        const int parentId = frame.u;
        const int newId = frame.v;
        const char ch = static_cast<char>(frame.val1);
        const int pos = frame.val2;

        while (static_cast<int>(m_nodes.size()) <= newId) {
            TrieNode node;
            node.id = static_cast<int>(m_nodes.size());
            node.parent = -1;
            m_nodes.push_back(node);
        }
        m_nodes[newId].id = newId;
        m_nodes[newId].ch = ch;
        m_nodes[newId].parent = parentId;
        m_nodes[parentId].children.push_back(newId);

        createNodeItem(newId);
        createEdgeItem(newId);
        ensureEndBlock(newId);
        rebuildLayout();

        if (pos >= 0 && pos < static_cast<int>(m_charCells.size())) {
            m_charCells[pos]->color = kTrCursor;
            m_charCells[pos]->update();
            m_indexPointer->setAnchorNode(m_charCells[pos]);
            m_indexPointer->syncToAnchor();
        }
        if (m_stateText) {
            m_stateText->setPlainText(QString("p = %1：找 '%2' → 没有，新建节点 %3，p 移到 %3")
                                      .arg(parentId).arg(QString(QChar(ch))).arg(newId));
        }
        auto edgeIt = m_edges.find(newId);
        if (edgeIt != m_edges.end()) {
            edgeIt->second->setColor(QColor(235, 155, 55));
            edgeIt->second->setPenWidth(3.2);
            edgeIt->second->update();
        }
        if (m_nodes[newId].node) {
            m_nodes[newId].node->color = kTrNew;
            m_nodes[newId].node->setHighlightColor(kTrNew);
            m_nodes[newId].node->update();
            if (m_animated) playScalePulse(m_nodes[newId].node, 1.3, 300);
        }
        m_cursorPointer->setOpacity(1);
        if (m_nodes[newId].node) {
            m_cursorPointer->setAnchorNode(m_nodes[newId].node);
            m_cursorPointer->syncToAnchor();
        }
    } else if (frame.type == ActionType::TR_END) {
        const int endNode = frame.u;
        ensureEndBlock(endNode);
        if (m_endBlocks.count(endNode)) {
            m_endBlocks[endNode]->setCustomValue("1");
            m_endBlocks[endNode]->color = kTrEnd;
            m_endBlocks[endNode]->update();
        }
        if (m_nodes.count(endNode) && m_nodes[endNode].node) {
            m_nodes[endNode].node->color = kTrEnd;
            m_nodes[endNode].node->update();
            if (m_animated) playScalePulse(m_nodes[endNode].node, 1.18, 240);
        }
        if (m_stateText) {
            m_stateText->setPlainText(QString("p = %1：单词结束，标记 end = 1").arg(endNode));
        }
    } else if (frame.type == ActionType::TR_DONE) {
        for (auto& n : m_nodes) {
            if (!n.node) continue;
            n.node->setHighlightColor(Qt::transparent);
            n.node->update();
        }
        for (auto& kv : m_edges) {
            if (kv.second->color == QColor(235, 155, 55)) {
                kv.second->setColor(kTrEdge);
                kv.second->setPenWidth(2.0);
                kv.second->update();
            }
        }
        m_cursorPointer->setOpacity(0);
        m_indexPointer->setOpacity(0);
        if (m_stateText) {
            m_stateText->setPlainText(QString("建树完成，共 %1 个节点").arg(frame.u));
        }
    }
}

void TrieModule::reset() {
    m_frames.clear();
    m_nodes.clear();
    m_edges.clear();
    m_endBlocks.clear();
    m_charCells.clear();
    m_words.clear();
    m_mathText = nullptr;
    m_wordText = nullptr;
    m_stateText = nullptr;
    m_charBlocks = nullptr;
    m_cursorPointer = nullptr;
    m_indexPointer = nullptr;
    m_valid = false;
}

void TrieModule::releaseSceneItems() {
    m_nodes.clear();
    m_edges.clear();
    m_endBlocks.clear();
    m_charCells.clear();
    m_mathText = nullptr;
    m_wordText = nullptr;
    m_stateText = nullptr;
    m_charBlocks = nullptr;
    m_cursorPointer = nullptr;
    m_indexPointer = nullptr;
}

#ifndef EULERMODULE_H
#define EULERMODULE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <QObject>
#include <QGraphicsTextItem>
#include <map>
#include <vector>

class EulerModule : public QObject, public IModule {
    Q_OBJECT
public:
    EulerModule();
    QString getModuleName() const override;
    QString getDefaultInput() const override;
