static void pump(int ms) {
    QEventLoop loop;
    QTimer::singleShot(ms, &loop, &QEventLoop::quit);
    loop.exec();
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    MainWindow w;
    w.resize(1400, 860);
    w.show();
    pump(700);
    QPixmap shot = w.grab();
    shot.save("ver_badge.png");
    printf("saved ver_badge.png %dx%d\n", shot.width(), shot.height());
    return 0;
}

