void PointerBlock::syncToAnchor() {
    QGraphicsItem* target = anchorItem();
    if (!target) return;
    if (m_anchor) {
        int index = 0;
        int total = 0;
        for (PointerBlock* p : m_anchor->pointerList) {
            if (!p || p->opacity() < 0.05) continue;
            ++total;
            if (p == this) index = total - 1;
        }
        if (total > 1) {
            double spread = 16.0;
            double delta = (index - (total - 1) / 2.0) * spread;
            setPos(target->pos() + m_anchorOffset + QPointF(delta, 0));
            return;
        }
    }
    setPos(target->pos() + m_anchorOffset);
}

void PointerBlock::syncToAnchor() {
    setPos(anchoredPos());
}

QPointF PointerBlock::anchoredPos() const {
    QGraphicsItem* target = anchorItem();
    if (!target) return pos();
    if (m_anchor) {
        int index = 0;
        int total = 0;
        for (PointerBlock* p : m_anchor->pointerList) {
            if (!p || p->opacity() < 0.05) continue;
            ++total;
            if (p == this) index = total - 1;
        }
        if (total > 1) {
            double spread = 16.0;
            double delta = (index - (total - 1) / 2.0) * spread;
            return target->pos() + m_anchorOffset + QPointF(delta, 0);
        }
    }
    return target->pos() + m_anchorOffset;
}

