static QImage renderScene(QGraphicsScene& scene) {
    QGraphicsView view(&scene);
    view.resize(1100, 820);
    view.show();
    pump(120);
    view.fitInView(scene.itemsBoundingRect().adjusted(-40, -40, 40, 40), Qt::KeepAspectRatio);
    pump(60);
    return view.grab().toImage();
}

static void cropScene(const QImage& shot, const QGraphicsScene& scene, const char* file,
                      QPointF scx, QPointF scy, int w, int h) {
    QGraphicsView* view = scene.views().isEmpty() ? nullptr : scene.views().first();
    if (!view) return;
    QPointF tl = view->mapFromScene(scx - QPointF(w / 2.0, h / 2.0));
    QImage sub = shot.copy(qMax(0, tl.x()), qMax(0, tl.y()), w, h);
    sub.scaled(w * 2, h * 2).save(file);
    printf("saved %s\n", file);
}

