static int g_fail = 0;

static void check(bool ok, const char* name) {
    printf("[%s] %s\n", ok ? "PASS" : "FAIL", name);
    if (!ok) g_fail++;
}

static void pump(int ms) {
    QEventLoop loop;
    QTimer::singleShot(ms, &loop, &QEventLoop::quit);
    loop.exec();
}

static PointerBlock* findPointer(QGraphicsScene& scene, const QString& label) {
    for (QGraphicsItem* item : scene.items()) {
        PointerBlock* p = dynamic_cast<PointerBlock*>(item);
        if (p && p->label == label) return p;
    }
    return nullptr;
}

static ArrayBlock* findArray(QGraphicsScene& scene, const QString& text) {
    for (QGraphicsItem* item : scene.items()) {
        ArrayBlock* b = dynamic_cast<ArrayBlock*>(item);
        if (b && b->customValue == text) return b;
    }
    return nullptr;
}

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    {
        QGraphicsScene scene;
        HashTableModule mod;
        mod.buildLayout(&scene, "4\n5\n3\n7\n11");
        auto frames = mod.runAlgorithm();
        for (const auto& f : frames) mod.renderFrame(f);
        PointerBlock* k = findPointer(scene, "k");
        check(k != nullptr, "hash pointer k exists");
        if (k) {
            ArrayBlock* slot = findArray(scene, "5");
            check(slot != nullptr, "hash slot holding key 5 exists");
            if (slot) {
                double dx = std::abs(k->pos().x() - (slot->pos().x() + slot->cellWidth() / 2.0));
                double dy = std::abs(k->pos().y() - (slot->pos().y() + 19.0));
                printf("k pos=(%.1f,%.1f) slot=(%.1f,%.1f) dx=%.1f dy=%.1f\n",
                       k->pos().x(), k->pos().y(), slot->pos().x(), slot->pos().y(), dx, dy);
                check(dx < 1.0, "k horizontally centered on the slot");
                check(dy < 1.0, "k arrow tip lands on the slot row");
                check(k->labelOffset().y() < 0, "k label sits above the shaft tail");
            }
        }
    }

    {
        QGraphicsScene scene;
        TrieModule mod;
        mod.buildLayout(&scene, "3\ncat\ncar\ndog");
        auto frames = mod.runAlgorithm();
        for (const auto& f : frames) mod.renderFrame(f);
        PointerBlock* i = findPointer(scene, "i");
        check(i != nullptr, "trie pointer i exists");
        if (i) {
            ArrayBlock* cell = findArray(scene, "c");
            check(cell != nullptr, "trie char cell holding c exists");
            if (cell) {
                double dx = std::abs(i->pos().x() - (cell->pos().x() + 27.0));
                double dy = std::abs(i->pos().y() - (cell->pos().y() + 19.0));
                printf("i pos=(%.1f,%.1f) cell=(%.1f,%.1f) dx=%.1f dy=%.1f\n",
                       i->pos().x(), i->pos().y(), cell->pos().x(), cell->pos().y(), dx, dy);
                check(dx < 1.0, "i horizontally centered on the cell");
                check(dy < 1.0, "i arrow tip lands on the cell row");
                check(i->labelOffset().y() < 0, "i label sits at the arrow tail");
            }
        }
    }

    {
        QGraphicsScene scene;
        PrimModule mod;
        mod.buildLayout(&scene, "6 9 1\n1 2 4\n1 3 3\n2 3 2\n2 4 5\n3 4 3\n3 5 6\n4 5 1\n4 6 7\n5 6 8");
        auto frames = mod.runAlgorithm();
        for (const auto& f : frames) mod.renderFrame(f);
        PointerBlock* u = findPointer(scene, "u");
        check(u != nullptr, "prim pointer u exists");
        if (u) {
            GraphNode* node = nullptr;
            for (QGraphicsItem* item : scene.items()) {
                GraphNode* n = dynamic_cast<GraphNode*>(item);
                if (n && n->id == 1) node = n;
            }
            check(node != nullptr, "prim node 1 exists");
            if (node) {
                double dx = std::abs(u->pos().x() - node->pos().x());
                printf("u pos=(%.1f,%.1f) node=(%.1f,%.1f) dx=%.1f dy=%.1f\n",
                       u->pos().x(), u->pos().y(), node->pos().x(), node->pos().y(),
                       dx, std::abs(u->pos().y() - node->pos().y()));
                check(dx < 1.0, "u aligned with the vertex horizontally");
                check(std::abs(u->pos().y() - node->pos().y()) < 30.0, "u arrow tip within the vertex circle");
            }
        }
    }

    printf("\n%s  fail=%d\n", g_fail == 0 ? "ALL PASS" : "HAS FAILURE", g_fail);
    return g_fail == 0 ? 0 : 1;
}

