static QImage shot(QGraphicsScene* scene) {
    QImage img(scene->sceneRect().size().toSize(), QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    scene->render(&p);
    return img;
}

static void dumpRow(const QImage& img, int y, int x0, int x1) {
    std::vector<int> cols;
    for (int x = x0; x < x1; ++x) {
        if (img.pixelColor(x, y).lightness() < 200) cols.push_back(x);
    }
    printf("row %d raw dark cols (%zu): ", y, cols.size());
    for (size_t i = 0; i < cols.size(); ++i) printf("%d ", cols[i]);
    printf("\n");
}

