    const double bBottom = h + gridH + 3.0;
    painter->setBrush(Qt::NoBrush);
    painter->setPen(QPen(barColor, 2.6, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
    const double arm = 13.0;
    const double lip = 6.0;
    painter->drawPolyline(QPolygonF({
        QPointF(m - 2.0, bTop), QPointF(m - 2.0 - arm, bTop), QPointF(m - 2.0 - arm, bTop + lip),
        QPointF(m - 2.0 - arm, bBottom - lip), QPointF(m - 2.0 - arm, bBottom), QPointF(m - 2.0, bBottom)}));
    painter->drawPolyline(QPolygonF({
        QPointF(m + gridW + 2.0, bTop), QPointF(m + gridW + 2.0 + arm, bTop),
        QPointF(m + gridW + 2.0 + arm, bTop + lip), QPointF(m + gridW + 2.0 + arm, bBottom - lip),
        QPointF(m + gridW + 2.0 + arm, bBottom), QPointF(m + gridW + 2.0, bBottom)}));
}

#ifndef POINTERGEOMETRY_H
