void ExgcdModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    long long a = 0;
    long long b = 0;
    if (tokens.size() >= 2) {
        a = tokens[0].toLongLong(&ok);
        const bool okA = ok && a >= 1 && a <= 100000;
        b = tokens[1].toLongLong(&ok);
        m_valid = okA && ok && b >= 1 && b <= 100000;
    }
    if (!m_valid) return;

    m_a = a;
    m_b = b;

    m_mathText = scene->addText(QString("扩展欧几里得：求 a·x + b·y = gcd(a, b)　（a = %1, b = %2）").arg(a).arg(b));
    m_mathText->setFont(UiFonts::mono(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(110, 18);

    m_stackTitle = scene->addText("递归调用栈（每一层是一对 a, b 与对应的 x, y）");
    m_stackTitle->setFont(UiFonts::cjk(12, true));
    m_stackTitle->setDefaultTextColor(QColor(60, 75, 95));
    m_stackTitle->setPos(110, 66);

    const double boxW = 116.0;
    const double boxH = 46.0;
    const double gapY = 96.0;

    long long ra = a;
    long long rb = b;
    int depth = 0;
    while (rb != 0 && depth < 12) {
        Level lv;
        lv.a = ra;
        lv.b = rb;
        const double y = 110.0 + depth * gapY;
        const double x = 240.0;

        QGraphicsTextItem* title = scene->addText(QString("第 %1 层").arg(depth + 1));
        title->setFont(UiFonts::cjk(11, true));
        title->setDefaultTextColor(QColor(90, 105, 125));
        title->setPos(110, y + 14);

        auto makeBox = [&](int id, const QString& label, const QColor& color) {
            ArrayBlock* box = new ArrayBlock(id, 0, label);
            box->setCellSize(boxW, boxH);
            box->setShowLabel(false);
            box->setValueFontSize(16);
            box->setCustomValue("—");
            box->color = color;
            box->setPos(x, y);
            scene->addItem(box);
            return box;
        };

        lv.aBox = makeBox(depth * 10 + 0, "a", kExA);
        lv.bBox = makeBox(depth * 10 + 1, "b", kExB);
        lv.xBox = makeBox(depth * 10 + 2, "x", kExX);
        lv.yBox = makeBox(depth * 10 + 3, "y", kExY);

        m_levels.push_back(lv);
        long long r = ra % rb;
        ra = rb;
        rb = r;
        ++depth;
    }

    m_noteText = scene->addText("");
    m_noteText->setFont(UiFonts::mono(14, true));
    m_noteText->setDefaultTextColor(QColor(200, 110, 40));
    m_noteText->setPos(110, 110.0 + static_cast<double>(m_levels.size()) * gapY + 10);

    m_ptrLevel = new PointerBlock("层", QColor(210, 80, 55));
    m_ptrLevel->setOpacity(0);
    m_ptrLevel->setDirection(PointerBlock::Left);
    m_ptrLevel->setLabelToRight(4.0);
    m_ptrLevel->setAnchorOffset(QPointF(-22.0, 0.0));
    scene->addItem(m_ptrLevel);
}

std::vector<AnimFrame> ExgcdModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    struct Frame {
        long long a;
        long long b;
        long long x;
        long long y;
    };
    std::vector<Frame> stack;
    stack.push_back({m_a, m_b, 0, 0});

    m_frames.push_back({ActionType::EX_RESET, 0, 0, 0, 0, {},
                        QString("开始递归：exgcd(%1, %2)").arg(m_a).arg(m_b),
                        QString("目标是求出 x, y 使 a·x + b·y = gcd(a, b)")});

    while (!stack.empty()) {
        Frame cur = stack.back();
        stack.pop_back();
        const int depth = static_cast<int>(m_levels.size()) - 1 - static_cast<int>(stack.size());
        m_frames.push_back({ActionType::EX_RECURSE, depth, static_cast<int>(cur.a), static_cast<int>(cur.b), 0, {},
                            QString("第 %1 层：exgcd(%2, %3)").arg(depth + 1).arg(cur.a).arg(cur.b),
                            QString("因为 %3 ≠ 0，继续递归 exgcd(%2, %3 %% %2)").arg(cur.a).arg(cur.b)});
        if (cur.b != 0) {
            stack.push_back({cur.b, cur.a % cur.b, 0, 0});
            continue;
        }
        m_frames.push_back({ActionType::EX_BASE, depth, static_cast<int>(cur.a), 1, 0, {},
                            QString("第 %1 层到达边界：b = 0，此时 x = 1, y = 0").arg(depth + 1),
                            QString("b = 0 ⇒ x = 1, y = 0")});
        long long x = 1;
        long long y = 0;
        m_frames.push_back({ActionType::EX_BACKTRACE, depth, static_cast<int>(cur.a), static_cast<int>(x), static_cast<int>(y), {},
                            QString("第 %1 层回溯：x = %2, y = %3").arg(depth + 1).arg(x).arg(y),
                            QString("边界层 x = 1, y = 0")});
        while (!stack.empty()) {
            Frame parent = stack.back();
            stack.pop_back();
            const long long q = parent.a / parent.b;
            const long long newX = y;
            const long long newY = x - q * y;
            const int pd = static_cast<int>(m_levels.size()) - 1 - static_cast<int>(stack.size());
            m_frames.push_back({ActionType::EX_BACKTRACE, pd, static_cast<int>(parent.a), static_cast<int>(newX), static_cast<int>(newY), {},
                                QString("回溯到第 %1 层：x = y' = %2，y = x' - (a/b)·y' = %3 - %4·%2 = %5")
                                    .arg(pd + 1).arg(newX).arg(x).arg(q).arg(y).arg(newY),
                                QString("x = y', y = x' - (a/b)·y'")});
            x = newX;
            y = newY;
        }
        m_frames.push_back({ActionType::EX_DONE, static_cast<int>(x), static_cast<int>(y), 0, 0, {},
                            QString("最终结果：%1·(%2) + %3·(%4) = gcd(%1, %3) = %5")
                                .arg(m_a).arg(x).arg(m_b).arg(y).arg(m_a),
                            QString("a·x + b·y = gcd(a, b)")});
        break;
    }
    return m_frames;
}

void ExgcdModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::EX_RESET) {
        for (auto& lv : m_levels) {
            if (lv.aBox) { lv.aBox->setCustomValue("—"); lv.aBox->color = kExA; lv.aBox->update(); }
            if (lv.bBox) { lv.bBox->setCustomValue("—"); lv.bBox->color = kExB; lv.bBox->update(); }
            if (lv.xBox) { lv.xBox->setCustomValue("—"); lv.xBox->color = kExX; lv.xBox->update(); }
            if (lv.yBox) { lv.yBox->setCustomValue("—"); lv.yBox->color = kExY; lv.yBox->update(); }
        }
        if (m_ptrLevel) m_ptrLevel->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText("");
            m_noteText->setDefaultTextColor(QColor(200, 110, 40));
        }
    } else if (frame.type == ActionType::EX_RECURSE) {
        Level* lv = levelAt(frame.u);
        if (lv) {
            if (lv->aBox) { lv->aBox->setCustomValue(QString::number(frame.v)); lv->aBox->update(); }
            if (lv->bBox) { lv->bBox->setCustomValue(QString::number(frame.val1)); lv->bBox->update(); }
            if (m_ptrLevel) {
                m_ptrLevel->setOpacity(1);
                retargetPointerTo(m_ptrLevel, lv->aBox, QPointF(-22.0, 0.0));
            }
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
    } else if (frame.type == ActionType::EX_BASE) {
        Level* lv = levelAt(frame.u);
        if (lv) {
            if (lv->bBox) { lv->bBox->setCustomValue("0"); lv->bBox->color = kExBase; lv->bBox->update(); }
            if (lv->xBox) { lv->xBox->setCustomValue("1"); lv->xBox->color = kExBase; lv->xBox->update(); }
            if (lv->yBox) { lv->yBox->setCustomValue("0"); lv->yBox->color = kExBase; lv->yBox->update(); }
            if (m_animated) {
                if (lv->xBox) playScalePulse(lv->xBox, 1.18, 240);
                if (lv->yBox) playScalePulse(lv->yBox, 1.18, 240);
            }
            if (m_ptrLevel) {
                m_ptrLevel->setOpacity(1);
                retargetPointerTo(m_ptrLevel, lv->aBox, QPointF(-22.0, 0.0));
            }
        }
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(190, 120, 30));
        }
    } else if (frame.type == ActionType::EX_BACKTRACE) {
        Level* lv = levelAt(frame.u);
        if (lv) {
            if (lv->xBox) {
                lv->xBox->setCustomValue(QString::number(frame.val1));
                lv->xBox->color = kExX;
                lv->xBox->update();
            }
            if (lv->yBox) {
                lv->yBox->setCustomValue(QString::number(frame.val2));
                lv->yBox->color = kExY;
                lv->yBox->update();
            }
            if (m_animated) {
                if (lv->xBox) playScalePulse(lv->xBox, 1.14, 220);
                if (lv->yBox) playScalePulse(lv->yBox, 1.14, 220);
            }
            if (m_ptrLevel) {
                m_ptrLevel->setOpacity(1);
                retargetPointerTo(m_ptrLevel, lv->aBox, QPointF(-22.0, 0.0));
            }
        }
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(70, 110, 170));
        }
    } else if (frame.type == ActionType::EX_DONE) {
        Level* lv = levelAt(0);
        if (lv) {
            if (lv->xBox) { lv->xBox->setCustomValue(QString::number(frame.u)); lv->xBox->color = kExDone; lv->xBox->update(); }
            if (lv->yBox) { lv->yBox->setCustomValue(QString::number(frame.v)); lv->yBox->color = kExDone; lv->yBox->update(); }
            if (m_animated) {
                if (lv->xBox) playScalePulse(lv->xBox, 1.26, 320);
                if (lv->yBox) playScalePulse(lv->yBox, 1.26, 320);
            }
        }
        if (m_ptrLevel) m_ptrLevel->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
    }
}

