QString StringHashModule::getInputHint() const {
    return "第一行输入主串 s（长度 2~12，只含小写字母）\n"
           "第二行输入模式串 t（长度 1~5，只含小写字母）\n"
           "先算前缀哈希 h[i] = h[i-1]·p + 字符码，再验证单个字符哈希 O(1) 判定子串是否等于模式串";
