    m_ptrI->setLabelAtTail(8.0);
    scene->addItem(m_ptrI);
}

std::vector<AnimFrame> StringHashModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    const int n = static_cast<int>(m_s.size());
    const int m = static_cast<int>(m_pattern.size());

    m_frames.push_back({ActionType::STH_RESET, 0, 0, 0, 0, {},
                        QString("初始化：准备计算前缀哈希"),
                        QString("p = %1, mod = %2").arg(kBase).arg(kMod)});

    unsigned long long h = 0;
    for (int i = 0; i < n; ++i) {
        const unsigned long long code = static_cast<unsigned long long>(m_s.at(i).toLatin1());
        const unsigned long long prev = h;
        h = (h * kBase + code) % kMod;
        m_frames.push_back({ActionType::STH_PREP, i + 1, static_cast<int>(prev), static_cast<int>(h),
                            static_cast<int>(code), {},
                            QString("h[%1] = h[%2]·%3 + '%4' 的字符码 %5 = %6")
                                .arg(i + 1).arg(i).arg(kBase).arg(m_s.at(i)).arg(code).arg(h),
                            QString("h[i] = (h[i-1]·p + code) %% mod")});
    }

    for (int e = 0; e <= n; ++e) {
        m_frames.push_back({ActionType::STH_POW, e, static_cast<int>(powBase(e)), 0, 0, {},
                            QString("预处理 p[%1] = %2^%3 mod %4 = %5").arg(e).arg(kBase).arg(e).arg(kMod).arg(powBase(e)),
                            QString("p[k] = p[k-1]·p mod mod")});
    }

    unsigned long long ht = 0;
    for (int i = 0; i < m; ++i) {
        const unsigned long long code = static_cast<unsigned long long>(m_pattern.at(i).toLatin1());
        ht = (ht * kBase + code) % kMod;
    }
    m_frames.push_back({ActionType::STH_QUERY, 0, static_cast<int>(ht), m, 0, {},
                        QString("模式串 \"%1\" 的哈希值 ht = %2").arg(m_pattern).arg(ht),
                        QString("ht = hash(t)")});

    for (int i = 0; i + m <= n; ++i) {
        const unsigned long long left = i == 0 ? 0 : (m_prefix[i] + kMod) % kMod;
        const unsigned long long sub = (m_prefix[i + m] + kMod - (left * powBase(m)) % kMod) % kMod;
        const bool hit = sub == ht;
        m_frames.push_back({ActionType::STH_MATCH, i + 1, i + m, static_cast<int>(sub), hit ? 1 : 0, {},
                            hit ? QString("子串 s[%1..%2] 哈希等于 ht，匹配成功").arg(i + 1).arg(i + m)
                                : QString("子串 s[%1..%2] 哈希 %3 ≠ ht %4，不匹配")
                                    .arg(i + 1).arg(i + m).arg(sub).arg(ht),
                            QString("h[r] - h[l-1]·p^(r-l+1) = %1").arg(sub)});
    }

    m_frames.push_back({ActionType::STH_DONE, n, static_cast<int>(ht), 0, 0, {},
                        QString("字符串哈希演示完成，单个子串判定只需 O(1)"),
                        QString("预处理 O(n)，每次比较 O(1)")});
    return m_frames;
}

void StringHashModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::STH_RESET) {
        for (auto* b : m_charCells) { b->color = kShIdle; b->update(); }
        for (auto* b : m_prefixBlocks) { b->setCustomValue("0"); b->color = kShIdle; b->update(); }
        for (auto* b : m_powBlocks) { b->setCustomValue("0"); b->color = kShIdle; b->update(); }
        for (auto* b : m_matchBlocks) { b->showValue = false; b->color = kShIdle; b->update(); }
        if (m_ptrI) m_ptrI->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText("");
            m_noteText->setDefaultTextColor(QColor(200, 110, 40));
        }
    } else if (frame.type == ActionType::STH_PREP) {
        for (auto* b : m_prefixBlocks) {
            if (b->color == kShPrefix) { b->color = kShIdle; b->update(); }
        }
        const int index = frame.u - 1;
        if (index >= 0 && index < static_cast<int>(m_prefixBlocks.size())) {
            m_prefixBlocks[index]->setCustomValue(QString::number(frame.val1));
            m_prefixBlocks[index]->color = kShPrefix;
            m_prefixBlocks[index]->update();
            if (m_animated) playScalePulse(m_prefixBlocks[index], 1.16, 240);
        }
        if (index >= 0 && index < static_cast<int>(m_charCells.size())) {
            m_charCells[index]->color = kShScan;
            m_charCells[index]->update();
            if (m_ptrI) {
                m_ptrI->setOpacity(1);
                retargetPointerTo(m_ptrI, m_charCells[index], PointerGeometry::aboveCell(56.0, 40.0));
            }
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
    } else if (frame.type == ActionType::STH_POW) {
        const int e = frame.u;
        if (e >= 0 && e < static_cast<int>(m_powBlocks.size())) {
            m_powBlocks[e]->setCustomValue(QString::number(frame.val1));
            m_powBlocks[e]->color = kShPow;
            m_powBlocks[e]->update();
            if (m_animated) playScalePulse(m_powBlocks[e], 1.12, 200);
        }
        if (m_noteText) {
            m_noteText->setPlainText(QString("p[%1] = %2").arg(e).arg(frame.val1));
        }
    } else if (frame.type == ActionType::STH_QUERY) {
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(70, 110, 170));
        }
    } else if (frame.type == ActionType::STH_MATCH) {
        const int l = frame.v;
        const int r = frame.u;
        for (auto* b : m_matchBlocks) { b->showValue = false; b->color = kShIdle; b->update(); }
        for (auto* b : m_charCells) {
            if (b->color == kShScan) { b->color = kShIdle; b->update(); }
        }
        const bool hit = frame.val2 == 1;
        for (int i = l; i < r && i < static_cast<int>(m_matchBlocks.size()); ++i) {
            m_matchBlocks[i]->showValue = true;
            m_matchBlocks[i]->value = static_cast<int>(m_s.at(i).toLatin1());
            m_matchBlocks[i]->color = hit ? kShHit : kShScan;
            m_matchBlocks[i]->update();
        }
        for (int i = l; i < r && i < static_cast<int>(m_charCells.size()); ++i) {
            m_charCells[i]->color = hit ? kShHit : kShScan;
            m_charCells[i]->update();
        }
        if (m_ptrI && l < static_cast<int>(m_charCells.size())) {
            m_ptrI->setOpacity(1);
            retargetPointerTo(m_ptrI, m_charCells[l], PointerGeometry::aboveCell(56.0, 40.0));
        }
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(hit ? QColor(40, 140, 70) : QColor(190, 100, 60));
        }
    } else if (frame.type == ActionType::STH_DONE) {
        if (m_ptrI) m_ptrI->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
    }
}

