static bool pointerOutsideCells(QGraphicsScene& scene, const char* label, const char* name) {
    bool found = false;
    for (QGraphicsItem* item : scene.items()) {
        PointerBlock* ptr = qgraphicsitem_cast<PointerBlock*>(item);
        if (!ptr || ptr->label != QLatin1String(label)) continue;
        if (ptr->opacity() < 0.05) continue;
        ArrayBlock* cell = qgraphicsitem_cast<ArrayBlock*>(ptr->anchorItem());
        if (!cell) continue;
        found = true;
        const double tipX = ptr->pos().x();
        const double tipY = ptr->pos().y();
        const double cellLeft = cell->pos().x();
        const double cellRight = cellLeft + cell->cellWidth();
        const double cellTop = cell->pos().y();
        const double cellBottom = cellTop + cell->cellHeight();
        bool outside = false;
        if (ptr->direction() == PointerBlock::Down) outside = tipY <= cellTop - 1.0;
        else if (ptr->direction() == PointerBlock::Up) outside = tipY >= cellBottom + 1.0;
        else if (ptr->direction() == PointerBlock::Right) outside = tipX <= cellLeft - 1.0;
        else outside = tipX >= cellRight + 1.0;
        printf("  %s tip=(%.1f,%.1f) cell=[%.1f..%.1f, %.1f..%.1f] dir=%d outside=%d\n",
               label.toUtf8().constData(), tipX, tipY, cellLeft, cellRight, cellTop, cellBottom,
               static_cast<int>(ptr->direction()), outside ? 1 : 0);
        if (!outside) {
            printf("[FAIL] %s\n", name);
            g_fail++;
        }
    }
    if (!found) {
        printf("[FAIL] %s (pointer not found)\n", name);
        g_fail++;
    }
    return found;
}

