P1 = 131
M1 = 998244353


def get_hash(h, l, r, p):
    return (h[r] - h[l - 1] * p[r - l + 1] % M1 + M1) % M1


def solve(s1, s2):
    n1, n2 = len(s1), len(s2)
    p = [0] * (max(n1, n2) + 1)
    h1 = [0] * (n1 + 1)
    h2 = [0] * (n2 + 1)
    p[0] = 1
    for i in range(1, max(n1, n2) + 1):
        p[i] = p[i - 1] * P1 % M1
    for i in range(1, n1 + 1):
        h1[i] = (h1[i - 1] * P1 + ord(s1[i - 1])) % M1
    for i in range(1, n2 + 1):
        h2[i] = (h2[i - 1] * P1 + ord(s2[i - 1])) % M1
    ans = 0
    for length in range(min(n1, n2), 0, -1):
        if get_hash(h1, 1, length, p) == get_hash(h2, n2 - length + 1, n2, p):
            ans = length
            break
        if get_hash(h2, 1, length, p) == get_hash(h1, n1 - length + 1, n1, p):
            ans = length
            break
    return ans


