HuffmanTreeModule::HuffNode* HuffmanTreeModule::nodeAt(int id) {
    if (id < 0 || id >= static_cast<int>(m_nodes.size())) return nullptr;
    return &m_nodes[id];
}

void HuffmanTreeModule::shiftSubtree(int root, int delta) {
    if (root < 0 || delta == 0) return;
    std::vector<int> stack;
    stack.push_back(root);
    while (!stack.empty()) {
        const int id = stack.back();
        stack.pop_back();
        auto it = m_treeNodes.find(id);
        if (it != m_treeNodes.end() && it->second) {
            it->second->setPos(it->second->pos() + QPointF(0, delta));
        }
        HuffNode* node = nodeAt(id);
        if (!node) continue;
        if (node->left >= 0) stack.push_back(node->left);
        if (node->right >= 0) stack.push_back(node->right);
    }
}

void HuffmanTreeModule::computeLayout() {
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        node->level = 0;
    }
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node || node->parent < 0) continue;
        HuffNode* p = nodeAt(node->parent);
        if (p) node->level = p->level + 1;
    }

    int minLevel = 0, maxLevel = 0;
    bool first = true;
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        if (first) {
            minLevel = maxLevel = node->level;
            first = false;
        } else {
            minLevel = qMin(minLevel, node->level);
            maxLevel = qMax(maxLevel, node->level);
        }
    }
    m_levelMin = minLevel;
    m_levelMax = maxLevel;

    std::vector<std::vector<int>> rows(maxLevel - minLevel + 1);
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        rows[node->level - minLevel].push_back(node->id);
    }

    for (auto& row : rows) {
        std::sort(row.begin(), row.end(), [this](int a, int b) {
            const HuffNode* na = nodeAt(a);
            const HuffNode* nb = nodeAt(b);
            if (!na || !nb) return a < b;
            if (na->weight != nb->weight) return na->weight < nb->weight;
            return a < b;
        });
    }

    const double span = qMax(1, static_cast<int>(rows.back().size())) * kBaseGap;
    for (size_t r = 0; r < rows.size(); ++r) {
        const double y = kTreeBottom - static_cast<double>(r) * kLevelH;
        const std::vector<int>& row = rows[r];
        const double rowSpan = qMax(1, static_cast<int>(row.size())) * kBaseGap;
        const double left = kTreeCenterX - rowSpan / 2.0 + kBaseGap / 2.0;
        for (size_t k = 0; k < row.size(); ++k) {
            auto it = m_treeNodes.find(row[k]);
            if (it == m_treeNodes.end() || !it->second) continue;
            const double x = left + static_cast<double>(k) * kBaseGap;
            it->second->setPos(x, y);
        }
    }
    Q_UNUSED(span);
}

void HuffmanTreeModule::applyLayout(bool animate) {
    std::vector<QGraphicsItem*> movers;
    std::vector<QPointF> goals;
    std::vector<QPointF> starts;
    for (auto& kv : m_treeNodes) {
        if (!kv.second) continue;
        movers.push_back(kv.second);
        starts.push_back(kv.second->pos());
        goals.push_back(kv.second->pos());
    }
    Q_UNUSED(movers);
    Q_UNUSED(goals);
    Q_UNUSED(starts);
    Q_UNUSED(animate);
}

void HuffmanTreeModule::ensureTreeNode(int id) {
    if (m_treeNodes.count(id)) return;
    HuffNode* node = nodeAt(id);
    if (!node) return;
    GraphNode* item = new GraphNode(id);
    item->color = node->original ? kHfLeaf : kHfMerge;
    item->setCustomValueText(QString::number(node->weight));
    m_scene->addItem(item);
    m_treeNodes[id] = item;
    node->item = item;
}

void HuffmanTreeModule::renderArray(const std::vector<int>& alive, int highlightA, int highlightB) {
    for (size_t i = 0; i < m_arrayCells.size(); ++i) {
        ArrayBlock* cell = m_arrayCells[i];
        if (!cell) continue;
        const int id = (i < alive.size()) ? alive[i] : -1;
        if (id < 0) {
            cell->color = QColor(238, 240, 245);
        } else {
            const HuffNode* node = nodeAt(id);
            cell->setCustomValue(QString::number(node ? node->weight : 0));
            cell->color = kHfSorted;
            if (id == highlightA || id == highlightB) cell->color = kHfPick;
        }
        cell->update();
    }
}

void HuffmanTreeModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!tokens.isEmpty()) {
        n = tokens[0].toInt(&ok);
        m_valid = ok && n >= 2 && n <= 8 && tokens.size() >= n + 1;
        if (m_valid) {
            for (int i = 0; i < n; ++i) {
                const long long value = tokens[i + 1].toLongLong(&ok);
                if (!ok || value < 0 || value > 9999) {
                    m_valid = false;
                    break;
                }
                HuffNode node;
                node.id = i;
                node.weight = value;
                node.original = true;
                m_nodes.push_back(node);
            }
        }
    }

    m_mathText = scene->addText(m_valid ? "哈夫曼树：每次取权值最小的两个节点合并，父节点权值 = 两者之和"
                                        : "输入格式：n，随后输入 n 个权值；2 <= n <= 8");
    m_mathText->setFont(UiFonts::mixed(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(110, 18);
    if (!m_valid) return;

    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        ArrayBlock* cell = new ArrayBlock(i, 0, QString::number(i));
        cell->setCellSize(kCellW, kCellH);
        cell->setShowLabel(false);
        cell->color = kHfLeaf;
        cell->setCustomValue(QString::number(m_nodes[i].weight));
        cell->setValueFontSize(14);
        cell->setPos(kArrayLeft + static_cast<double>(i) * kCellW, kArrayY);
        scene->addItem(cell);
        m_arrayCells.push_back(cell);
    }

    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        ensureTreeNode(i);
    }
    computeLayout();

    m_arrayTitle = scene->addText("频率数组 a[]");
    m_arrayTitle->setFont(UiFonts::cjk(12, true));
    m_arrayTitle->setDefaultTextColor(QColor(60, 75, 95));
    m_arrayTitle->setPos(kArrayLeft - 30, kArrayY - 28);

