void HuffmanTreeModule::computePositions(const std::map<int, int>& rows, const std::map<int, int>& cols,
                                         std::map<int, QPointF>& out) const {
    out.clear();
    const int count = static_cast<int>(m_nodes.size());
    if (count == 0) return;

    int maxRow = 0;
    for (const auto& kv : rows) maxRow = qMax(maxRow, kv.second);

    std::map<int, int> rowSize;
    for (const auto& kv : rows) ++rowSize[kv.second];

    const double width = qMax(1, static_cast<int>(m_sortedLeaves.size())) * kBaseGap;
    const double left = kTreeCenterX - width / 2.0 + kBaseGap / 2.0;

    for (int id = 0; id < count; ++id) {
        const int row = rows.count(id) ? rows.at(id) : 0;
        const int slot = cols.count(id) ? cols.at(id) : id;
        const double y = kTreeBottom - static_cast<double>(row) * kLevelH;
        double x = left + static_cast<double>(slot) * kBaseGap;
        if (!m_nodes[id].original) {
            const HuffmanNodeData* node = nodeAt(id);
            const int l = node->left;
            const int r = node->right;
            const double lx = (l >= 0 && cols.count(l)) ? left + static_cast<double>(cols.at(l)) * kBaseGap : x;
            const double rx = (r >= 0 && cols.count(r)) ? left + static_cast<double>(cols.at(r)) * kBaseGap : x;
            x = (lx + rx) / 2.0;
        }
        out[id] = QPointF(x, y);
    }
    Q_UNUSED(rowSize);
    Q_UNUSED(maxRow);
}

