    m_frames.clear();
    m_nodes.clear();
    m_plan.clear();
    m_sortedLeaves.clear();
    m_forest.clear();
    m_arrayCells.clear();
    m_codeRows.clear();
    m_codeFreqCells.clear();
    m_codeCells.clear();
    m_codeLenCells.clear();
    m_wplCells.clear();
    m_wplSumCell = nullptr;
    m_treeNodes.clear();
    m_childEdges.clear();
    m_xPos.clear();
    m_yPos.clear();
    m_codeMap.clear();
    m_mathText = nullptr;
    m_noteText = nullptr;
    m_phaseText = nullptr;
    m_resultText = nullptr;
    m_arrayTitle = nullptr;
    m_tableTitle = nullptr;
    m_tableHead1 = nullptr;
    m_tableHead2 = nullptr;
