#ifndef HUFFMANTREEMODULE_H
#define HUFFMANTREEMODULE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <QObject>
#include <QGraphicsTextItem>
#include <map>
#include <vector>

struct HuffmanNodeData {
    int id = 0;
    long long weight = 0;
    int left = -1;
    int right = -1;
    int parent = -1;
    bool original = true;
    int level = 0;
    double x = 0.0;
    GraphNode* item = nullptr;
};

struct HuffmanMergeStep {
    int a = 0;
    int b = 0;
    int parent = 0;
    int kind = 0;
    int parentLevel = 0;
    int liftChild = -1;
    int liftDelta = 0;
    std::map<int, int> levelsAfterLift;
    std::map<int, int> levelsAfter;
};

struct HuffmanCodeRow {
    int leafId = 0;
    int originalIndex = 0;
    long long weight = 0;
    QString code;
    int codeLength = 0;
};

class HuffmanTreeModule : public QObject, public IModule {
    Q_OBJECT
public:
    HuffmanTreeModule();
    QString getModuleName() const override;
    QString getDefaultInput() const override;
    QString getInputHint() const override;
    void buildLayout(QGraphicsScene* scene, const QString& inputData) override;
    std::vector<AnimFrame> runAlgorithm() override;
    void renderFrame(const AnimFrame& frame) override;
    void reset() override;
    void releaseSceneItems() override;

private:
    static constexpr double kNodeR = 21.0;
    static constexpr double kCellW = 64.0;
    static constexpr double kCellH = 44.0;
    static constexpr double kArrayY = 158.0;
    static constexpr double kArrayLeft = 60.0;
    static constexpr double kCenterX = 300.0;
    static constexpr double kLeafSpan = 64.0;
    static constexpr double kLeafRowY = 618.0;
    static constexpr double kTreeTopY = 268.0;
    static constexpr double kTableX = 566.0;
    static constexpr double kTableCol1 = 72.0;
    static constexpr double kTableCol2 = 118.0;
    static constexpr double kTableCol3 = 58.0;
    static constexpr double kTableRowH = 34.0;
    static constexpr double kTableTop = 330.0;
    static constexpr double kWplCellW = 68.0;
    static constexpr double kWplCellH = 44.0;
    static constexpr double kWplY = 690.0;

    HuffmanNodeData* nodeAt(int id);
    const HuffmanNodeData* nodeAt(int id) const;
    void computeTree();
    void simulateLayout();
    void computeXPositions();
    void computeCodes();
    void applyLevelMap(const std::map<int, int>& levels, int duration);
    void refreshArrayColors(int used);
    void buildCodeTable();
    void clearCodeTable();
    void clearWplRow();
    void setLeafCode(int leafId, const QString& code);
    void revealPathLabels(int leafId);
    void shiftSubtree(int id, int delta, std::map<int, int>& levels) const;
    double yOfLevel(int level) const;
    double xOf(int id) const;

    std::vector<AnimFrame> m_frames;
    std::vector<HuffmanNodeData> m_nodes;
    std::vector<HuffmanMergeStep> m_plan;
    std::vector<int> m_sortedLeaves;
    std::vector<int> m_forest;
    std::vector<ArrayBlock*> m_arrayCells;
    std::vector<HuffmanCodeRow> m_codeRows;
    std::vector<ArrayBlock*> m_codeFreqCells;
    std::vector<ArrayBlock*> m_codeCells;
    std::vector<ArrayBlock*> m_codeLenCells;
    std::vector<ArrayBlock*> m_wplCells;
    ArrayBlock* m_wplSumCell = nullptr;
    std::map<int, GraphNode*> m_treeNodes;
