        HuffmanNodeData* node = nodeAt(id);
        if (!node) return 0;
        if (node->original) {
            node->slot = 0;
            return 1;
        }
        const int leftCount = assign(node->left);
        assign(node->right);
        return leftCount + countLeaves(node->right);
    };
    Q_UNUSED(assign);
}

