void ExgcdModule::computeChain() {
    m_rem.clear();
    m_quot.clear();
    m_rows.clear();

    long long ra = m_a;
    long long rb = m_b;
    while (rb != 0) {
        ExgcdStepRow row;
        row.dividend = ra;
        row.divisor = rb;
        row.quotient = ra / rb;
        row.remainder = ra % rb;
        m_rows.push_back(row);
        m_rem.push_back(row.remainder);
        m_quot.push_back(row.quotient);
        ra = rb;
        rb = row.remainder;
    }
    m_gcd = ra;
}

void ExgcdModule::buildBackSteps() {
    m_backSteps.clear();

    std::vector<std::pair<long long, long long>> coeffs;
    coeffs.push_back({1, 0});
    coeffs.push_back({0, 1});
    for (size_t i = 0; i < m_quot.size(); ++i) {
        const long long q = m_quot[i];
        const long long nx = coeffs[i + 1].first;
        const long long ny = coeffs[i + 2].first - q * coeffs[i + 1].first;
        coeffs.push_back({nx, ny});
    }
    const size_t last = coeffs.size() - 1;
    m_x = coeffs[last].first;
    m_y = coeffs[last].second;

    QString current = QString("1 = %1 × %2").arg(m_gcd).arg(m_rem.isEmpty() ? m_gcd : m_rem.back());

    for (size_t k = m_rem.size(); k > 0; --k) {
        const long long rem = m_rem[k - 1];
        const long long q = m_quot[k - 1];
        const long long nextRem = (k >= 2) ? m_rem[k - 2] : m_gcd;

        ExgcdBackStep step;
        step.line = current;

        QString substituted;
        if (k >= 2) {
            substituted = QString("1 = %1 × %2 - %3 × %4")
                              .arg(m_quot[k - 1] + 1)
                              .arg(nextRem)
                              .arg(m_quot[k - 2] + 1)
                              .arg(rem);
        } else {
            substituted = QString("1 = %1 × %2").arg(nextRem);
        }
        step.substituted = substituted;
        step.simplified = simplifiedForm(coeffs, k);
        m_backSteps.push_back(step);
        current = step.simplified;
    }
}

QString ExgcdModule::simplifiedForm(const std::vector<std::pair<long long, long long>>& coeffs, size_t k) const {
    const long long ca = coeffs[k].first;
    const long long cb = coeffs[k].second;
    QStringList parts;
    if (ca != 0) parts << QString("%1 × %2").arg(ca).arg(m_a);
    if (cb != 0) parts << QString("%1 × %2").arg(cb).arg(m_b);
    if (parts.isEmpty()) return "1 = 0";
    return "1 = " + parts.join(" + ");
}

