void ExgcdModule::computeChain() {
    m_rows.clear();
    m_chain.clear();

    long long ra = m_a;
    long long rb = m_b;
    while (rb != 0) {
        ExgcdStepRow row;
        row.dividend = ra;
        row.divisor = rb;
        row.quotient = ra / rb;
        row.remainder = ra % rb;
        m_rows.push_back(row);
        m_chain.push_back(ra);
        ra = rb;
        rb = row.remainder;
    }
    m_chain.push_back(ra);
    m_gcd = ra;
}

QString ExgcdModule::formatOneTerm(long long coef, long long value) const {
    if (coef == 0) return QString();
    if (coef == 1) return QString::number(value);
    if (coef == -1) return QString("- %1").arg(value);
    return QString("%1 × %2").arg(coef).arg(value);
}

QString ExgcdModule::formatCoefs(const std::map<int, long long>& coefs,
                                  const std::map<int, long long>& chain) const {
    QStringList parts;
    for (const auto& kv : coefs) {
        const QString term = formatOneTerm(kv.second, chain.count(kv.first) ? chain.at(kv.first) : 0);
        if (term.isEmpty()) continue;
        parts << term;
    }
    if (parts.isEmpty()) return "0";
    QString out = parts.first();
    for (int i = 1; i < parts.size(); ++i) {
        out += (parts[i].startsWith("-") ? " - " : " + ") + parts[i].mid(parts[i].startsWith("-") ? 1 : 0);
    }
    return out;
}

void ExgcdModule::buildBackSteps() {
    m_backSteps.clear();

    std::map<int, long long> chain;
    for (size_t i = 0; i < m_chain.size(); ++i) {
        chain[static_cast<int>(i)] = m_chain[i];
    }
    const int n = static_cast<int>(m_rows.size());

    std::vector<std::map<int, long long>> coefTable;
    coefTable.push_back({{0, 1}});
    coefTable.push_back({{1, 1}});
    for (int i = 0; i < n; ++i) {
        const long long q = m_rows[i].quotient;
        std::map<int, long long> next;
        next[static_cast<int>(i + 1)] = coefTable[i + 1].count(static_cast<int>(i + 1))
                                            ? coefTable[i + 1].at(static_cast<int>(i + 1)) : 0;
        const long long ca = coefTable[i + 2].count(static_cast<int>(i + 2))
                                 ? coefTable[i + 2].at(static_cast<int>(i + 2)) : 0;
        const long long cb = coefTable[i + 1].count(static_cast<int>(i + 1))
                                 ? coefTable[i + 1].at(static_cast<int>(i + 1)) : 0;
        next[static_cast<int>(i + 2)] = ca - q * cb;
        coefTable.push_back(next);
    }

    const size_t last = static_cast<size_t>(n) + 1;
    m_x = coefTable[last].count(0) ? coefTable[last].at(0) : 0;
    m_y = coefTable[last].count(1) ? coefTable[last].at(1) : 0;

    for (int k = n; k >= 1; --k) {
        ExgcdBackStep step;
        const long long rk = m_chain[k];
        const long long rk1 = m_chain[k - 1];
        const long long q = m_rows[k - 1].quotient;

        const std::map<int, long long> cur = coefTable[static_cast<size_t>(k)];
        const std::map<int, long long> prev = coefTable[static_cast<size_t>(k - 1)];
        const std::map<int, long long> prev2 = coefTable[static_cast<size_t>(k - 2)];

        const QString curExpr = formatCoefs(cur, chain);
        const QString prevExpr = formatCoefs(prev, chain);

        step.lhs = QString("1 = %1 × %2 - %3 × %4").arg(q + 1).arg(rk1).arg(q).arg(rk);
        step.rhs = QString("1 = %1").arg(curExpr);
        if (k >= 2) {
            step.lhs += QString(" = %1 × %2 - %3 × %4")
                            .arg(q + 1).arg(rk1).arg(q).arg(rk);
            step.rhs = QString("1 = %1").arg(curExpr);
        }
        Q_UNUSED(prev2);
        Q_UNUSED(prevExpr);
        m_backSteps.push_back(step);
    }
}

