void ExgcdModule::computeChain() {
    m_rows.clear();
    m_chain.clear();

    long long r0 = m_b;
    long long r1 = m_a;
    m_chain.push_back(r0);
    m_chain.push_back(r1);
    while (r1 != 0) {
        const long long q = r0 / r1;
        const long long r2 = r0 % r1;
        ExgcdStepRow row;
        row.dividend = r0;
        row.divisor = r1;
        row.quotient = q;
        row.remainder = r2;
        m_rows.push_back(row);
        m_chain.push_back(r2);
        r0 = r1;
        r1 = r2;
    }
    m_gcdIndex = static_cast<int>(m_chain.size()) - 2;
    m_gcd = m_chain[m_gcdIndex];
}

QString ExgcdModule::renderCoefs(const std::map<int, long long>& coefs, int substIndex) const {
    QStringList parts;
    for (auto it = coefs.rbegin(); it != coefs.rend(); ++it) {
        const int idx = it->first;
        const long long coef = it->second;
        if (coef == 0) continue;
        const long long value = (idx >= 0 && idx < static_cast<int>(m_chain.size()))
                                    ? m_chain[idx] : 0;
        QString term;
        if (idx == substIndex && idx >= 2) {
            const long long inner = m_chain[idx - 1];
            const long long q = m_rows[idx - 1].quotient;
            term = QString("(%1 - %2 × %3)")
                       .arg(inner)
                       .arg(q)
                       .arg(value);
        } else {
            term = QString::number(value);
        }
        if (coef == 1) parts << term;
        else if (coef == -1) parts << ("-" + term);
        else parts << QString("%1 × %2").arg(coef).arg(term);
    }
    if (parts.isEmpty()) return "0";
    QString out = parts.first();
    for (int i = 1; i < parts.size(); ++i) {
        if (parts[i].startsWith("-")) out += " " + parts[i];
        else out += " + " + parts[i];
    }
    return out;
}

void ExgcdModule::buildBackSteps() {
    m_backSteps.clear();

    std::map<int, long long> coefs;
    coefs[m_gcdIndex] = 1;

    for (int j = m_gcdIndex; j >= 2; --j) {
        auto it = coefs.find(j);
        if (it == coefs.end() || it->second == 0) continue;

        ExgcdBackStep step;
        const QString substituted = renderCoefs(coefs, j);
        const QString simplified = renderCoefs(coefs, -1);

        const long long coef = it->second;
        const long long q = m_rows[j - 1].quotient;
        coefs[j - 2] += coef;
        coefs[j - 1] -= coef * q;
        coefs[j] = 0;

        step.lhs = QString("1 = %1").arg(substituted);
        step.rhs = QString("1 = %1").arg(simplified);
        step.substituted = substituted;
        step.simplified = simplified;
        m_backSteps.push_back(step);
    }

    m_x = coefs.count(1) ? coefs.at(1) : 0;
    m_y = coefs.count(0) ? -coefs.at(0) : 0;
}

