            if (m_animated) {
                const QPointF from = QPointF(40, target->pos().y() - 22);
                playTextFlight(text, from, QPointF(40, target->pos().y()), 13, kExHi, 460);
            }
        }
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(kExHi);
        }
        return;
    }

    if (frame.type == ActionType::EX_DONE) {
        if (m_ptrRow) m_ptrRow->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(kExOk);
        }
        if (m_resultText) {
            m_resultText->setPlainText(m_inverseMode
                                           ? QString("结论：%1 在模 %2 意义下的乘法逆元是 %3")
                                                 .arg(m_a).arg(m_b).arg(frame.u)
                                           : QString("结论：%1·(%2) + %3·(%4) = %5")
                                                 .arg(m_a).arg(frame.u).arg(m_b).arg(frame.v).arg(m_gcd));
            m_resultText->setDefaultTextColor(kExOk);
        }
    }
}

void ExgcdModule::reset() {
    m_frames.clear();
    m_rows.clear();
    m_chain.clear();
    m_backSteps.clear();
    clearLayoutBlocks();
    m_mathText = nullptr;
    m_a = 0;
    m_b = 0;
    m_gcd = 0;
    m_gcdIndex = -1;
    m_x = 0;
    m_y = 0;
    m_valid = false;
}

void ExgcdModule::releaseSceneItems() {
    m_rows.clear();
    m_chain.clear();
    m_backSteps.clear();
    clearLayoutBlocks();
    m_mathText = nullptr;
}

