void ExgcdModule::computeChain() {
    m_rows.clear();
    m_chain.clear();

    long long r0 = m_b;
    long long r1 = m_a;
    m_chain.push_back(r0);
    m_chain.push_back(r1);
    while (r1 != 0) {
        const long long q = r0 / r1;
        const long long r2 = r0 % r1;
        ExgcdStepRow row;
        row.dividend = r0;
        row.divisor = r1;
        row.quotient = q;
        row.remainder = r2;
        m_rows.push_back(row);
        m_chain.push_back(r2);
        r0 = r1;
        r1 = r2;
    }
    m_gcdIndex = static_cast<int>(m_chain.size()) - 2;
    m_gcd = m_chain[m_gcdIndex];
}

QString ExgcdModule::termText(int index, long long coef, int substIndex) const {
    const long long value = (index >= 0 && index < static_cast<int>(m_chain.size()))
                                ? m_chain[index] : 0;
    QString body;
    if (index == substIndex && index >= 2) {
        const long long outer = m_chain[index - 2];
        const long long inner = m_chain[index - 1];
        const long long q = m_rows[index - 2].quotient;
        body = QString("(%1 - %2 × %3)").arg(outer).arg(q).arg(inner);
    } else {
        body = QString::number(value);
    }
    return QString("%1 × %2").arg(coef).arg(body);
}

QString ExgcdModule::renderCoefs(const std::map<int, long long>& coefs, int substIndex) const {
    std::vector<std::pair<int, long long>> pos;
    std::vector<std::pair<int, long long>> neg;
    for (const auto& kv : coefs) {
        if (kv.second == 0) continue;
        if (kv.first == substIndex) continue;
        if (kv.second > 0) pos.push_back(kv);
        else neg.push_back(kv);
    }
    auto byIndexDesc = [](const std::pair<int, long long>& a,
                          const std::pair<int, long long>& b) { return a.first > b.first; };
    std::sort(pos.begin(), pos.end(), byIndexDesc);
    std::sort(neg.begin(), neg.end(), byIndexDesc);

    QStringList parts;
    if (substIndex >= 0) {
        const long long coef = coefs.count(substIndex) ? coefs.at(substIndex) : 0;
        if (coef != 0) parts << termText(substIndex, coef, substIndex);
    }
    for (const auto& kv : pos) parts << termText(kv.first, kv.second, -1);
    for (const auto& kv : neg) parts << termText(kv.first, kv.second, -1);
    if (parts.isEmpty()) return "0";

    QString out = parts.first();
    for (int i = 1; i < parts.size(); ++i) {
        if (parts[i].startsWith("-")) out += " " + parts[i];
        else out += " + " + parts[i];
    }
    return out;
}

void ExgcdModule::buildBackSteps() {
    m_backSteps.clear();

    std::map<int, long long> coefs;
    coefs[m_gcdIndex] = 1;

    for (int j = m_gcdIndex; j >= 2; --j) {
        auto it = coefs.find(j);
        if (it == coefs.end() || it->second == 0) continue;

        const long long coef = it->second;
        const long long q = m_rows[j - 2].quotient;
        const long long coefPrev = coefs.count(j - 1) ? coefs.at(j - 1) : 0;

        ExgcdBackStep step;
        step.substituted = renderCoefs(coefs, j);

        coefs[j - 1] = coefPrev - coef * q;
        coefs[j - 2] += coef;
        coefs[j] = 0;

        step.simplified = renderCoefs(coefs, -1);
        step.lhs = step.substituted;
        step.rhs = step.simplified;
        m_backSteps.push_back(step);
    }

    m_x = coefs.count(1) ? coefs.at(1) : 0;
    m_y = coefs.count(0) ? -coefs.at(0) : 0;
}

