void ExgcdModule::computeChain() {
    m_rows.clear();
    m_chain.clear();

    long long r0 = m_b;
    long long r1 = m_a;
    m_chain.push_back(r0);
    m_chain.push_back(r1);
    while (r1 != 0) {
        const long long q = r0 / r1;
        const long long r2 = r0 % r1;
        ExgcdStepRow row;
        row.dividend = r0;
        row.divisor = r1;
        row.quotient = q;
        row.remainder = r2;
        m_rows.push_back(row);
        m_chain.push_back(r2);
        r0 = r1;
        r1 = r2;
    }
    m_gcdIndex = static_cast<int>(m_chain.size()) - 2;
    m_gcd = m_chain[m_gcdIndex];
}

QString ExgcdModule::termBody(int index, int substIndex, bool withParens) const {
    const long long value = (index >= 0 && index < static_cast<int>(m_chain.size()))
                                ? m_chain[index] : 0;
    if (substIndex >= 0 && index == substIndex && withParens) {
        const long long q = m_rows[index - 2].quotient;
        return QString("(%1 - %2 × %3)")
            .arg(m_chain[index - 2]).arg(q).arg(m_chain[index - 1]);
    }
    return QString::number(value);
}

QString ExgcdModule::termWithCoef(long long coef, const QString& body) const {
    if (coef == 1) return body;
    if (coef == -1) return QString("-%1").arg(body);
    return QString("%1 × %2").arg(coef).arg(body);
}

QString ExgcdModule::renderCoefs(const std::vector<std::pair<int, long long>>& slots,
                                 int substIndex) const {
    QStringList parts;
    for (const auto& slot : slots) {
        if (slot.second == 0) continue;
        const QString body = termBody(slot.first, substIndex, true);
        parts << termWithCoef(slot.second, body);
    }
    if (parts.isEmpty()) return "0";

    QString out;
    for (int i = 0; i < parts.size(); ++i) {
        if (i == 0) {
            out = parts[i];
            continue;
        }
        if (parts[i].startsWith("-")) out += QString(" %1").arg(parts[i]);
        else out += QString(" + %1").arg(parts[i]);
    }
    return out;
}

void ExgcdModule::buildBackSteps() {
    m_backSteps.clear();

    std::vector<std::pair<int, long long>> slots;
    slots.push_back({m_gcdIndex, 1});

    while (true) {
        int top = -1;
        for (const auto& slot : slots) {
            if (slot.second == 0) continue;
            if (top < 0 || slot.first > top) top = slot.first;
        }
        if (top < 2) break;

        const long long coef = [&slots, top]() {
            for (const auto& slot : slots) {
                if (slot.first == top) return slot.second;
            }
            return 0LL;
        }();

        const long long q = m_rows[top - 2].quotient;

        ExgcdBackStep step;
        step.sourceRow = top - 2;
        step.substituted = renderCoefs(slots, top);

        std::vector<std::pair<int, long long>> next;
        bool replaced = false;
        for (const auto& slot : slots) {
            if (slot.first == top) {
                next.push_back({top - 2, slot.second});
                next.push_back({top - 1, -slot.second * q});
                replaced = true;
                continue;
            }
            next.push_back(slot);
        }
        Q_UNUSED(coef);

        std::vector<std::pair<int, long long>> merged;
        for (const auto& slot : next) {
            if (slot.second == 0) continue;
            bool found = false;
            for (auto& target : merged) {
                if (target.first == slot.first) {
                    target.second += slot.second;
                    found = true;
                    break;
                }
            }
            if (!found) merged.push_back(slot);
        }
        slots = merged;

        step.simplified = renderCoefs(slots, -1);
        m_backSteps.push_back(step);
    }

    m_x = 0;
    m_y = 0;
    for (const auto& slot : slots) {
        if (slot.first == 1) m_x = slot.second;
        if (slot.first == 0) m_y = slot.second;
    }
}

