void ExgcdModule::computeChain() {
    m_rows.clear();
    m_chain.clear();

    long long r0 = m_b;
    long long r1 = m_a;
    m_chain.push_back(r0);
    m_chain.push_back(r1);
    while (r1 != 0) {
        const long long q = r0 / r1;
        const long long r2 = r0 % r1;
        ExgcdStepRow row;
        row.dividend = r0;
        row.divisor = r1;
        row.quotient = q;
        row.remainder = r2;
        m_rows.push_back(row);
        m_chain.push_back(r2);
        r0 = r1;
        r1 = r2;
    }
    m_gcdIndex = static_cast<int>(m_chain.size()) - 2;
    m_gcd = m_chain[m_gcdIndex];
}

QString ExgcdModule::renderTerms(const std::vector<ExgcdTerm>& terms, int substIndex,
                                 bool omitUnitCoef) const {
    QString out;
    bool first = true;
    for (const ExgcdTerm& t : terms) {
        if (t.coef == 0) continue;
        QString body;
        if (substIndex >= 0 && t.index == substIndex && t.index >= 2) {
            body = QString("(%1 - %2 × %3)")
                       .arg(m_chain[t.index - 2])
                       .arg(m_rows[t.index - 2].quotient)
                       .arg(m_chain[t.index - 1]);
        } else if (t.index >= 0 && t.index < static_cast<int>(m_chain.size())) {
            body = QString::number(m_chain[t.index]);
        } else {
            continue;
        }
        const QString absCoef = QString::number(qAbs(t.coef));
        const QString term = (omitUnitCoef && qAbs(t.coef) == 1)
                                ? body
                                : QString("%1 × %2").arg(absCoef, body);
        if (first) {
            out = (t.coef < 0) ? QString("-%1").arg(term) : term;
            first = false;
            continue;
        }
        out += (t.coef < 0) ? QString(" - %1").arg(term) : QString(" + %1").arg(term);
    }
    if (first) return "0";
    return out;
}

void ExgcdModule::buildBackSteps() {
    m_backSteps.clear();

    std::vector<ExgcdTerm> terms;
    terms.push_back({m_gcdIndex, 1});

    while (true) {
        int top = -1;
        long long coef = 0;
        for (const ExgcdTerm& t : terms) {
            if (t.coef == 0) continue;
            if (t.index > top) {
                top = t.index;
                coef = t.coef;
            }
        }
        if (top < 2) break;

        const long long q = m_rows[top - 2].quotient;

        ExgcdBackStep step;
        step.sourceRow = top - 2;
        step.substituted = renderTerms(terms, top, true);

        std::vector<ExgcdTerm> next;
        for (const ExgcdTerm& t : terms) {
            if (t.index == top) {
                next.push_back({top - 2, t.coef});
                next.push_back({top - 1, -t.coef * q});
                continue;
            }
            next.push_back(t);
        }

        std::vector<ExgcdTerm> merged;
        for (const ExgcdTerm& t : next) {
            if (t.coef == 0) continue;
            bool found = false;
            for (ExgcdTerm& m : merged) {
                if (m.index == t.index) {
                    m.coef += t.coef;
                    found = true;
                    break;
                }
            }
            if (!found) merged.push_back(t);
        }
        std::vector<ExgcdTerm> cleaned;
        for (const ExgcdTerm& t : merged) {
            if (t.coef == 0) continue;
            cleaned.push_back(t);
        }
        terms = cleaned;

        step.simplified = renderTerms(terms, -1, false);
        m_backSteps.push_back(step);
    }

    m_x = 0;
    m_y = 0;
    for (const ExgcdTerm& t : terms) {
        if (t.index == 1) m_x = t.coef;
        if (t.index == 0) m_y = -t.coef;
    }
}

